
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @unresolved INT;
BEGIN TRANSACTION;

;WITH raw AS (
    SELECT * FROM (VALUES
        (N'DSE-DISC-01', N'WF-X-DISC-01', N'DSE-DISC', N'PH-DSE-DISC-EXPL', 1, N'Find out who has already spoken to this customer', N'Establish what is already known about the estate and who holds the rest, before you take a single question to the customer.', N'Featured', N'Both', N'For [account name], show me what is already recorded about their technical estate: the products and workloads in place and when they were deployed, any open support or delivery issue, the opportunities open and what they are for, every recorded activity and which role it came from, and whether a partner or co-sell record exists on the account. Report only what the record contains. Do not describe what any partner has done - that is not in MSX.', N'1. Open Sales Agent and paste the prompt with your customer.
2. Read the activity list by role. Whoever has been active is the person who knows what is not written down.
3. If a partner record exists, check the Partner Timeline view or Partner Center - the partner may have run discovery of their own.
4. Write down what the record answers, and what it only appears to answer.', N'One customer where you are about to start technical discovery.', N'What the record already establishes about the estate, and the named colleagues or partners likely holding the rest.', N'The DSE decides what the record genuinely establishes versus what it merely mentions. A workload appearing in the record says it was bought rather than how it was configured, and the configuration is what you will be held to when you design against it.', N'Prior discovery', N'At this customer count you are arriving after a partner and a seller have both already been there. Starting from what they found is faster than starting again and does not spend the customer''s patience.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-DISC-02', N'WF-X-DISC-01', N'DSE-DISC', N'PH-DSE-DISC-EXPL', 2, N'Test your criteria against what they already run', N'Check draft decision criteria against the customer''s recorded estate, and work out which ones a partner would have to satisfy.', N'Featured', N'Both', N'Here are the technical decision criteria I am proposing for [account name]: [paste your draft criteria]. Show me what that customer has deployed today and, for each criterion, whether anything in the record bears on it - an existing workload, an open support issue, a prior opportunity - or whether the record says nothing. Do not assess technical effort or judge whether a criterion is reasonable. I want to know which of these the record can already speak to.', N'1. Draft your criteria first. This is your judgment, not the agent''s.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Criteria the record says nothing about are the ones you will have to establish with the customer or the partner.
4. Mark which of those a delivery partner would have to satisfy rather than you.
5. Agree the surviving set with the DAE before it reaches the customer.', N'Your draft technical decision criteria, and the customer they are for.', N'Your criteria split by whether the record already speaks to them, with the partner-satisfied ones marked.', N'The DSE writes the criteria and decides which a partner could realistically meet. A criterion only the engineer can satisfy quietly commits you to every future deal of that shape, and at this customer count that is a commitment you cannot keep.', N'Decision criteria', N'Criteria written for yourself do not survive being handed to a delivery partner. Checking them against what the customer already runs is the cheap part; deciding who can meet them is the part that matters.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-DISC-03', N'WF-X-DISC-01', N'DSE-DISC', N'PH-DSE-DISC-EXPL', 3, N'Find where the technical record has gone quiet', N'Rank the technical record by how long each part of it has gone without an update, then decide what you still have to verify yourself.', N'Extended', N'Both', N'For [account name], show me how current the technical record actually is. For each deployed product and workload give the date it was last updated, list any open support or service record with the date it last moved, and name the areas where nothing has been logged in the last [number] months. Sort by longest silence first, and lead with the gaps rather than a full inventory of the estate.', N'1. Open Sales Agent, paste the prompt, and replace both bracketed sections - the account and the number of months you want checked.
2. Read the dates, not just the facts. Silence is not evidence either way: it means no entry was found in MSX for that period, not that nothing happened or that nobody recorded it somewhere you cannot see.
3. Now do the part the agent cannot: decide which of these facts you will confirm with a person before you design against them, and which are safe to take as read.', N'The customer, and how far back you want the currency check to run.', N'The technical record ranked by how long each part of it has gone untouched, with anything showing no entry inside the chosen period named separately.', N'The DSE owns the design and therefore decides which recorded facts are safe to build on. A fact nobody has touched in a long time is not necessarily wrong, and the difference between an inaccuracy caught at design time and one found in production is entirely a matter of which fact it was.', N'Verification', N'You cannot verify everything at this customer count. The record will not tell you what is true, but it will tell you which facts are fresh and which have gone untouched long enough to be worth checking before you design against them.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PROOF-01', N'WF-X-ARCH-01', N'DSE-PROOF', N'PH-DSE-PROOF-EXPL', 1, N'Look for the proof before you build one', N'Check whether you or a colleague have already proven this, at a customer with a comparable estate.', N'Featured', N'Both', N'I need to prove [describe what the customer doubts] for a customer running [describe their estate]. Across the opportunities in my patch, show me any where a similar workload or configuration was involved, what stage they reached, and any recorded notes, objections or outcomes. For each, show what the customer environment looked like. Do not assume a similar environment means the same proof will transfer.', N'1. Open Sales Agent, paste the prompt, and replace both bracketed sections.
2. Look for the closest environment rather than the closest product name.
3. If something transfers, find out who ran it before rebuilding it.
4. If nothing transfers, you now know why this one is genuinely new.', N'The technical doubt to be settled, and the customer''s environment as you understand it.', N'Comparable prior work identified with an honest read on whether it transfers, or a clear statement that this proof is genuinely new.', N'The DSE judges whether a prior proof actually transfers. Two customers on the same product can differ in the one respect the proof depended on, and a borrowed proof that quietly does not apply is worse than building a new one, because nobody re-examines it.', N'Reuse', N'A bespoke proof for every customer does not survive the customer count in this segment. Reuse is the constraint that makes the job possible, and it only works if somebody looks first.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PROOF-02', N'WF-X-ARCH-01', N'DSE-PROOF', N'PH-DSE-PROOF-EXPL', 2, N'Cut your proof down before you build it', N'State the proof you are considering, then test it against what comparable customers actually needed.', N'Featured', N'Both', N'A customer at [account name] is unsure about [describe the doubt]. I am considering this proof: [describe the proof you have in mind]. Across the opportunities in my patch, show me any where a similar doubt or objection was recorded, what was proposed, what stage the opportunity reached, and any note about what convinced the customer. Do not design a proof or judge whether mine is the right size.', N'1. Write down the proof you have in mind first, including what it will not cover. That scoping is yours.
2. Open Sales Agent, paste the prompt, and replace all three bracketed sections.
3. Look at what actually convinced comparable customers. It is frequently smaller than what was offered.
4. Cut yours to the smallest version that still settles the doubt, and write down explicitly what it excludes.
5. Get the customer to agree that this settles it, before you build anything.', N'The customer, what they are unsure about, and the proof you are considering including its exclusions.', N'Your proposed proof tested against what comparable customers actually needed, cut to the smallest sufficient version with exclusions stated.', N'The DSE decides what the customer is really doubting, which is frequently not what they asked to see. A request for a pilot is often a request for reassurance about operational effort, and building the pilot answers a question nobody had while leaving the real one open.', N'Proof scope', N'Proof work expands to fill whatever time it is given, and at this customer count that time comes straight out of another customer. What convinced somebody comparable is the cheapest available check on your own scoping.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PROOF-03', N'WF-X-ARCH-01', N'DSE-PROOF', N'PH-DSE-PROOF-EXPL', 3, N'Leave it in a state the next engineer can use', N'Spend the extra hour that makes this proof reusable, rather than rebuilding it from memory next quarter.', N'Extended', N'Both', N'I have built a proof demonstrating [describe what it shows] for a customer running [describe the environment]. Help me write it up so another engineer could reuse it: what it demonstrates, what environment it assumes, what it deliberately does not cover, what would have to change for a different customer, and what someone should check before reusing it. Write it for an engineer who was not involved. Do not include the customer name, contact details, or anything identifying them.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Read the assumptions section as somebody who was not there. Anything implicit will be missed.
3. Remove anything identifying the customer.
4. Put it where your colleagues will actually find it, and tell the ones covering similar estates.', N'The proof you built, what it demonstrates, and the environment it assumed.', N'A reuse note covering what the proof shows, what it assumes, what it excludes, and what to check before reusing it, with the customer anonymized.', N'The DSE states what the proof deliberately does not cover. A reuse note that lists only capabilities gets applied to a situation it was never valid for, and the engineer who inherits the failure will not know which assumption broke.', N'Reusability', N'Reuse only works if somebody wrote down the limits. The capabilities are obvious from the artifact; the boundaries exist only in the head of whoever built it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-CONV-01', N'WF-X-CONV-01', N'DSE-CONV', N'PH-DSE-CONV-EXPL', 1, N'Work out what was actually asked', N'Reconstruct the customer''s real question from the version that reached you second-hand.', N'Featured', N'Both', N'A technical question has reached me through a partner or seller. Here is how it was relayed: [paste the question as you received it]. It concerns [account name]. Using what is recorded about that customer''s estate, help me work out what they might actually be asking. Give the most likely readings, what each would imply about their concern, and the single clarifying question that would tell them apart. Do not answer the question yet.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Read the alternative readings against what the customer actually runs.
3. If two readings need completely different answers, ask the clarifying question before answering.
4. Answering the wrong reading confidently costs more than the delay of asking.', N'The relayed question as you received it, and the customer it concerns.', N'The plausible readings of the question with the one clarifying question that would resolve them.', N'The DSE decides whether to answer or to ask. A relayed question has already lost the tone and the follow-up that would have disambiguated it, and answering the wrong reading with confidence is how a technically correct answer becomes a customer problem.', N'Relayed question', N'You are not in the room in this segment, so every question arrives already translated once. Treating the relayed wording as the actual question is how engineers give confidently wrong answers.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-CONV-02', N'WF-X-CONV-01', N'DSE-CONV', N'PH-DSE-CONV-EXPL', 2, N'Write an answer that survives being forwarded', N'Produce a technical answer for the person who will relay it, not for a technical peer.', N'Featured', N'Both', N'Here is a technical question about [account name]: [state the question you have established]. Here is my answer: [paste your answer in your own words]. Rewrite it for a partner or seller who will relay it to the customer and who is not a specialist in this area. Lead with the direct answer, then the conditions it depends on. Keep every qualification I have written - do not simplify one away. Mark clearly which parts must be passed on word for word and which can be summarized. Do not add technical claims I have not made.', N'1. Write your answer first, in your own words. The technical content is yours.
2. Open Cowork, paste the prompt, and replace all three bracketed sections.
3. Check nothing has been added that you did not say, and no qualification has been softened.
4. Read it as the relayer. If a sentence needs you present to make sense, rewrite it.
5. Check the word-for-word section is genuinely short - if everything is marked critical, nothing is.
6. Check it against the CELA rules before it goes to a partner: no personal data, no seat or spend detail, nothing resembling an export.', N'The question you have established, your own technical answer, and the account. The CELA rules on partner data exchange.', N'Your answer rewritten for relay, with qualifications intact, the must-not-paraphrase parts marked, and the data-sharing boundary checked.', N'The DSE writes the technical answer and checks that nothing was added or softened in the rewrite. A model asked to make an answer clearer will drop the qualification that made it accurate, and the person relaying it has no way to know a sentence went missing.', N'Relay-safe answer', N'An answer written for a technical peer gets compressed by whoever passes it on, and the part they drop is the qualification. Having it rewritten for the relayer is useful; letting it be written from scratch is how a confident wrong answer reaches a customer.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-CONV-03', N'WF-X-CONV-01', N'DSE-CONV', N'PH-DSE-CONV-EXPL', 3, N'Work out what is not yours to answer', N'Identify the parts of a technical question that belong to product, legal, security or commercial owners, and route them.', N'Extended', N'Both', N'Here is a technical question I have been asked about [account name]: [state the question]. Break it into its separate parts and, for each, say whether answering it needs current product behavior, an unreleased or roadmap capability, licensing or commercial terms, or a security, legal or compliance position. Do not answer any part and do not suggest who should own it.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. You route these, not the agent. Licensing and commercial go to your CE; security and compliance to the authoritative owner.
3. Anything touching roadmap goes nowhere near a customer until it has shipped.
4. Answer your part fully and name who is picking up the rest, so the question does not stall.', N'The technical question and the account it concerns. Your CE for anything commercial, and the authoritative owner for security or compliance.', N'The question split by the kind of answer each part needs, with your portion answered and the rest routed by you to a named owner.', N'The DSE answers the technical part and routes the rest rather than being helpful across the boundary. An engineer''s answer about licensing or a roadmap date is read as authoritative because it came from the technical person, and it is repeated long after it stops being true.', N'Answer boundary', N'A relayed question arrives as one question and unpacks into several. Splitting it is what stops an engineer accidentally giving a commercial commitment.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DSE-HEALTH-01', N'WF-X-HEALTH-01', N'DSE-HEALTH', N'PH-DSE-HEALTH-EXPL', 1, N'Find who else is running the thing you know breaks', N'Take a problem you have already met and find the other customers exposed to it.', N'Featured', N'Both', N'I have found a technical problem at one customer: [describe the configuration or workload and what goes wrong]. Across the accounts in my patch, show me which others have the same workload or product combination deployed, with what is recorded about their deployment and any open support issue. Do not conclude that a matching product list means the same problem is present.', N'1. Open Sales Agent and paste the prompt with your problem described.
2. Treat the output as a list of customers to check, not a list of customers affected.
3. Narrow it using what you know about the configurations rather than the product names.
4. Order the survivors by how visible the failure would be to the customer.', N'A technical problem you have already diagnosed at one customer. The accounts in your patch.', N'The customers plausibly exposed to the same problem, narrowed by configuration rather than product match, and ordered by customer-visible impact.', N'The DSE decides which matches are genuinely exposed. A product list is not a configuration, and two deployments that share a product name can differ in exactly the setting that determines whether the problem occurs.', N'Pattern exposure', N'You do not operate any of these environments and there are too many to inspect. The only scalable way to find a problem before the customer does is to already know its shape.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-HEALTH-02', N'WF-X-HEALTH-01', N'DSE-HEALTH', N'PH-DSE-HEALTH-EXPL', 2, N'Check whether the problem is already being worked', N'Find out whether an exposed customer already has a support issue open on the problem, before you warn anyone about it.', N'Featured', N'Both', N'For these customers [list the exposed accounts], show every support or service issue recorded in the last six months: what it concerns, when it was raised, its current status, and whether it has been resolved. Show the deployed workloads alongside so I can see which issues touch the configuration I am worried about. Report only what is recorded and do not judge whether any issue relates to my problem.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list.
2. Read the open issues first. An issue already raised on the same workload means somebody found this before you.
3. A resolved issue on the same configuration is worth reading too - it may be the fix you were about to describe.
4. Only for accounts with nothing recorded should you check the Partner Timeline view, since a partner may be working it outside our systems.
5. Warn only the customers where nobody appears to be on it.', N'Your list of exposed customers from the previous activity.', N'The exposed customers split by whether an issue is already open, already resolved, or nothing is recorded at all.', N'The DSE decides whether an existing issue is actually the same problem. Support records describe a symptom in the customer''s words rather than the cause in yours, and a ticket that looks unrelated is often the same fault reported by someone who did not know what they were seeing.', N'Partner awareness', N'Most of these environments are operated by somebody else, so a problem you have just spotted has often already been raised by the people living with it. Warning them about it costs you standing you will need later.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-HEALTH-03', N'WF-X-HEALTH-01', N'DSE-HEALTH', N'PH-DSE-HEALTH-EXPL', 3, N'Send the fix to whoever can actually apply it', N'Write the problem up so the person who operates the solution can act on it without needing you.', N'Extended', N'Both', N'I need to tell the people operating a solution about this problem: [describe the problem, the trigger, and the fix]. Draft a short technical note for whoever operates the environment: what the symptom looks like, what causes it, how to confirm whether they are affected, and what to do about it. Write it for a competent engineer who was not involved in the original design. Keep it to what is technically necessary and exclude customer names, personal data, seat counts and spend figures.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check the confirm-whether-affected step is something they can actually run themselves.
3. Remove anything a partner should not receive under the CELA rules.
4. Send it, and record where you sent it so this does not come back to you as new in three months.', N'The problem, its trigger and its fix. The partners or customer teams operating the affected environments. The CELA rules on partner data exchange.', N'A technical note the operating team can act on unaided, with the check they can run themselves and the customer detail removed.', N'The DSE decides whether the note is genuinely actionable by somebody who was not there, and checks it against the data rules before it goes to a partner. A problem report that requires the author to explain it will sit unactioned, and the customer will find the problem first.', N'Routing the fix', N'You are not going to fix these yourself across this many customers. The work is making the fix travel, and a note that needs you attached to it does not travel.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-PART-01', N'WF-X-PARTNER-01', N'DCSA-PARTNER', N'PH-DCSA-PARTNER-EXPL', 1, N'Find out what is actually behind each account', N'Establish which accounts have a delivery partner genuinely engaged and which have a support agreement, because on these accounts one of those may be all there is.', N'Featured', N'Both', N'For these accounts [list up to fifteen accounts from your portfolio], show two things. First, whether any support or services agreement is recorded on the account, and of what kind. Second, whether a partner is associated, with any co-sell or referral record and its recorded status and dates. Report only what the record contains and do not describe what any partner is doing or infer what support entitlement implies.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list with up to fifteen of your accounts.
2. Read the support agreement column first. An account with neither an agreement nor an engaged partner has nothing behind it at all.
3. An association is not an engagement - check the dates before assuming anyone is active.
4. For anything that looks live, open the Partner Timeline view or Partner Center; partner-side progress is only visible there.
5. Rank by what would happen at each account if something broke tomorrow.', N'Up to fifteen accounts from your portfolio.', N'Your accounts sorted by what is actually behind them: an agreement, an engaged partner, both, or nothing.', N'The DCSA decides what counts as an engaged partner and what an absent agreement really means for a given account. A referral accepted eight months ago and a partner deploying this week look identical in our record, and an account with neither is one where your own time is the entire coverage.', N'Partner engagement', N'At this coverage ratio you are not the delivery mechanism, the agreement or the partner is. Knowing which accounts have neither tells you where a problem becomes yours by default.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-PART-02', N'WF-X-PARTNER-01', N'DCSA-PARTNER', N'PH-DCSA-PARTNER-EXPL', 2, N'Write a handover the partner can act on without you', N'Turn your own technical assessment into something a partner engineer can execute, inside the rules that govern what may be shared.', N'Featured', N'Both', N'I need to hand technical work to a delivery partner at [account name]. Here is my assessment and what I want done: [paste your own technical assessment and the work required]. Restructure this for a competent engineer at the partner who was not in any of my conversations: what the situation is, what needs doing, what order, and what they should check to confirm it worked. Do not add technical steps or recommendations I have not written. Exclude contact names and details, seat counts, spend figures, and anything that reads as an export from our systems.', N'1. Write your technical assessment and the required work first. That content is yours.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Check nothing technical has been added that you did not write.
4. Read it as the partner engineer. Anything that assumes a conversation they were not in has to be spelled out.
5. Check it against the CELA rules before sending: no personal data, no seat or spend detail, nothing resembling an export.', N'One account, and your own technical assessment of what needs doing. The CELA rules on partner data exchange.', N'A partner-executable technical handover derived from your own assessment, checked for added content and for the data-sharing boundary.', N'The DCSA owns the technical content and confirms nothing was invented in the restructuring, then checks it against the data rules before it goes out. A partner engineer will execute what is written without knowing which line came from you and which was generated to make the sequence read well.', N'Technical handover', N'Without a Unified agreement there is no delivery manager to interpret your intent. The handover is the whole intervention, and if it needs you attached to it, nothing happens.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-PART-03', N'WF-X-PARTNER-01', N'DCSA-PARTNER', N'PH-DCSA-PARTNER-EXPL', 3, N'Decide how you will know it worked', N'Name the observable signal that would tell you the partner''s work landed, before you stop thinking about the account.', N'Extended', N'Both', N'I have handed technical work to a partner at [account name]. The intended technical outcome is [describe what should change if it worked]. Show me what is currently recorded for that account that relates to it: deployed workloads, open or resolved support issues, recorded activity, and any usage or consumption figures held in the record. Show the current state only. Do not project what should happen or judge whether the work will succeed.', N'1. Open Sales Agent, paste the prompt, and replace both bracketed sections.
2. Take this as your baseline and write it down with today''s date.
3. Decide which single observable would change if the work landed, and by when you would expect it.
4. Put that check in your calendar. Nothing else in the week will surface it.
5. If the observable is not visible in any record you can reach, you need the partner to report it - agree that now, not later.', N'One account with work handed to a partner, and your own definition of what would change if it succeeded.', N'A dated baseline of what is currently recorded, with one observable signal and a date to check it.', N'The DCSA defines what would count as success and whether it is observable at all. Some technical outcomes leave no trace in any system we can see, and finding that out now rather than in three months is the difference between a check you can run and a hope.', N'Verification', N'Work handed to a partner without a check is work you have stopped tracking. At this account count nothing will bring it back to your attention until the customer escalates.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-CONV-01', N'WF-X-CONV-01', N'DCSA-CONV', N'PH-DCSA-CONV-EXPL', 1, N'Pick the one thing worth their attention', N'Assemble what is known about the account and choose the single technical priority, on the assumption you get one conversation.', N'Featured', N'Both', N'For [account name], show me what is recorded: the products and workloads deployed and when, any open or recently resolved support issue, any usage or consumption figures held in the record, recent activity and which role it came from, and whether a partner is associated. Present it as a factual summary. Do not rank the findings by importance or recommend what to focus on.', N'1. Open Sales Agent and paste the prompt with your account.
2. Read it for what is missing as much as for what is there.
3. Now do the part the agent cannot: decide the single technical thing that most needs to be right at this customer.
4. Build the conversation around that one thing and let the rest go.', N'One customer with a technical conversation coming up.', N'A factual account summary, with your own decision on the single technical priority for the conversation.', N'The DCSA chooses the priority. The record shows what was bought and what has broken, but which risk actually matters for this customer depends on what they are trying to do, and a summary that ranks findings would be ranking them on the wrong criteria.', N'Single priority', N'With one conversation available, covering everything means the customer leaves with nothing. Choosing is the work, and it is not something the record can do for you.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-CONV-02', N'WF-X-CONV-01', N'DCSA-CONV', N'PH-DCSA-CONV-EXPL', 2, N'Leave something behind that works without you', N'Turn your technical guidance into a short written artifact the customer or their partner can act on after you have moved on.', N'Featured', N'Both', N'I am advising [account name] on [state the priority you have chosen]. Here is my guidance in my own words: [paste your guidance]. Turn it into a short written note for the customer''s own technical people and whoever supports them, covering what to do, in what order, what to check afterwards, and what would indicate it is going wrong. Do not add recommendations I have not written. Keep it to one page and write it for someone who was not in the conversation.', N'1. Write your guidance first, in your own words. The technical judgment is yours.
2. Open Cowork, paste the prompt, and replace all three bracketed sections.
3. Check nothing has been added, and that no caveat you wrote has been smoothed away.
4. Test it against the question: could they follow this in three months with you unavailable?
5. Send it to the customer and, if a partner supports them, to the partner as well.', N'One customer, your chosen technical priority, and your own guidance written out.', N'A one-page durable note the customer or their partner can act on without you, derived from your own guidance.', N'The DCSA owns the guidance and confirms nothing was added in the rewrite. Advice that gets acted on months later with nobody available to interpret it has to be right as written, and a generated clarification that changes the meaning will not be caught by the person following it.', N'Durable guidance', N'At this coverage the value you leave is more durable than the value you deliver in the room. A conversation with nothing written down is gone the week after.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-CONV-03', N'WF-X-CONV-01', N'DCSA-CONV', N'PH-DCSA-CONV-EXPL', 3, N'Name who has this account after you', N'Establish which Microsoft roles have been active recently and who realistically holds the technical relationship next.', N'Extended', N'Both', N'For [account name], list every recorded activity in the last six months with the date and the role it came from, and show any open support issue with its recorded owner. Show the roles by how recently each was active. Do not include partner or co-sell records, and do not infer who is responsible for the account technically.', N'1. Open Sales Agent and paste the prompt with your account.
2. If the only recent activity is yours, that is the finding.
3. Decide who realistically holds this next - the DAE, a partner you already identified, or nobody - and be honest about the last option.
4. Tell them, and tell the customer who to contact. An unnamed successor is the same as none.', N'One customer you are unlikely to revisit soon.', N'The Microsoft roles active on the account ordered by recency, with a named technical successor or an explicit acknowledgement that there is not one.', N'The DCSA decides who genuinely picks this up, including the honest answer that nobody does. Naming a successor who has not agreed is worse than admitting the gap, because the customer will call someone who is not expecting them.', N'Succession', N'Accounts at this coverage ratio quietly lose their technical contact and nobody notices until something breaks. Saying out loud that there is no successor is what turns it into a decision somebody can make.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-VALUE-01', N'WF-X-VALUE-01', N'DCSA-VALUE', N'PH-DCSA-VALUE-EXPL', 1, N'Work out which accounts left any trace of delivery', N'Establish which of your accounts have a delivery record behind them and which have nothing but telemetry, because that determines what you can ever evidence.', N'Featured', N'Both', N'For these accounts [list up to fifteen accounts where you believe the technical outcome was good], show for each whether a support or services agreement is recorded, any support issue raised and how it was resolved, any milestone or success activity logged, and any usage or consumption figures held in the record. Separate the accounts that produced some record of delivery work from those where the only thing recorded is the purchase and whatever usage figures exist. Do not infer an outcome from deployment or from usage.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list.
2. The accounts with no delivery record are the normal case here, not the failures. That is what non-Unified looks like.
3. For those, usage figures are the only evidence that will ever exist, so decide now whether they say anything useful.
4. For the accounts that did produce a record, check whether the work recorded is actually connected to the outcome you have in mind.
5. Pick the account with the strongest case and carry it into the attribution step.', N'Up to fifteen accounts where you believe the technical outcome was good.', N'Your accounts split by whether any delivery record exists, with an explicit read on what can be evidenced for those where none does.', N'The DCSA decides whether usage figures alone amount to evidence of an outcome. On an account with no delivery record they are all there is, and consumption showing a service running is a much weaker claim than a customer saying it solved something.', N'Evidence base', N'A Unified engagement leaves milestones and hours behind it. Most of these accounts leave nothing, so knowing which ones produced any record at all tells you where a value story is even possible before somebody asks you for one.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-VALUE-02', N'WF-X-VALUE-01', N'DCSA-VALUE', N'PH-DCSA-VALUE-EXPL', 2, N'Separate what you did from what the partner did', N'Establish who actually performed the delivery work, so that outcomes are described by whoever earned them.', N'Featured', N'Both', N'For these accounts [list your evidenced accounts], show what the record says about work performed: each recorded activity with its date and the role it came from, each support issue with who logged it and who resolved it, and the dates workloads were deployed. Report the recorded actors only. Do not infer who was responsible for any outcome and do not summarize contribution.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list.
2. Our record captures what Microsoft logged. On a partner-delivered account that is a fraction of what happened, and the gaps are the partner''s work.
3. Where a partner delivered, the outcome is theirs to describe and yours to acknowledge.
4. If you want to use a partner-delivered outcome, ask them rather than reconstructing it from our record.', N'Your evidenced accounts from the previous activity.', N'Recorded delivery work attributed by actor, with the partner-delivered outcomes identified as theirs to describe.', N'The DCSA decides what is honestly ours to claim. Our record shows what Microsoft logged, which on a partner-delivered account is a small fraction of what happened, and presenting that fraction as the whole story is visible to the partner immediately.', N'Attribution', N'On non-Unified accounts the partner may have done most of the delivery. Getting attribution right is not politeness, it is the thing that keeps the partner willing to do it again.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-VALUE-03', N'WF-X-VALUE-01', N'DCSA-VALUE', N'PH-DCSA-VALUE-EXPL', 3, N'Get the evidence to whoever owns the renewal', N'Pass the technical evidence to the account and commercial roles before the renewal conversation happens without it.', N'Extended', N'Both', N'For [account name], I have technical evidence of the outcome delivered. Here is what I can evidence: [paste what you established]. Draft a short internal note for the account executive and the commercial executive covering what was delivered, what the evidence is, what the partner contributed, and what remains unproven. Keep it brief and factual. Do not add claims I have not made and do not characterize the commercial implications.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check nothing has been added, particularly anything that reads as a commercial recommendation.
3. Say plainly what remains unproven. A note that only lists wins is discounted by whoever reads it.
4. Send it to the DAE and the CE, and note the renewal date so you know whether it arrived in time.', N'One account with evidenced technical outcomes, your own summary of them, and the renewal date if known.', N'A brief factual internal note for the account and commercial roles, stating what is evidenced, what the partner contributed, and what is not proven.', N'The DCSA states what is not proven alongside what is. A technical note that reads as advocacy gets discounted entirely by the people preparing a renewal, and the unproven items are exactly what they need to know before they meet the customer.', N'Renewal handoff', N'Renewal conversations belong to the account and commercial roles. Technical evidence that stays with the architect does not reach them, and at this coverage nobody will come and ask for it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'PSS-DEM-01', N'WF-X-OPP-01', N'PSS-DEMAND', N'PH-PSS-DEMAND-EXPL', 1, N'Separate what you know from what you were told', N'Establish what our own record can independently confirm about an opportunity a partner brought you.', N'Featured', N'Both', N'A partner has brought me an opportunity at [account or company name]. Here is what they have told me: [paste what the partner told you]. Show me what our record independently contains about that customer: whether they exist as an account and under whose ownership, any products or workloads already in place, any prior or open opportunity, any recorded activity and from which role, and any existing partner association. State plainly which of the partner''s claims our record can speak to and which it cannot. Do not assess whether the opportunity is likely to close.', N'1. Open Researcher, paste the prompt, and replace both bracketed sections.
2. Read the cannot-speak-to list first. That is the part you are taking on the partner''s word.
3. If the account is owned by a DAE, tell them before you invest anything.
4. Decide how much Microsoft resource you will commit against the unverifiable portion, and be explicit that you are choosing to.', N'One opportunity brought to you by a partner, and what the partner told you about it.', N'The partner''s claims split into what our record can confirm and what rests entirely on their word, with an explicit decision on what to invest against the latter.', N'The PSS decides how much to invest against a claim only the partner can make. Their qualification bar is not ours and their incentive is to get Microsoft engaged, and a partner who is habitually right about this is a different proposition from one who is not, which is a judgment about the relationship rather than about the deal.', N'Inbound qualification', N'Every other role in this segment sends work out to partners. You also receive it, and what arrives has been qualified by somebody with a different standard and a different interest in the answer.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'PSS-DEM-02', N'WF-X-OPP-01', N'PSS-DEMAND', N'PH-PSS-DEMAND-EXPL', 2, N'Check the conditions before anyone counts on it', N'Establish whether a partner-originated deal meets the recorded conditions for registration, before it is treated as one.', N'Featured', N'Both', N'For [opportunity name or ID], show me what is recorded that bears on co-sell registration: the account and whether it is Microsoft-managed, the recorded deal value and currency, the solution area and products attached, the opportunity creation date, and the current stage and status. Also show any existing co-sell or referral record on the opportunity with its dates. Report only what is recorded and do not assess eligibility.', N'1. Open Sales Home and paste the prompt with the opportunity.
2. Check the recorded facts against the conditions yourself: a Microsoft-managed account, Azure IP co-sell eligibility, a value of at least twenty-five thousand US dollars, and at least seventy-two hours between creation and being marked won.
3. Anything you cannot confirm from the record, confirm with the authoritative owner rather than assuming.
4. Tell the partner what is missing now. Finding out at close is too late for both of you.', N'One partner-originated opportunity. The current co-sell registration conditions from the authoritative source.', N'The recorded facts assembled against the registration conditions, with the gaps identified and raised with the partner early.', N'The PSS confirms eligibility against the authoritative source rather than against a summary. Registration conditions change and a deal that fails one at close costs the partner real money, which is the kind of thing that ends a partnership rather than a deal.', N'Registration', N'The conditions are checkable long before close, and nothing prompts anyone to check them until it is nearly there. The whole cost of getting this wrong lands on the partner, and they will remember.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-DEM-03', N'WF-X-OPP-01', N'PSS-DEMAND', N'PH-PSS-DEMAND-EXPL', 3, N'Find the partner who keeps letting things lapse', N'Look across your partners for the ones whose referrals and co-sell records consistently stall, because that is a relationship problem rather than a record problem.', N'Extended', N'Both', N'For these partners [list three to five partners], show me the co-sell and referral records associated with each: the account, the recorded status, the date the record was created, and the date of the last recorded change. Group the output by partner. Report the recorded dates only - do not calculate elapsed time, judge which are close to expiring, or compare the partners.', N'1. Open Sales Home, paste the prompt, and replace the bracketed list with three to five of your partners.
2. Do the arithmetic yourself against the windows: fourteen days for a partner to accept a referral before it expires, sixty days after acceptance to convert before it is marked lost.
3. Read down each partner rather than across all the records. One lapsed referral is an accident; a partner with several is a conversation.
4. Check anything near a boundary in the Partner Timeline view or Partner Center, since our recorded status can lag what the partner has already done.
5. Chase the individual items with days left, and raise the pattern with the partner who has one.', N'Three to five partners from your portfolio. The Partner Timeline view or Partner Center for anything near a boundary.', N'Records grouped by partner with the window arithmetic done by you, separating one-off lapses from a partner-level pattern.', N'The PSS decides whether a pattern of lapsed records is a capacity problem, a fit problem, or a partner who was never going to work them. Those need completely different conversations, and the records look identical in all three cases.', N'Window management', N'Individual expiring referrals are chased by whoever sent them. Nobody else is positioned to notice whether the lapses concentrate on one partner, and that is the finding worth having.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-ORCH-01', N'WF-X-ORCH-01', N'PSS-ORCH', N'PH-PSS-ORCH-EXPL', 1, N'Decide which partners need you this month', N'Triage a portfolio of partners into the ones with something to decide and the ones that only need contact.', N'Featured', N'Both', N'For these partners [list three to five partners], show for each: the co-sell and referral records currently associated with them and the recorded status of each, and any opportunity where they are the associated partner along with its stage and the date it last moved. Group the output by partner. Do not rank the partners, compare them, or recommend where to spend time.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list with three to five partners.
2. Look for partners with something stalled or something approaching a decision - those need a meeting with an agenda.
3. Partners with everything moving need a check-in, not a meeting.
4. Separately, check your own cadence commitment: a minimum of monthly contact per partner seller. Anyone you have not spoken to in that window needs contact regardless of what the record shows.
5. Split the month into meetings that need preparation and contacts that satisfy the cadence.', N'Three to five partners from your portfolio, and your own record of when you last spoke to each.', N'Those partners split into meetings that need an agenda and contacts that meet the cadence commitment.', N'The PSS decides which partner genuinely needs time this month. Activity in the record tracks how much business is flowing rather than how much attention the relationship needs, and meeting a cadence minimum is a floor rather than a plan.', N'Portfolio triage', N'A minimum contact cadence is an obligation, not a strategy. Without a deliberate split the calendar fills with the partners who ask for time, and the meetings that needed preparation get none.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-ORCH-02', N'WF-X-ORCH-01', N'PSS-ORCH', N'PH-PSS-ORCH-EXPL', 2, N'Give the meeting something to decide', N'Turn a recurring partner meeting into one with a decision attached, using what has actually moved.', N'Featured', N'Both', N'I have a partner meeting with [partner name]. Show me what has changed on their associated records since a month ago where the record supports that: opportunities that moved stage, co-sell or referral records created or changed status, and any new recorded activity. Also show what has not moved. Present the changes factually and do not propose an agenda or suggest what to discuss.', N'1. Open Sales Agent, paste the prompt, and replace [partner name].
2. The things that have not moved are the meeting. The things that have moved are the update.
3. Pick one decision you want out of the conversation and build the agenda around it.
4. Send the partner the decision you want to reach beforehand, so they can arrive able to make it.', N'One partner with a meeting coming up.', N'A factual read on what has and has not moved for that partner, with one decision chosen and sent ahead as the agenda.', N'The PSS chooses the decision the meeting is for. What has not moved may be a partner problem, a Microsoft problem or a customer problem, and walking in with the wrong attribution turns a working session into a defensive one.', N'Meeting agenda', N'Recurring partner meetings drift into status reporting, which both sides can do by email. A meeting with a decision attached is the only kind worth the cadence.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-ORCH-03', N'WF-X-ORCH-01', N'PSS-ORCH', N'PH-PSS-ORCH-EXPL', 3, N'Find out who else is talking to your partner', N'Establish which Microsoft roles are engaged with the same partner, so the partner is not receiving three different asks.', N'Extended', N'Both', N'For these accounts where [partner name] is engaged [list three to five accounts], show which Microsoft roles have recorded activity on each in the last quarter and the date of the most recent from each role. Present it account by account with the roles named. Do not infer coordination or judge whether the engagement is aligned.', N'1. Open Sales Agent and paste the prompt with your partner and three to five of the accounts they work.
2. Look for accounts where several roles are active - the partner may be receiving conflicting asks.
3. Look for accounts where only the partner appears and no Microsoft role does.
4. Raise the conflicts at the territory health review rather than by chasing each role individually.', N'One partner, and three to five accounts where they are engaged.', N'The accounts where your partner is engaged, showing which Microsoft roles are active on each and where nobody is.', N'The PSS decides whether several roles engaging one partner is coordination or confusion. The record shows activity rather than intent, and a partner being asked for different things by three people will do the easiest one and tell nobody.', N'Internal alignment', N'Partners work with many people at Microsoft, and one receiving mixed messages does not necessarily say so; they prioritize. Seeing the overlap is the only way to find out it is happening.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-VAL-01', N'WF-X-VALUE-01', N'PSS-VALUE', N'PH-PSS-VALUE-EXPL', 1, N'Find out what happened after one partner''s deals closed', N'Take a single partner and establish what our record knows about the customers they closed, and where it goes silent.', N'Featured', N'Both', N'For [partner name], show me the opportunities recorded as closed won where they are the associated partner, going back two quarters. For each, show the account, the close date, and then what has been recorded on that account since that date: any activity and from which role, any support issue, and any usage or consumption figures held in the record. Show the most recent record date for each account alongside the close date. Do not infer customer satisfaction or outcome from any of it.', N'1. Open Sales Agent, paste the prompt, and replace [partner name] with one partner.
2. Look at the gap between each close date and the most recent record. That gap is what Microsoft cannot see.
3. Read it as a pattern for this partner rather than as a list of accounts. If every one of their customers goes silent immediately, that tells you something about how they work.
4. Long silence is not evidence of a problem or of success. It is the normal condition when a partner owns the relationship.
5. Pick the customer where not knowing would cost the most, usually one with a renewal ahead.', N'One partner whose closed deals you want to understand.', N'The visibility gap across one partner''s closed customers, read as a pattern for that partner, with the customer where it matters most identified.', N'The PSS decides where a gap in our visibility actually matters. Silence after a partner-led close is normal rather than alarming, and treating every quiet customer as a risk will exhaust both your time and the partner''s patience.', N'Visibility gap', N'Our record ends roughly where the customer''s experience begins on these deals. Looking partner by partner rather than account by account shows you whether the blind spot is about one customer or about how that partner works.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-VAL-02', N'WF-X-VALUE-01', N'PSS-VALUE', N'PH-PSS-VALUE-EXPL', 2, N'Ask the partner something worth answering', N'Draft the question that gets a partner to tell you how a customer is actually doing, without it reading as an audit.', N'Featured', N'Both', N'I want to ask [partner name] how a customer is getting on since they closed and delivered. Here is what I already know from our record: [paste what you found]. Draft a short message asking about the customer''s experience and any difficulty they have hit. Write it as a colleague with a shared interest in the customer, not as an inspection. Keep it to a few lines. Do not request seat counts, consumption figures, financial detail or anything commercially sensitive, and do not imply any obligation to report to us.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Read it as the partner. If it sounds like a request for a status report, it will be answered like one.
3. Check it against the CELA rules in both directions - what you are asking for as well as what you are sharing.
4. Send it, and be ready to offer something in return. A question with nothing behind it gets a short answer.', N'One partner and one customer they closed, plus what our record already shows. The CELA rules on partner data exchange.', N'A short colleague-to-colleague question about a specific customer, checked against the data rules and with something offered in return.', N'The PSS owns how this reads to the partner. A partner has no obligation to report customer outcomes to Microsoft, so the answer depends entirely on whether the question sounds like interest or like inspection, and only the person in the relationship can judge which.', N'Asking the partner', N'This is the only route Microsoft has back to a customer a partner owns. Getting the tone wrong does not just fail to get an answer, it makes the next question harder.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'PSS-VAL-03', N'WF-X-VALUE-01', N'PSS-VALUE', N'PH-PSS-VALUE-EXPL', 3, N'Get what you learn back to the people who need it', N'Pass what a partner tells you about a customer to the account and commercial roles, without overstating what you were told.', N'Extended', N'Both', N'A partner has told me about a customer they closed and delivered. Here is what they said: [paste what the partner told you]. Here is what our record shows: [paste the record position]. Draft a short internal note for the account executive and the commercial executive setting out what the partner reported, what our record independently shows, and where the two do not line up. Attribute the partner''s account clearly as theirs. Do not resolve any discrepancy or add conclusions I have not drawn.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check the partner''s account is presented as their report rather than as established fact.
3. Leave any discrepancy visible. The gap between what a partner says and what the record shows is the useful part.
4. Send it to the DAE and the CE, and tell the partner you have passed it on.', N'What the partner told you, and what our record shows for the same customer.', N'A short internal note separating the partner''s report from our record, with discrepancies left visible and attribution clear.', N'The PSS decides what is safe to represent as fact when it came from a single partner conversation. A partner''s read is genuine information and is also their interpretation, and a note that promotes it into a finding will be acted on by people who never spoke to them.', N'Closing the loop', N'What you learn from a partner is worthless if it stays with you. It is also dangerous if it travels as established fact, and the difference is entirely in how the note is written.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-POL-01', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 1, N'List the questions this structure will have to answer', N'Surface the policy, licensing and eligibility questions a deal will meet, before the structure is fixed.', N'Featured', N'Both', N'For [account name], show what is recorded that bears on commercial eligibility: the agreement type and its dates, the products and quantities involved, whether a partner is associated and any co-sell or referral record, and any amendment or exception already on the account. Also show whether the account transacts direct or through a partner where the record says so. Report what is recorded and do not interpret eligibility, licensing entitlement or policy.', N'1. Open Sales Agent and paste the prompt with your account.
2. Read the agreement type and the transaction route first - both change which rules apply.
3. Write down each question the structure raises. That list is yours to produce, not the agent''s.
4. Route every one to the authoritative owner rather than answering from a previous deal.', N'One live deal where the commercial structure is not yet fixed.', N'The recorded facts that bear on eligibility, with your own list of the questions the structure raises.', N'The CE decides which questions genuinely need an authoritative answer and routes them rather than answering from precedent. A structure that worked for a similar customer shows only that it was permitted once, on facts you have probably not seen, and reusing it quietly converts someone else''s exception into your own assumption.', N'Policy questions', N'Policy questions are cheapest at the point the structure is still a question. Asked at approval they cost weeks, and by then the customer may already have been told something that no longer holds.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-POL-02', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 2, N'Route the question so it comes back usable', N'Frame a policy question so the authoritative owner can answer it once, rather than starting a conversation.', N'Featured', N'Both', N'I need to ask an authoritative owner a policy question about [account name]. Here is the question and the context: [paste your question and the deal facts that bear on it]. Restructure this as a single question that can be answered without a follow-up: what is being asked, the specific facts that determine the answer, what I have already checked, and what decision the answer will drive. Do not answer the question or suggest what the answer might be.', N'1. Write the question yourself first, including the deal facts that determine the answer.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Check the restructured version still asks YOUR question rather than a cleaner adjacent one.
4. Send it, and record the answer against the account so the next person does not ask again.', N'Your policy question and the deal facts that bear on it. The authoritative owner for that question.', N'A single self-contained question that can be answered without a follow-up, with the answer recorded against the account.', N'The CE owns the question and confirms the rewrite did not change what is being asked. A model asked to make a question clearer will often make it more general, and a general answer to a specific eligibility question is worse than no answer because it feels like one.', N'Routing', N'Most policy delay is not the owner being slow, it is the question arriving without the facts needed to answer it. One well-formed question beats three exchanges.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-POL-03', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 3, N'Say out loud what you are relying on', N'Make an inherited policy position explicit enough that its owner can confirm or correct it.', N'Extended', N'Both', N'For [account name], show every amendment, exception or non-standard term recorded against this account: what each one is, the date it was recorded, and which agreement it sits against. Report only what is recorded on this account. Do not compare it to other accounts, and do not judge whether any of it still applies.', N'1. Write down the position you are about to rely on, in one sentence, before you look at anything. If you cannot state it, you do not yet know what you are assuming.
2. Open Sales Agent, paste the prompt, and replace [account name] with your deal.
3. Check whether the record actually says what you remember it saying. Often it says something narrower.
4. Send your one sentence and the relevant record to the authoritative owner and ask whether it still stands.', N'One live deal and the policy position you intend to rely on.', N'The position you are relying on stated in one sentence, with its recorded basis, sent to the authoritative owner for confirmation.', N'The CE states precisely what position they are relying on and has the owner confirm it before building on it. Reuse is invisible - a previous answer gets carried forward as an assumption rather than re-examined as a decision - and only the person relying on it can notice they are doing it. Whether it still stands is the owner''s call, not a matter of how recent it looks.', N'Precedent check', N'The most expensive policy error is not a wrong answer, it is a right answer that has expired. Nothing in the record marks a position as superseded, so the only reliable move is to name what you are assuming and have it confirmed.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-NEG-01', N'WF-X-DEAL-01', N'SMEC-CE-NEG', N'PH-SMEC-CE-NEG-EXPL', 1, N'Establish what can be conceded without asking', N'Fix the concession boundary from approved guidance before any pressure is applied to it.', N'Featured', N'Both', N'For [account name], show any discount, concession or non-standard term already in force on this account: what each one is, which agreement it sits on, and whether a partner transacts it. Report what is recorded. Do not advise what concession would be appropriate and do not propose a boundary.', N'1. Set your concession boundary from current approved guidance before you look at anything. That anchor does not come from the record.
2. Open Sales Agent, paste the prompt, and replace [account name] with your deal.
3. Treat what is already in force as a constraint on the boundary, not as evidence for it. It may itself have been an exception.
4. Write the boundary down, with the existing concessions noted against it, before anyone asks you to move.', N'One live deal heading toward a negotiation. Current approved commercial guidance for concession authority.', N'A concession boundary set from approved guidance, with the concessions already in force on the account recorded as constraints on it.', N'The CE sets the boundary from current approved guidance rather than from what comparable deals happen to carry. What was granted elsewhere may have been an exception, may have been wrong, or may have been approved under guidance that has since changed, and inheriting it silently converts one exception into a standard.', N'Concession authority', N'A boundary set before the pressure arrives is a decision. The same boundary set during the negotiation is a reaction, and it will be argued with.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-NEG-02', N'WF-X-DEAL-01', N'SMEC-CE-NEG', N'PH-SMEC-CE-NEG-EXPL', 2, N'Test whether your briefing gives away the floor', N'Check what a partner could infer from the boundary you are about to hand them.', N'Featured', N'Both', N'A partner will negotiate [describe the deal] with the customer. Here is the briefing I have written for them, covering what is fixed, what is theirs to use without asking, and what has to come back to me: [paste your briefing]. Read it as the partner would. Tell me what could be inferred from it about how much room exists beyond what I have stated, what is vague enough to be read as permission I did not intend, and anything in it resembling internal cost, margin, approval thresholds, seat counts, spend figures or personal data. Do not rewrite the briefing and do not tell me where the boundary should sit.', N'1. Write the briefing yourself, in three parts: what is fixed, what is theirs to use without asking, and what must come back to you. All three are your decisions and none of them are delegated.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Close anything that could be read as permission you did not intend to give. Vagueness reads as room.
4. Check it against the CELA rules yourself as well. The agent is a second reader, not the control.
5. Send it through your normal partner channel before the negotiation, not during it.', N'The partner briefing you have written, setting out what is fixed, what is theirs to use, and what must return to you for approval. The CELA rules on partner data exchange.', N'A partner briefing whose stated limits cannot be read as more room than you intended, with everything inferable closed before it is sent.', N'The CE decides how much of the boundary the partner needs to see. Too little and they concede something they should have escalated; too much and your floor becomes their opening position with the customer. That judgment depends on the specific partner, and only the person in the relationship can make it.', N'Partner briefing', N'A boundary is only as good as what the other side can infer around it. Partners are commercially sophisticated and will read the shape of what you did not say.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-NEG-03', N'WF-X-DEAL-01', N'SMEC-CE-NEG', N'PH-SMEC-CE-NEG-EXPL', 3, N'Decide now what would make you escalate', N'Name the specific condition that would take a concession decision above you, before it arrives.', N'Extended', N'Both', N'For the deal at [account name], my concession boundary is [paste your boundary]. Help me think through what circumstances would put a decision beyond that boundary: what the customer might reasonably ask for, what a partner might commit to on their own, and what timing pressure might create. For each, frame it as a condition to watch for rather than a prediction. Do not recommend whether to escalate or what the answer should be.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Pick the one or two conditions most likely to actually occur.
3. Write the trigger as something observable - a specific ask, a specific number - not as a feeling.
4. Tell your approver now that it may be coming, so the escalation is expected rather than a surprise.', N'Your concession boundary and the deal it applies to. Your approval route.', N'One or two observable escalation triggers named in advance, with the approver forewarned.', N'The CE decides what genuinely warrants escalation. Escalating everything trains your approver to stop reading, and escalating nothing means the boundary was never real, and only you can judge where this deal sits between those.', N'Escalation trigger', N'An escalation raised before the pressure is a decision with time attached. The same escalation raised during a negotiation is an emergency, and gets a worse answer.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'SMEC-CE-ORCH-01', N'WF-X-ORCH-01', N'SMEC-CE-ORCH', N'PH-SMEC-CE-ORCH-EXPL', 1, N'Find every approval this structure triggers', N'Assemble the full set of approvals a commercial structure will need, rather than meeting them one at a time.', N'Featured', N'Both', N'For [account name] I am taking this commercial structure to approval: [paste the structure]. Show what is already recorded that an approver would need to see: any exception or non-standard term already approved on this account and when it was recorded, the current deal stage and value, and whether a partner is associated with the account. Report what is recorded. Do not determine which approvals are required or who approves them.', N'1. Open Sales Agent and paste the prompt with your deal.
2. Work out the required approvals yourself from current approved guidance - that mapping is yours and it changes.
3. For each, decide whether it is one you obtain, one you request, or one the partner obtains from their own organization.
4. Confirm current lead times rather than assuming last quarter''s.', N'One deal with an agreed commercial structure needing approval. Current approved guidance on approval requirements.', N'The full approval set for this structure, each classified by whether you obtain it, request it, or the partner obtains it.', N'The CE determines which approvals are required, because that mapping changes with guidance and the record cannot know it. The classification matters more than the list: an approval you can obtain and one the partner must obtain from their own organization look identical on a plan and behave completely differently.', N'Approval mapping', N'Approvals met one at a time cost a week each. Mapping them together can show which ones run in parallel, and the sequence that looked fixed may be habit.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-ORCH-02', N'WF-X-ORCH-01', N'SMEC-CE-ORCH', N'PH-SMEC-CE-ORCH-EXPL', 2, N'Replace every implied owner with a named one', N'Turn an approval path expressed in roles into one expressed in people who know it is coming.', N'Featured', N'Both', N'Here is the approval path I have mapped for [account name]. For each step I have listed the owning role and the evidence that approval requires: [paste your approval list]. Draft the short note I would send to secure each one: what is being asked, the evidence I have listed against it, the date it is needed by, and what happens if it slips. Keep each to a few lines. Do not add evidence I have not listed, do not invent approver names, and do not state who the owner is.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Put a real name against every role before you send anything. A role is not an owner.
3. For partner-side steps, send the note to your partner contact rather than assuming they will discover it.
4. Send them all now rather than in sequence. Most of these are not actually dependent on each other.', N'Your mapped approval path, with the owning role for each step and the evidence that step requires taken from current approved guidance. The people who currently hold those roles.', N'A named owner and a sent request for every approval step, with the partner-side steps raised with the partner.', N'The CE confirms who currently holds each approval and that the evidence listed against it is what that approver actually asks for. Both change without announcement - a role moves, or a threshold is revised - and a note sent to last quarter''s owner citing last quarter''s evidence is a week lost before anyone notices it went to the wrong place.', N'Named owners', N'The approval path can be entirely correct and still unowned. Naming people converts a diagram into something that moves.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-ORCH-03', N'WF-X-ORCH-01', N'SMEC-CE-ORCH', N'PH-SMEC-CE-ORCH-EXPL', 3, N'Find the approval that never landed', N'Check the approvals you have already requested against what the record now shows, before a customer date makes it urgent.', N'Extended', N'Both', N'Here are the approvals I have outstanding and the date I requested each one: [paste your list with dates]. For each, show what is currently recorded on that opportunity: the current stage, the recorded next step and who owns it, and the close date. Report what is recorded and do not infer why anything is waiting.', N'1. List your outstanding approvals and the date you asked for each. If you cannot produce that list, that is itself the finding.
2. Open Sales Agent, paste the prompt, and replace the bracketed section.
3. Compare the recorded next step against what you actually asked for. Where they do not match, the request never landed.
4. Chase the ones you own with the named person rather than the queue. For partner-side approvals, ask your partner contact - our record will not show their progress at all.', N'The approvals you have already requested, and the date you requested each one.', N'Outstanding approvals separated into those that landed, those that never registered, and those sitting with a partner organization.', N'The CE decides which approvals have genuinely stalled and which are simply waiting their turn. An approval nobody ever submitted and one sitting correctly in a queue look identical from inside our systems, and a partner-side approval leaves no trace here at all - chasing that one through our own record costs the week you were trying to save.', N'Stalled approvals', N'Approvals fail quietly. The request that was never registered looks exactly like the one being worked, and the difference only becomes visible when the close date arrives.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-DEAL2-01', N'WF-X-DEAL-01', N'SMEC-CE-DEAL2', N'PH-SMEC-CE-DEAL2-EXPL', 1, N'State the decision you are asking someone to make', N'Turn a commercial structure into an explicit decision, so the approver is not left to work out what is being asked.', N'Featured', N'Both', N'I am taking a commercial structure to approval. Here is the structure and what I am asking for: [paste the structure and the ask]. Restate this as a decision: what specifically is being approved, what the alternatives were and why they were set aside, what happens if it is declined, and what the approver is accepting responsibility for. Use only what I have given you. Do not add commercial detail, do not recommend a decision, and do not soften the ask.', N'1. Write the structure and the ask down yourself first. If you cannot state the ask in one sentence, it is not ready to send.
2. Open Cowork, paste the prompt, and replace the bracketed section.
3. Check the alternatives are the ones you genuinely considered, not ones that make the recommendation look inevitable.
4. Confirm the responsibility line is accurate. That sentence is the one the approver will remember.', N'One commercial structure you have agreed and intend to take to approval. The approval you are seeking.', N'The structure restated as an explicit decision, with the alternatives, the consequence of declining, and what the approver is accepting.', N'The CE decides what the approver is actually being asked to accept. An approval request that understates what the approver is taking on gets granted quickly and withdrawn later, and the second conversation is far more expensive than the first.', N'Structure outcome', N'Approvers are sent structures and left to infer the decision. The ones that stall are the ones where the ask was never stated plainly, and nobody wants to admit they could not find it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-DEAL2-02', N'WF-X-DEAL-01', N'SMEC-CE-DEAL2', N'PH-SMEC-CE-DEAL2-EXPL', 2, N'Make the numbers checkable by someone else', N'Lay out the economics so an approver can verify them rather than take them on trust.', N'Featured', N'Both', N'Here are the economics of the commercial structure I am proposing: [paste your figures and where each came from]. Lay them out so someone else can check them: what is committed, over what period, what the customer pays and when, and what varies from standard and by how much. Show each figure alongside the source I have given for it. Do not calculate anything I have not supplied, do not estimate missing values, and flag any figure I have given without a source.', N'1. Assemble your figures first, and write the source next to each one as you go.
2. Open Cowork, paste the prompt, and replace the bracketed section.
3. Look at what it flags as unsourced. Those are the ones you will be asked about.
4. Replace any figure you cannot source with the range you can defend, and say it is a range.', N'The economics of your proposed structure, with the source of each figure.', N'The economics laid out with a source against every figure, and unsourced figures either sourced or stated as ranges.', N'The CE owns every number in the narrative and confirms each against where it came from. A figure that appears in an approval document becomes the figure everyone quotes afterwards, and the person who typed it is the only one who knows whether it was measured or estimated.', N'Pattern', N'A commercial narrative can fail review on one unsourced number rather than on the strength of the case. The figure nobody can trace is the one that stops the meeting.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-DEAL2-03', N'WF-X-DEAL-01', N'SMEC-CE-DEAL2', N'PH-SMEC-CE-DEAL2-EXPL', 3, N'Find what you have asserted without showing', N'Read your own narrative as someone who was not in any of the conversations behind it.', N'Extended', N'Both', N'Here is the commercial decision narrative I have written: [paste the narrative]. Read it as someone who was not part of any conversation behind it. List every claim asserted without evidence attached, every figure whose source is not stated, and every place where a judgment is presented as though it were a fact. Do not rewrite it, do not supply the missing evidence, and do not tell me whether the case is a good one.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Read the list before defending anything. The first reaction to most of these is that the context is obvious.
3. Close the gaps on the central commercial claim. Leave the peripheral ones open if closing them would bury the argument.
4. Where a judgment is being presented as a fact, say whose judgment it is.', N'Your drafted commercial decision narrative.', N'The narrative''s unevidenced claims identified, with the central ones closed and the remaining judgments attributed.', N'The CE decides which gaps must be closed before this goes and which can stand. A narrative that evidences every claim is unreadable and a narrative that leaves the central commercial claim unevidenced is returned, and telling those apart is the whole skill.', N'Feeding it back', N'You cannot see the assumptions you carried into your own document. Everything in it was obvious to you at the time, which is exactly why it reads as unsupported to the person approving it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-ARCH-01', N'WF-X-ARCH-01', N'DCSA-ARCH', N'PH-DCSA-ARCH-EXPL', 1, N'Compare the options on what happens when nobody tunes them', N'Research architecture options for a customer with no platform team, judging them on how they behave unattended.', N'Featured', N'Both', N'I am designing [describe the workload] for a customer with [describe their technical capacity and who will operate it]. Using approved Microsoft and authoritative public sources, compare the architecture options on operational burden: what each requires someone to monitor, tune or intervene on; what each does when left alone; what skills each assumes the operator already has; and what the documented failure modes are. Cite each claim and name where guidance conflicts or is missing. Do not recommend an option.', N'1. Write down who will operate this before you look at any options. That constraint decides the answer.
2. Open Researcher, paste the prompt, and replace both bracketed sections.
3. Check the citations. Guidance written for a customer with a platform team will not say so, and you have to notice.
4. Discard any option whose operational assumptions this customer cannot meet, however good it looks.', N'The workload and the customer''s technical constraints. What you know about who will operate it.', N'Architecture options compared on unattended behavior and operator skill assumed, with sources cited and gaps named.', N'The DCSA decides what this customer can realistically operate. Published guidance assumes a competent platform team because it is written for the general case, and a design chosen on capability alone will be technically correct and quietly abandoned within two quarters.', N'Compare the options on what happens when nobody tunes them', N'For a portfolio of non-unified customers there is no support relationship to absorb an operationally demanding design. The question is not which architecture is best but which one survives contact with the people who will actually run it.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DCSA-ARCH-02', N'WF-X-ARCH-01', N'DCSA-ARCH', N'PH-DCSA-ARCH-EXPL', 2, N'Write the design for the person who will build it', N'Turn a chosen architecture into something a partner or customer team can implement without you present.', N'Featured', N'Both', N'Here is the architecture I have chosen and what I know about who will implement it: [paste the design, the constraints, and what the implementer has built before]. Turn this into an implementation-ready description covering the sequence and the dependencies, marking which dependencies are outside the implementer''s control. Separately, list every configuration decision the implementer will have to make that my design does not already settle, and for each state what the design implies but does not say. Do not choose any of those configurations for me and do not add architectural decisions I have not made.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Read the unsettled configuration list. Those are the decisions the implementer will otherwise make for you, at the point you are least available.
3. Write your recommended choice against each one yourself. That is a design decision and it does not get delegated.
4. Send it to the implementer and ask which step they would want to talk through.', N'Your chosen architecture and its constraints. Who will implement it and what they have built before.', N'An implementation-ready design with the sequence and dependencies, plus the configuration decisions your design leaves open, each answered by you.', N'The DCSA answers every configuration decision the design leaves open. The implementer will resolve anything left silent using their own defaults, which are reasonable for their usual customer and may be wrong for this one - and the divergence only becomes visible when something behaves unexpectedly months later.', N'Write the design for the person who will build it', N'The design is not the artefact. What the implementer does with it is the artefact, and everything you left implicit becomes their judgment call.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-ARCH-03', N'WF-X-ARCH-01', N'DCSA-ARCH', N'PH-DCSA-ARCH-EXPL', 3, N'Find what your design assumes the customer has', N'Read your own design for the support, skills and tooling it quietly takes for granted.', N'Extended', N'Both', N'Here is a design I am about to hand over: [paste the design]. Here is what I actually know about the customer''s operating capability: [describe their team, skills, tooling and support arrangements]. Identify every point where the design assumes capability, tooling, support or availability I have not confirmed they have. For each, state what the design expects and what happens if it is absent. Do not redesign anything and do not tell me whether the design is good.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Read the list before defending it. Most of these assumptions felt obvious when you made them.
3. Confirm or close the ones that would cause a silent failure. An assumption that fails loudly is survivable.
4. Where you cannot close one, say so in the handover rather than leaving it to be discovered.', N'Your implementation-ready design. What you actually know about the customer''s operating capability and support arrangements.', N'The design''s unconfirmed assumptions listed with the consequence of each, and the silent-failure ones closed or disclosed.', N'The DCSA decides which unconfirmed assumptions are acceptable to hand over. Every design assumes something, and closing all of it is not possible in this segment - the judgment is which assumption fails quietly, because that is the one that turns into a consumption problem nobody traces back to the design.', N'Find what your design assumes the customer has', N'You cannot see what you assumed. Everything in the design was reasonable when you wrote it, which is exactly why the gaps are invisible to you and obvious to the customer six months later.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-HEALTH-01', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 1, N'Find the accounts where something technical has changed', N'Scan the portfolio for the recorded signals that precede a consumption problem.', N'Featured', N'Both', N'Across the accounts in my portfolio, identify those where consumption or usage has moved against plan, and separately those with a support or service record raised in the period I specify but no recorded technical activity from us. For the accounts that match, show the recorded movement, the support activity and the date of our last recorded technical engagement. Use this period: [state the period]. Do not return the accounts that do not match and do not diagnose a cause.', N'1. Open Sales Agent and paste the prompt.
2. Treat the two groups differently: movement against plan is a question, support activity with no engagement from us is a gap.
3. For each candidate, form your own technical hypothesis before opening the account. The record will not give you one.
4. Rank by how expensive the problem becomes if it is still there next quarter, not by size.', N'Your portfolio of accounts. Whatever consumption, usage and support views you can reach. The period you want assessed.', N'The portfolio split into accounts moving against plan and accounts with unattended support activity, ranked by cost of delay.', N'The DCSA decides which movement is technically significant. Consumption drops for reasons that have nothing to do with the technology - a project ending, a budget cycle, a seasonal workload - and spending your limited portfolio time on those is how the real problem stays undiscovered.', N'Find the accounts where something technical has changed', N'At this portfolio size you cannot inspect accounts individually, so the scan is the only way in. It will not tell you what is wrong; it tells you where to spend the attention you have.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-HEALTH-02', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 2, N'Raise a problem the customer has not noticed yet', N'Prepare the conversation where you tell a customer about a technical risk they did not ask you to look for.', N'Featured', N'Both', N'I need to raise a technical risk with a customer who has not asked about it. Here is the risk and my evidence: [describe the risk and what supports it]. Here is who I would raise it with and our history: [describe the contact and the relationship]. Help me rehearse this conversation: how to open it without implying they have been negligent, what they are likely to push back on, how to respond if they say it is not a priority, and how to close with a specific next step. Do not tell me whether to raise it.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the pushback you find hardest rather than the opening you find easiest.
3. Decide in advance what you will do if they decline to act. That answer is yours, not the agent''s.
4. Have the conversation, and record what they said so the next person does not raise it cold again.', N'The technical risk you have identified and the evidence for it. Who at the customer you would raise it with.', N'A rehearsed conversation with the likely objections worked through and a specific next step prepared.', N'The DCSA decides whether the evidence is strong enough to raise unasked. A technical risk surfaced on partial evidence and then disproved by the customer''s own team costs the standing you would need to raise the next one, and the record may not contain enough to settle it either way before the conversation.', N'Raise a problem the customer has not noticed yet', N'Finding the risk is the easy part. The conversation is where it either becomes an intervention or becomes a note nobody acted on, and in this segment you may get one attempt.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DCSA-HEALTH-03', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 3, N'Set a standing check so the next one finds you', N'Put a recurring watch on the portfolio so technical movement reaches you when it happens rather than at the next review.', N'Featured', N'Both', N'Set up a recurring weekly check across the accounts in my portfolio. Each week, tell me where consumption or usage has moved against plan, where a new support or service record has appeared on an account with no recent technical engagement from us, and where something I flagged previously has not changed. For each one, state what the data shows, what it does not tell us, and the single technical question I should ask next. Remember what you reported before, so you can tell me what is genuinely new and what is unchanged.', N'1. Open Scout and set the check running against your portfolio.
2. Give it the period and the movement threshold you actually care about, so it does not report everything.
3. Read the first run against what you already believed about these accounts.
4. Keep only the accounts where the movement is technically explainable and worth a conversation.
5. Prune it after two weeks. A check that reports everything gets ignored exactly like a dashboard nobody opens.', N'Your portfolio of accounts. The consumption, usage and support sources you can reach. The risks already on your list.', N'A weekly check running across the portfolio, separating new movement from unchanged risk, with a next technical question for each.', N'The DCSA confirms the technical reading of each signal and decides what is worth acting on. A standing check makes the finding cheaper, not the judgment - and the failure mode of automation here is a weekly report that everyone stops reading by week three.', N'Set a standing check so the next one finds you', N'Manual portfolio scans do not survive a busy quarter, which is exactly the quarter you need them. The value is that it keeps running when you have forgotten about it.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'DCSA-EXPAND-01', N'WF-X-RENEW-01', N'DCSA-EXPAND', N'PH-DCSA-EXPAND-EXPL', 1, N'Find the workload that is genuinely working', N'Identify where a customer is succeeding with something, as the only reliable starting point for expansion.', N'Featured', N'Both', N'For the accounts in my portfolio, show for each the workloads deployed, what usage is recorded against each, when each was deployed, and any support or service record raised against them. Identify the accounts where recorded usage has been stable or growing over the period I specify: [state the period you want assessed]. Report what is recorded and do not infer readiness or recommend anything.', N'1. Open Sales Agent and paste the prompt.
2. Look for stable and growing, not just large. A big workload that has flattened is not a readiness signal.
3. Decide for yourself how long usage has to hold before it evidences adoption rather than a pilot. That depends on the workload and the customer.
4. Pick the one account where the succeeding workload is closest to something the customer has said they care about.', N'Your portfolio of accounts and whatever deployment and usage evidence you can reach.', N'Accounts where a workload has demonstrably held or grown over two quarters, with the strongest candidate chosen.', N'The DCSA decides what counts as genuinely succeeding. Recorded usage can reflect one team, one automated process, or a workload nobody has switched off, and expanding from a false positive costs the credibility you would need for the real conversation.', N'Find the workload that is genuinely working', N'Expansion built on a workload that is merely deployed fails in a predictable way. Expansion built on one the customer is visibly getting value from is a conversation they will start themselves.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-EXPAND-02', N'WF-X-RENEW-01', N'DCSA-EXPAND', N'PH-DCSA-EXPAND-EXPL', 2, N'Test what usually comes next after this', N'Check an expansion hypothesis against documented adoption patterns rather than against what we would like to sell.', N'Featured', N'Both', N'A customer is running [describe the workload] successfully and I am considering whether [describe the expansion you have in mind] is the next logical step. Using approved Microsoft and authoritative public sources, show what the documented technical prerequisites are for that expansion, what the common adoption sequence is from the first workload, and what the documented reasons are for that sequence failing. Cite each claim. Do not tell me whether this customer is ready.', N'1. Open Researcher, paste the prompt, and replace both bracketed sections.
2. Read the failure reasons before the prerequisites. They are more useful and less often looked at.
3. Check the prerequisites against what you actually know this customer has, not what a customer of this size usually has.
4. If the documented sequence puts something else before your expansion, take that seriously rather than skipping it.', N'The workload the customer is succeeding with, and the expansion you are considering.', N'The expansion''s documented prerequisites and common failure reasons, checked against what this customer actually has.', N'The DCSA decides whether the documented sequence applies to this customer. Adoption patterns describe the average case and this segment is full of customers who are not average - the judgment is which prerequisite genuinely blocks and which is an assumption from a larger deployment.', N'Test what usually comes next after this', N'The expansion that follows a documented sequence is the one the customer can absorb. Skipping a step is how a technically valid expansion turns into a stalled deployment that damages the workload it grew from.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DCSA-EXPAND-03', N'WF-X-RENEW-01', N'DCSA-EXPAND', N'PH-DCSA-EXPAND-EXPL', 3, N'Hand it over in a form somebody can sell', N'Turn technical readiness evidence into something the person who owns the commercial conversation can actually use.', N'Extended', N'Both', N'I have technical evidence that a customer is ready for [describe the expansion]. Here is the evidence: [paste what you found - the succeeding workload, the usage pattern, the prerequisites met and any not yet met]. Draft a short handover for the person who owns the commercial conversation: what the customer is already succeeding with, what that makes possible, what is technically confirmed and what is not, and what would need to be true before it could start. Keep it factual. Do not write a pitch and do not include commercial or pricing framing.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check that what is unconfirmed is as prominent as what is confirmed. A handover that reads as certainty will be sold as certainty.
3. Send it to whoever owns the commercial conversation and say explicitly that the technical readiness is your view and the timing is theirs.
4. Record it against the account so the next person does not rediscover it.', N'Your evidenced expansion hypothesis. Who owns the commercial conversation on this account.', N'A factual technical handover separating confirmed readiness from open questions, with the commercial owner named.', N'The DCSA states what is technically evidenced and stops there. Technical readiness and commercial timing are different judgments owned by different people, and a handover that strays into whether the customer will buy undermines the person who has to have that conversation.', N'Hand it over in a form somebody can sell', N'Uncovering the next workload is the DCSA''s accountability; selling it is not. The handover is where that boundary is either respected or quietly crossed.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-ASSET-01', N'WF-X-ASSET-01', N'DSE-ASSET', N'PH-DSE-ASSET-EXPL', 1, N'Package it with what it assumes', N'Turn something you built into a reusable asset, with the constraints that decide whether it fits.', N'Featured', N'Both', N'Here is something I built and want to make reusable: [paste or describe the artefact - a script, design, demo, response or checklist]. It was built for this situation: [describe the customer context, constraints and what it assumed]. Produce a reusable package covering what it does, what it requires before use, the steps to use it, what someone would need to change for their own situation, how to check it worked, where it does not apply, and who owns it. Flag anything customer-identifying that should be removed. Do not add capability it does not have.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check the removal flags yourself. The agent will catch names and identifiers; it will not catch a configuration that only one customer would ever run.
3. Write the "where it does not apply" section properly. It is the part that stops the asset being misused and the part everyone skips.
4. Check the community hubs before publishing. If something close already exists, improve that instead of adding a second.', N'The artefact you want to make reusable. The customer situation it was built for. Your team''s rules on what may be shared internally.', N'A reusable package with prerequisites, adaptation points, validation steps and stated limits, sanitized for internal sharing.', N'The DSE decides what is safe to hand to someone who will not know what it assumed. Automated flagging may surface names and identifiers but cannot be relied on to catch a configuration that only made sense for one customer, so the review is the seller''s and it is not delegable.', N'Package it with what it assumes', N'An artefact without its constraints is not reusable, it is just findable. The next engineer either rebuilds it or applies it somewhere it was never validated.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-ASSET-02', N'WF-X-ASSET-01', N'DSE-ASSET', N'PH-DSE-ASSET-EXPL', 2, N'Write the note that makes it findable', N'Produce the description another engineer would search for and could judge fit from without opening it.', N'Featured', N'Both', N'Here is a reusable asset I am publishing: [paste the package]. Write the entry another engineer would find when searching: a one-line description of what it does, the problem it solves stated in the words somebody would actually search for, the prerequisites, one example of when to use it and one of when not to, and the owner. Keep it short enough to read in fifteen seconds. Do not restate the asset itself.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check the search words are the ones a colleague would type, not the ones you used when you built it.
3. Make sure the "when not to use it" example is specific. A vague limitation gets ignored.
4. Publish it where the team already looks, and tell one person who has the problem it solves.', N'Your sanitized asset package. Where it will be stored and who maintains it.', N'A short findable entry with the problem stated in searchable terms, a fit example, a non-fit example and a named owner.', N'The DSE decides whether the description matches how colleagues actually search. The test is not whether it reads well but whether it uses the words someone would type while looking for something they cannot name precisely, and only somebody who has failed to find things in this repository knows what those are.', N'Write the note that makes it findable', N'An asset nobody can find fails for a reason that has nothing to do with its quality. Something described in the language of the person who built it is invisible to the person who needs it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-ASSET-03', N'WF-X-ASSET-01', N'DSE-ASSET', N'PH-DSE-ASSET-EXPL', 3, N'Catch the question that has started arriving', N'Set a standing check that surfaces technical questions which have begun recurring since you last looked, rather than re-listing what you already know.', N'Featured', N'Both', N'Check my messages and meetings from the last [state a period] for technical questions I have answered more than once. Group them by the underlying technical problem rather than by wording, and show how many different people or customers each came from. On each later run, report only groups that are new since your previous report, or where the number of distinct askers has grown. Do not draft answers and do not repeat groups you have already reported unless they have grown.', N'1. Open Scout, run the prompt, and set your own lookback period for the first run.
2. Treat the first run as a backlog. Everything it finds is historical and most of it you already half-knew.
3. From the second run onward, the value is only in what is new or growing. That is a signal that something has changed in the product, the market or your patch.
4. Pick candidates by breadth of asker rather than by count, and judge for yourself what breadth means for your patch.
5. When you publish an asset, check the next report to see whether the question stopped arriving.', N'Your mail, chats and meetings. The assets your team has already published.', N'Technical question groups that are new or growing since the previous run, with the breadth of askers for each.', N'The DSE decides whether a newly recurring question reflects a genuine change or a coincidence of timing. A question that starts appearing may mean a product update, a competitor claim or a shift in what customers are attempting - and only someone who knows what changed recently can tell which, or whether it is simply two customers who happened to ask in the same two weeks.', N'Notice what you are answering repeatedly', N'A one-off scan finds the backlog once. What is worth knowing afterwards is which questions have STARTED arriving, because that is a change in the field you would otherwise notice months later.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'DSE-PARTNER-01', N'WF-X-ORCH-01', N'DSE-PARTNER', N'PH-DSE-PARTNER-EXPL', 1, N'Find where the same partner keeps needing you', N'Look across partner-led opportunities for the technical dependency that keeps coming back to you.', N'Featured', N'Both', N'For the opportunities in my area where a partner is associated and that have been open during [state the period], group them by partner and return only the partners with more than one. For those partners only, show for each opportunity the current stage, how long it has been at that stage, the recorded next step and its owner, and any recorded technical activity from me. Report what is recorded and do not infer why anything has stalled.', N'1. Open Sales Agent and paste the prompt.
2. Look at the grouping by partner before the individual deals. One deal needing you is normal; one partner repeatedly needing you is the finding.
3. For each recurring partner, work out what specific technical step they hand back. The record will not say - you know it from the asks.
4. Separate what they cannot do from what they simply prefer you to do. Those need different responses.', N'The partner-led opportunities you support, which partner is associated with each, and the period you want to look at.', N'Partner-led opportunities grouped by partner, with the recurring technical dependency identified for each.', N'The DSE decides whether a partner is genuinely lacking capability or has learned that asking is faster than doing. Both look identical in the record and in the request, and enablement fixes only the first - offering it for the second is politely ignored.', N'Find where the same partner keeps needing you', N'One deal at a time, absorbing the technical step looks like helpfulness. Across a partner''s portfolio it is the reason their capability never grows and your time never comes back.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PARTNER-02', N'WF-X-ORCH-01', N'DSE-PARTNER', N'PH-DSE-PARTNER-EXPL', 2, N'Have the capability conversation without causing offence', N'Prepare the conversation that names a partner''s technical gap and offers to close it rather than cover it.', N'Featured', N'Both', N'I need to raise a technical capability gap with a partner. Here is the gap and what makes me think it exists: [describe the gap and the evidence]. Here is my relationship with them and who I would speak to: [describe the contact and the history]. Help me rehearse this: how to open it as an offer rather than a criticism, what they may say to deflect it, how to respond if they say they have it covered when the evidence says otherwise, and how to close with a specific action they own. Do not tell me whether the gap is real.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the deflection you expect, not the version where they agree with you.
3. Decide beforehand what you will do if they decline. Continuing to absorb the work is a decision too, and it should be a deliberate one.
4. Close with an action the partner owns and a date. Enablement you own is not enablement.', N'The capability gap you have identified and the evidence for it. Your relationship with the partner and who you would raise it with.', N'A rehearsed capability conversation opened as an offer, with the likely deflections worked through and a partner-owned action prepared.', N'The DSE decides what evidence is sufficient to call something a capability gap rather than a preference. Repeated requests can mean the partner cannot do the work, or that they have learned we will, and naming the wrong one produces enablement that is politely attended and never applied.', N'Have the capability conversation without causing offence', N'This conversation is the whole workflow. Everything before it is preparation, and the alternative to having it is doing the partner''s technical work indefinitely.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DSE-PARTNER-03', N'WF-X-ORCH-01', N'DSE-PARTNER', N'PH-DSE-PARTNER-EXPL', 3, N'Leave them something that works when you are not there', N'Turn a resolved technical gap into material the partner can use themselves next time.', N'Extended', N'Both', N'A partner had this technical gap and here is how it was resolved this time: [describe the gap and what was done]. Here is what the partner''s team already knows and works with: [describe their technical background and tooling]. Draft something they could use to do this themselves next time: the steps, the decisions they will face and what to consider for each, how to check it worked, and when to come to us anyway. Write it for their engineers, not for ours. Do not include internal-only detail, customer-identifying information, or anything that reads as an export from our systems.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check it against your data-sharing rules before it leaves Microsoft. This is going to another company.
3. Be specific about when they should still come to us. Material that implies they never need us again is inaccurate and will be trusted anyway.
4. Send it to the person who owns the action, not to the account contact, and ask them to try it on the next one.', N'The capability gap and how it was resolved. What the partner already knows and what they use.', N'Partner-usable technical material with the decision points explained and the escalation boundary stated, checked before it leaves Microsoft.', N'The DSE decides what is genuinely safe to hand to another company and where the boundary of self-service sits. Material that is too complete invites a partner to attempt something they should escalate, and the failure lands on a customer who never knew the difference.', N'Leave them something that works when you are not there', N'A gap closed in one conversation reopens on the next deal. Something the partner keeps is the only version of this that reduces your load permanently.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSS-COMP-01', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 1, N'Find out what the competitor actually does well', N'Build an evidenced view of a competitor''s real strengths in your solution area, from sources rather than from internal belief.', N'Featured', N'Both', N'A customer is comparing our [describe the solution area] against [name the competitor]. Using authoritative public sources and approved Microsoft material, set out what that competitor''s offering does well in this area, what its documented limitations are, and where independent sources disagree with either vendor''s marketing. Cite each claim and state where evidence is thin. Do not tell me how to position against them and do not characterize the competitor as weak.', N'1. Open Researcher, paste the prompt, and replace both bracketed sections.
2. Read the competitor strengths first. That is the part internal material will not give you honestly.
3. Check the citations. A claim about a competitor that turns out to be out of date loses a technical audience.
4. Mark anything you would be uncomfortable saying if the competitor were in the room. That is the material to drop.', N'The competitor and the solution area. The customer''s stated decision criteria if you have them.', N'An evidenced view of the competitor''s genuine strengths and documented limitations, with sources cited and thin areas flagged.', N'The DSS decides what is safe to assert. A competitive claim that a customer can disprove in one search costs the whole position, not just that point, and internal competitive material is written to persuade rather than to survive being checked.', N'Find out what the competitor actually does well', N'You will be positioned against a competitor the customer has already researched. Arriving with a view that is less accurate than theirs ends the technical credibility you need for everything else.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DSS-COMP-02', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 2, N'Check what this competitor has actually cost you', N'Look across your solution area for what happened in past opportunities where this competitor was involved.', N'Featured', N'Both', N'Across the opportunities in my solution area, show any where [name the competitor] is recorded as involved: the account, the stage reached, whether it closed and how, and any recorded objection, blocker or competitor note. Group them by outcome. Report what is recorded and do not infer why any of them went the way they did.', N'1. Open Sales Home and paste the prompt with your competitor.
2. Look at the losses before the wins. The recorded objection on a loss is the most useful sentence in the system.
3. Where the record says nothing, treat that as unknown rather than as no objection.
4. Pick the objection that appears most often across different accounts. That is the one worth preparing properly.', N'The competitor. Your solution-area opportunities.', N'Past opportunities involving this competitor grouped by outcome, with the recurring objection identified.', N'The DSS decides which recorded objection reflects a real competitive pattern. Notes are written by whoever was losing at the time and often record the last thing said rather than the actual reason, so the same words can mean several different problems.', N'Check what this competitor has actually cost you', N'The objection you will meet has almost certainly been met before somewhere in your solution area. It is written down badly, but it is written down.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-COMP-03', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 3, N'Write the position against their criteria, not ours', N'Turn competitive evidence into a position expressed in the customer''s decision criteria.', N'Extended', N'Both', N'Here is what I know about how we compare to a competitor in my solution area: [paste your evidence and the recurring objection]. Here are the customer''s decision criteria as they have expressed them: [paste or describe the criteria]. Map each criterion to what we can evidence, what the competitor can evidence, and where neither of us has evidence. Identify the criteria where the comparison genuinely favors us and those where it does not. Do not write positioning language and do not resolve the criteria where we are behind.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Look at the criteria where we are behind. Deciding what to do about those is the actual work.
3. Concede the ones you cannot win rather than arguing them. A concession buys credibility for the criteria that matter.
4. Build the conversation around the two or three criteria where the advantage is both real and valued.', N'Your competitive evidence and the recurring objection. The customer''s decision criteria in their own words.', N'Decision criteria mapped to what each side can evidence, with the winnable criteria separated from the ones to concede.', N'The DSS decides which criteria to concede. Contesting everything reads as a vendor who has not listened, and choosing what to give up is a judgment about this customer''s priorities that no comparison table contains.', N'Write the position against their criteria, not ours', N'Customers decide on their criteria, not on ours. A position organized around our strengths answers a question they were not asking.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSS-ORCH-01', N'WF-X-ORCH-01', N'DSS-ORCH', N'PH-DSS-ORCH-EXPL', 1, N'Work out what the opportunity is actually missing', N'Establish what support an opportunity needs by looking at what is recorded rather than at what feels stuck.', N'Featured', N'Both', N'For [opportunity name or ID] in my solution area, show what is recorded: the current stage and when it last changed, the recorded next step and its owner, any recorded blocker or objection, whether a partner is associated, and what technical or specialist activity is recorded against it. Report what is recorded and do not infer what support is needed.', N'1. Open Sales Agent and paste the prompt with your opportunity.
2. Compare the recorded next step against what you believe the next step is. Where they differ, someone else is working from the record.
3. Decide what is genuinely missing: a person, a decision, or evidence. They are asked for in different ways.
4. Write the need down as a task somebody could do, not as a description of the situation.', N'One opportunity in your solution area that is not moving as it should.', N'The opportunity''s recorded position with the missing support identified as a person, a decision or a piece of evidence.', N'The DSS decides what would actually unblock this rather than what would be useful to have. In a segment with no assigned v-team every ask spends credit with someone who has their own targets, and asking for the wrong thing costs the same as asking for the right one.', N'Work out what the opportunity is actually missing', N'Most support asks describe a situation and hope the reader works out the task. Naming the missing thing precisely is what separates an ask that gets actioned from one that gets acknowledged.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-ORCH-02', N'WF-X-ORCH-01', N'DSS-ORCH', N'PH-DSS-ORCH-EXPL', 2, N'Write the ask so it can be said yes to', N'Turn a support need into a request with a task, a date and a consequence.', N'Featured', N'Both', N'I need support on an opportunity and here is what is missing: [describe what you need and the opportunity context]. I am asking [describe who you are asking and what they are accountable for]. I need it by [state your date] because [state what happens to the opportunity if it does not arrive]. Draft the request using those: what specifically I am asking them to do, by my stated date, what I have already done so they are not repeating it, and my stated consequence. Keep it to a few lines. Do not set a date I have not given you, do not invent a consequence, and do not pad it with background.', N'1. Decide your date and your consequence first. Both are yours and neither can be worked out from the opportunity record.
2. Open Cowork, paste the prompt, and replace all four bracketed sections.
3. Check that the task is something a person could start without asking you a question first.
4. Send it to a named person. A request to a team is a request to nobody.', N'The support you need and the opportunity it is for. Who you are asking and what they are accountable for. The date you need it by, and what happens to the opportunity if it does not arrive by then.', N'A short request with a specific task, a date, what has already been done, and the consequence of it not arriving.', N'The DSS decides how much of the consequence to state. Overstating it is noticed and quietly discounted from then on; omitting it leaves the reader to guess the priority, and they will guess low because everything else they have been sent also looked urgent.', N'Write the ask so it can be said yes to', N'The people you need are not assigned to you and are choosing between several asks. Yours is competing on how easy it is to act on.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSS-ORCH-03', N'WF-X-ORCH-01', N'DSS-ORCH', N'PH-DSS-ORCH-EXPL', 3, N'Notice when an ask has gone quiet', N'Set a standing check that tells you which of your requests never got answered.', N'Featured', N'Both', N'Set up a recurring weekly check across my sent messages for requests I have made that have not received a reply. For each, show who it went to, when it was sent, what was being asked, and whether any date I set has now passed. Group them by how overdue they are. Remember what you reported before so you can tell me which are newly overdue and which I have already been told about. Do not draft follow-ups.', N'1. Open Scout and run the prompt.
2. Read the newly-overdue group first. The long-overdue ones need a different approach rather than another chase.
3. For anything twice reported and still unanswered, go to the person a different way rather than resending.
4. Prune what you are tracking every few weeks. A list that includes everything you ever sent stops being useful immediately.', N'The support asks you have outstanding and who each went to.', N'Outstanding requests grouped by how overdue they are, separating newly overdue from previously reported.', N'The DSS decides which silence needs chasing and which means the answer is no. Some unanswered asks are a queue and some are a declined request nobody wanted to say out loud, and chasing the second repeatedly costs the relationship you will need for the next one.', N'Notice when an ask has gone quiet', N'Support asks fail silently. Nobody tells you they are not doing it, and by the time you notice, the opportunity has moved past the point where it would have helped.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'PSS-CAP-01', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 1, N'Look at what the partner has actually delivered', N'Establish a partner''s delivery record from what is recorded, before deciding what to route to them.', N'Featured', N'Both', N'For [partner name], show what is recorded: the opportunities where they are associated and the stage each reached, any co-sell or referral record and its status, what closed and over what period, and the workloads or solution areas involved. Group by outcome and by solution area. Report what is recorded and do not assess their capability.', N'1. Open Sales Agent and paste the prompt with your partner.
2. Look at what they have delivered in the specific solution area you are considering, not their overall record.
3. Note where the record thins out. A partner with three closed deals and nothing recorded since is a different proposition from one with steady flow.
4. Treat this as the capability half only. Nothing here tells you whether they have anyone available.', N'The partner you are assessing. The work you are considering routing to them.', N'The partner''s recorded delivery grouped by outcome and solution area, with the gaps in the record noted.', N'The PSS decides what the delivery record actually evidences. A partner who closed several deals two years ago with a team that has since left looks identical in the record to one delivering now, and the record has no way of showing you the difference.', N'Look at what the partner has actually delivered', N'Capability is the half of partner readiness we have evidence for. Getting it from the record rather than from the relationship is what makes the routing decision defensible when it is questioned.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-CAP-02', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 2, N'Ask about capacity without implying doubt', N'Prepare the conversation that establishes whether a partner actually has people available, which no system will tell you.', N'Featured', N'Both', N'I need to find out whether a partner genuinely has capacity to take on [describe the work], and our systems cannot tell me. Here is what I know about their delivery record: [paste your findings]. Help me prepare that conversation: how to ask about available people without implying I doubt them, what answers would tell me they are overcommitted, how to respond if they say yes when the evidence suggests otherwise, and how to leave the door open if the answer is no. Do not tell me whether to route the work.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the case where they say yes and you do not believe them. That is the hard one and it is common.
3. Ask about named people and current commitments rather than about capacity in general. General questions get general reassurance.
4. Decide in advance what you will do with a no. A partner who can say no safely will tell you the truth next time.', N'The partner and what you are considering routing to them. Your delivery-record findings.', N'A prepared capacity conversation with the tell-tale answers identified and a safe route to no.', N'The PSS decides whether a named-people answer is specific enough to route work on. A partner naming individuals and dates has given you something checkable; a partner describing capability in general has not, and accepting the second because the first felt intrusive is how work gets routed to a firm rather than to a team.', N'Ask about capacity without implying doubt', N'Nothing in our systems shows partner capacity. It only comes from a conversation, and how you ask determines whether the answer is real.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'PSS-CAP-03', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 3, N'Watch for the partner who has stopped moving', N'Set a standing check across your partners for the delivery signals that appear before a partner-led engagement stalls.', N'Featured', N'Both', N'Set up a recurring check across the partners I work with. Each time, show me for each partner-associated opportunity and referral: its current status, the date that status was last recorded, and how long it has held. Show the same for any partner with no recorded activity in the period. Report the elapsed times and do not classify anything as stalled, at risk or normal. Remember what you reported before so you can tell me which elapsed times have grown since last time.', N'1. Open Scout and confirm which partner and opportunity sources it can reach.
2. Choose your own cadence. Partner rhythms differ and a frequency that suits one portfolio buries another.
3. Decide for yourself what counts as too long for each partner. A quiet period that is routine for one partner is a warning for another.
4. Remember our record shows nothing about partner-side activity. Silence here is a prompt to ask, not a finding.
5. Prune what you track once you can see which categories actually move.', N'The partners you carry. The opportunities and referrals associated with each.', N'Elapsed time against each partner-associated record, with the times that have grown since the previous run identified.', N'The PSS decides what a gap in partner activity means. There is no general answer - partners work to their own cadence, and two weeks of quiet that is routine for one is a warning for another - so the elapsed time is a prompt to ask rather than a conclusion to act on.', N'Watch for the partner who has stopped moving', N'Elapsed time is a fact the record can supply. Whether a given elapsed time matters is a judgment about a specific partner relationship, and conflating the two produces either constant false alarms or a report nobody reads.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'PSS-CONV-01', N'WF-X-CONV-01', N'PSS-CONV', N'PH-PSS-CONV-EXPL', 1, N'Assemble what the partner already knows about themselves', N'Build the performance picture the partner will recognize, before you ask them for anything.', N'Featured', N'Both', N'[Partner name]', N'1. Open Know Your Partner and type the partner name or their PartnerOne ID.
2. Read the performance and program sections first. This is the version of the relationship they can also see.
3. Check the web-sourced context - recent news, acquisitions, expansion. That often explains a change in behavior better than any metric.
4. Note where it shows a placeholder rather than a figure. Missing data is not zero, and treating it as zero in front of a partner is expensive.
5. If you do not have access, assemble the same picture from partner performance reporting and continue with the rest of the workflow.', N'The partner and the conversation you have coming up.', N'A partner performance and context picture covering program participation, delivery and recent business developments.', N'The PSS decides which of this the partner would recognize as their own view. Our reporting measures what matters to Microsoft, and opening a conversation with figures the partner does not use is how a business discussion turns into a data argument.', N'Assemble what the partner already knows about themselves', N'Partners experience the relationship through their own numbers. Arriving with only our version guarantees the first ten minutes are spent reconciling rather than deciding.', N'https://aka.ms/KnowYourPartner', N'Open Know Your Partner'),
        (N'PSS-CONV-02', N'WF-X-CONV-01', N'PSS-CONV', N'PH-PSS-CONV-EXPL', 2, N'Reframe the ask in what their business gains', N'Turn a Microsoft priority into an ask expressed in the partner''s own economics.', N'Featured', N'Both', N'I want a partner to [describe the one thing you want them to do]. Here is what I know about their business and performance: [paste your partner picture]. Here is what I know about how they make money, and what I do not know: [describe their model and state the gaps]. Set out the questions I would have to answer before I could claim this is good for their business: what it would cost them, what they would gain, and over what period. For each question, say whether what I have given you answers it. Do not estimate any figure I have not supplied, do not construct a return calculation, and do not use Microsoft targets or incentive language.', N'1. Open Cowork, paste the prompt, and replace all three bracketed sections, including what you do NOT know.
2. Look at which questions your material cannot answer. Those are what you ask the partner, not what you assert to them.
3. Do not fill a gap with an estimate. A partner will recognize a number you invented about their own business immediately.
4. Reduce it to one ask, framed by the questions you can actually answer.', N'Your partner picture. The one thing you want the partner to do. Whatever you actually know about how they make money, including what you do not know.', N'The economic questions the ask depends on, marked by whether your material answers them, with the unanswerable ones turned into questions for the partner.', N'The PSS decides which economic claims can be made and which must be asked. A partner''s cost base is not visible to us, and a return figure constructed from our side is both wrong and recognisably wrong to the person who runs the business - which costs the credibility the ask depends on.', N'Reframe the ask in what their business gains', N'Partners commit to things that improve their business. Claiming to know their economics when you do not is how you get treated as a vendor rather than a partner.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'PSS-CONV-03', N'WF-X-CONV-01', N'PSS-CONV', N'PH-PSS-CONV-EXPL', 3, N'Rehearse the part where they push back', N'Prepare for the objection this partner will actually raise, rather than the conversation where they agree.', N'Extended', N'Both', N'I am asking a partner to [describe your reframed ask]. Here is our history: [describe what this partner has committed to before and what actually happened]. Help me rehearse the difficult part: what they are most likely to push back with, how to respond if they raise a past commitment we did not meet, what to do if they agree in the room but the history suggests they will not act, and how to close with something specific enough to follow up on. Do not tell me whether the ask is reasonable.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the response to a past Microsoft failure honestly. Deflecting it is remembered longer than the original failure.
3. Prepare for agreement-without-action specifically - it is the most common outcome and the hardest to name politely.
4. Close on something checkable with a date, and put it in writing the same day.', N'Your reframed ask and the partner picture. The history of what this partner has and has not done before.', N'A rehearsed conversation covering the likely pushback, the history, and a close specific enough to follow up.', N'The PSS decides which previous commitment is solid enough evidence to raise. A commitment that was implied, or made by someone who has since left, will be disputed and turns the conversation into a disagreement about history - so the judgment is whether this specific instance is documented well enough to survive being questioned.', N'Rehearse the part where they push back', N'The partner conversation that changes anything is the one where the difficult part was prepared. The rest is a status meeting with a friendlier name.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DAE-HEALTH-05', N'WF-X-HEALTH-01', N'DAE-HEALTH', N'PH-DAE-HEALTH-EXPL', 5, N'Let the territory tell you when it moves', N'Set a standing check across the territory so a change reaches you when it happens rather than at the next review.', N'Featured', N'Both', N'Set up a recurring weekly check across the accounts in my territory. Each week, show me where an opportunity has changed stage or close date, where a new signal or plan priority has arrived and how long it has before it expires, where a renewal date has moved inside twelve months, and where a partner referral has changed status. For each, state what changed and what the record does not tell us. Remember what you reported before so you can separate what is new from what I have already seen.', N'1. Open Scout and confirm which signal, opportunity and referral sources it can reach for your territory.
2. Run the prompt and set the cadence to land before your own pipeline review.
3. The first run reports everything. Read it once, then tune it to movement rather than inventory.
4. Act on expiring signals first - they are the only items on the list with a deadline you cannot negotiate.', N'Your territory of accounts. The signal, opportunity and renewal sources you can reach.', N'A weekly view of territory movement separating new changes from previously reported ones, with expiring items surfaced.', N'The DAE decides which movement needs action this week. A territory of this size generates change constantly and most of it is noise, so the judgment is which change alters what you were going to do anyway.', N'Let the territory tell you when it moves', N'At this territory size nothing surfaces on its own. The choice is between a standing check and finding out at the review, and the review is always too late for the signals that expire.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SMEC-CE-HEALTH-05', N'WF-X-HEALTH-01', N'SMEC-CE-HEALTH', N'PH-SMEC-CE-HEALTH-EXPL', 5, N'Keep watching the book between reviews', N'Set a standing check across the agreement book so commercial exposure surfaces before it becomes a renewal problem.', N'Featured', N'Both', N'Set up a recurring check across the agreements in my book that runs every two weeks. Each time, show me where an agreement end date has moved, where a new exception or amendment has been recorded, and where a renewal date has come inside the window I specify. Report only what has changed since the previous run. Do not assess commercial risk and do not recommend action.', N'1. Open Scout and set the check running against your book of agreements.
2. Run the prompt and set it to repeat every two weeks. Commercial exposure moves more slowly than pipeline and a weekly check would mostly report nothing.
3. Read the first run in full, then read only the changes after that.
4. Decide which movements need a conversation and which are administrative.', N'Your book of agreements. The consumption, amendment and renewal data you can reach.', N'A change-only view, refreshed every two weeks, of agreement dates moving, new exceptions recorded, and renewals entering the window.', N'The CE decides which movement is commercially material. An exception recorded on one account is administration; the same exception appearing repeatedly is a policy signal, and only someone reading across the book over time can tell which one they are watching.', N'Keep watching the book between reviews', N'Commercial exposure in this segment accumulates quietly across many small agreements. Nobody discovers it in a single review, because no single account looks like a problem.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SMEC-CE-POL-04', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 4, N'Read what the guidance actually says', N'Establish what published commercial and licensing guidance states on a question, before asking anyone to interpret it.', N'Extended', N'Both', N'I need to understand what published guidance says about [describe the policy, licensing or eligibility question]. Using approved Microsoft sources and authoritative public documentation, set out what the published position is, what conditions or exceptions the documentation names, what it explicitly does not cover, and where different sources say different things. Cite each source and give its date. Do not tell me whether it applies to my deal and do not resolve any conflict you find.', N'1. Open Researcher, paste the prompt, and replace the bracketed section.
2. Check the dates before the content. Commercial guidance gets revised without being re-read.
3. Where sources conflict, that is your question for the authoritative owner - not something to resolve yourself.
4. Take the citations with you when you ask. A question that shows what you have already read gets a faster and better answer.', N'The policy or licensing question your deal raises.', N'The published position with its conditions, its explicit gaps, and any conflicts between sources, each cited and dated.', N'The CE decides which fact about this deal takes it outside the published general case. Guidance is written for the standard shape and commercial eligibility turns on the specifics that differ, so the judgment is which of your deal''s particulars actually changes the answer - that is what determines whether you need a ruling or already have one.', N'Read what the guidance actually says', N'Arriving at the policy owner having read nothing wastes their time and yours. Arriving having read it and knowing exactly where it stops being clear is the difference between one exchange and four.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DSS-INV-01', N'WF-INVEST-01', N'DSS-INVEST', N'PH-DSS-INVEST-EXPL', 1, N'Establish what the deal actually looks like', N'Assemble the recorded facts that determine which investment routes are even open to this opportunity.', N'Featured', N'Both', N'For [opportunity name or ID] in my solution area, show what is recorded: the account, the products and workloads involved, the deal value and stage, any existing agreement and its type, whether a partner is associated and any co-sell or referral record, and any consumption or usage recorded on the account. Report what is recorded. Do not determine eligibility for any investment program and do not recommend a route.', N'1. Open Sales Agent and paste the prompt with your opportunity.
2. Note the partner association first. It changes which routes are even in scope.
3. Write down the barrier the investment would remove, in one sentence. If you cannot, investment is not the answer yet.
4. Take the facts and the barrier to the next step rather than deciding eligibility here.', N'One solution-area opportunity where customer investment might remove a barrier.', N'The recorded facts that bear on route selection, with the barrier the investment would remove stated in one sentence.', N'The DSS decides whether there is a real barrier that money removes. Investment attached to a deal that is simply slow does not speed it up, and a request built on a barrier nobody can name is declined late, after the effort has been spent.', N'Establish what the deal actually looks like', N'Route selection depends on facts about the deal that are already recorded. Starting from the program rather than the deal is how sellers end up building a case for a vehicle the opportunity never fitted.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-INV-02', N'WF-INVEST-01', N'DSS-INVEST', N'PH-DSS-INVEST-EXPL', 2, N'Find out what the routes actually require', N'Establish from published guidance what each candidate investment route requires, before choosing between them.', N'Featured', N'Both', N'I am considering customer investment for an opportunity with these characteristics: [paste the deal facts and the barrier]. Using approved Microsoft sources and authoritative internal documentation, set out what the published requirements are for each investment route that could apply, what evidence each requires, what each explicitly excludes, and where the documentation is silent. Cite each source and give its date. Do not tell me which route to use and do not assess whether my opportunity qualifies.', N'1. Open Researcher, paste the prompt, and replace the bracketed section.
2. Read the exclusions before the requirements. That is where most requests fail and it is the part least often read.
3. Check the dates. Investment guidance changes between fiscal years and last year''s version is still findable.
4. Where the documentation is silent, that is a question for the authoritative owner, not a gap for you to fill.', N'Your deal facts and the barrier you named. The routes you are considering.', N'Each candidate route''s published requirements, evidence and exclusions, cited and dated, with the silent areas identified.', N'The DSS confirms every eligibility reading with the authoritative owner rather than acting on the documentation alone. Published requirements describe the general case and investment decisions turn on specifics the documentation cannot see, so this shortens that conversation instead of replacing it.', N'Find out what the routes actually require', N'Sellers learn one route and apply it everywhere - the one that worked first. Reading what the alternatives actually require is the only way that habit gets corrected.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DSS-INV-03', N'WF-INVEST-01', N'DSS-INVEST', N'PH-DSS-INVEST-EXPL', 3, N'Write the case against the route you chose', N'Turn the barrier and the route requirements into a request that answers what that route actually asks.', N'Extended', N'Both', N'I am requesting customer investment through [name the route] for an opportunity. Here are the route''s published requirements: [paste them]. Here is the barrier and the deal context: [paste them]. Draft the request so that it answers each requirement in turn: what is being asked for, the barrier it removes, the evidence for that barrier, what changes if it is approved, and how that change would be observed. Mark any requirement I have not evidenced. Do not assert eligibility, do not estimate any figure I have not supplied, and do not claim approval is likely.', N'1. Open Cowork, paste the prompt, and replace all three bracketed sections.
2. Look at what it marks as unevidenced. Those are the questions a reviewer will ask first.
3. Make the observable change specific. "Accelerates adoption" is not something anyone can check afterwards.
4. Send it through the route''s own process rather than to whoever answered last time.', N'Your chosen route and its published requirements. The barrier and the deal facts.', N'A request answering each published requirement in turn, with unevidenced requirements marked and the observable change stated specifically.', N'The DSS states what will be observably different if the investment is approved. A request that promises acceleration without naming what would be measured is approved on trust and cannot be defended at review, which is what makes the next request from your team harder.', N'Write the case against the route you chose', N'Investment requests are compared against each other, not judged in isolation. The one that answers the stated requirements in order is easier to approve than a better opportunity described loosely.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'PSS-INV-01', N'WF-INVEST-01', N'PSS-INVEST', N'PH-PSS-INVEST-EXPL', 1, N'Check what this partner has already signed up to', N'Establish what program commitments a partner already carries before adding another one.', N'Featured', N'Both', N'For [partner name], show any co-sell or referral record currently open and the status and date of each, and any record showing a program or campaign this partner has been nominated into. For each, show whether it progressed after it was opened and the date of the last change. Report what is recorded. Do not assess their program eligibility and do not recommend an investment route.', N'1. Open Sales Agent and paste the prompt with your partner.
2. Look for records opened and never progressed. A partner carrying several of those has an acceptance habit rather than a delivery habit.
3. Check program participation in the partner reporting you have access to - our opportunity record shows nominations, not completions.
4. Decide whether this partner has room for another commitment before you offer one.', N'The partner and the opportunity you are considering investment for. Whatever partner program reporting you can reach.', N'The partner''s open commitments with the ones that never progressed identified, and a view on whether they have room for another.', N'The PSS decides whether this partner can absorb another commitment. Partners accept nominations readily and complete far fewer, so adding one to a partner already carrying unfinished commitments produces another unfinished commitment and makes the next conversation harder to have.', N'See what this partner has already been nominated for', N'A partner-led route only works if the partner does their part. What they have already agreed to and not delivered is the most direct evidence available, and it sits in a record nobody checks before nominating.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-INV-02', N'WF-INVEST-01', N'PSS-INVEST', N'PH-PSS-INVEST-EXPL', 2, N'Find out what the route asks of the partner', N'Establish from published guidance what a partner-led route requires the partner to do, not just what it offers.', N'Featured', N'Both', N'I am considering [name the partner-led investment route] for a partner opportunity. Using approved Microsoft sources and authoritative internal documentation, set out what the route requires from the PARTNER specifically: what they must nominate, what activity they must complete, what evidence they must produce, over what period, and what they receive in return. Also show what it requires from Microsoft. Cite each source and give its date. Do not assess whether this partner qualifies.', N'1. Open Researcher, paste the prompt, and replace the bracketed section.
2. Separate what the partner must do from what we must do, and list each partner obligation on its own line.
3. Note the period. A program requiring activity over two quarters is a different ask from one requiring a single nomination.
4. Take the partner-side obligations into the conversation with them rather than nominating first and explaining later.', N'The route you are considering and the partner it would run through.', N'The route''s partner-side obligations, Microsoft-side obligations, timeframe and partner return, cited and dated.', N'The PSS confirms the partner-side obligations with the authoritative owner before committing a partner to them. Program terms change between fiscal years and a partner told the wrong requirements will discover the real ones at the point they are being assessed, which costs the relationship rather than the program.', N'Find out what the route asks of the partner', N'Partner-led investment fails when the partner did not know what they had agreed to. The obligations are published, and nothing in the nomination flow requires anyone to read them.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'PSS-INV-03', N'WF-INVEST-01', N'PSS-INVEST', N'PH-PSS-INVEST-EXPL', 3, N'Get the partner to agree to their half', N'Prepare the conversation where the partner commits to what the route requires of them, rather than simply accepting a nomination.', N'Extended', N'Both', N'I want a partner to take part in an investment route that requires this of them: [paste the partner-side obligations]. Here is their record of completing what they have started before: [describe it]. Help me prepare the conversation: how to present the obligations without making it sound like paperwork, what they are likely to agree to in the room and not do, how to raise a previous unfinished commitment without it becoming an argument, and how to close on something specific enough to check. Do not tell me whether to nominate them.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse raising the unfinished commitment. Avoiding it guarantees the same outcome.
3. Get agreement on a named person on their side, not on the firm. A firm cannot complete an activity.
4. Confirm in writing the same day, with what they agreed and by when.', N'The route''s partner-side obligations. The partner''s record of completing what they start.', N'A prepared conversation covering the partner''s obligations, the previous record, and a close naming a person and a date.', N'The PSS decides how directly to raise a partner''s record of not finishing. Naming it risks the relationship; not naming it means nominating into the same outcome again, and only the person in the relationship can judge which this partner will take better.', N'Get the partner to agree to their half', N'A nomination is not a commitment. The conversation where the partner agrees to their specific half is the whole difference between a program that runs and one that appears in a report as unstarted.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DAE-INV-01', N'WF-INVEST-01', N'DAE-INVEST', N'PH-DAE-INVEST-EXPL', 1, N'Tell a funding barrier from a decision barrier', N'Assemble the recorded facts your role needs before contributing to an investment decision.', N'Featured', N'Both', N'For [account name], show what is recorded that would bear on whether investment could help: the open opportunities and their stage, any recorded blocker or objection, the existing agreement and its type, what is deployed against it, whether a partner is associated, and any recorded activity in the last six months. Report what is recorded and do not assess whether investment is appropriate.', N'1. Open Sales Agent and paste the prompt with your account or opportunity.
2. Separate what the record shows from what you have been told. Where those two disagree is the barrier worth naming.
3. Form your own view before reading anyone else''s assessment.
4. Route what you find to whoever owns the request rather than acting on it yourself.', N'One account where something is blocked and money might move it.', N'The account''s recorded position with the barrier stated, and your own read on whether it is one funding removes.', N'The DAE decides whether the barrier is one money removes. A customer who has not decided is not blocked by cost, and investment offered into indecision reads as discounting and is remembered as a price signal on the next deal.', N'Tell a funding barrier from a decision barrier', N'Investment is a lever for a specific class of barrier. Offering it against the wrong one trains the customer to wait for it.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DAE-INV-02', N'WF-INVEST-01', N'DAE-INVEST', N'PH-DAE-INVEST-EXPL', 2, N'Route it to whoever owns the request', N'Hand a recognized investment opportunity to its owner with enough evidence to be acted on.', N'Extended', N'Both', N'I have found an account where customer investment might remove a barrier. Here is what I found and the evidence: [paste your findings]. Draft a short note for whoever owns the investment request: the account, the barrier and what evidences it, what I have already confirmed, what I have not, and why I think investment is the lever rather than something else. Keep it brief. Do not assess eligibility and do not recommend an amount.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check that what you could not determine is as visible as what you found. Silence on a gap reads as a clear result.
3. Say what your role would still have to do. Requests are approved without that and then stall on it.
4. Send it to the named owner, not to a distribution list.', N'Your assessment and the evidence behind it. Who owns the investment request.', N'A short handover naming the account, the barrier and its evidence, with what you confirmed separated from what you did not.', N'The DAE hands over the barrier evidence and does not propose a figure. An amount suggested by the person who found the opportunity anchors the request before anyone has assessed eligibility, and a number that turns out to be wrong is remembered as the account team over-promising.', N'Route it to whoever owns the request', N'You see these barriers across more accounts than anyone. The value is only realized if the person who owns the request can act without a second conversation.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-INV-01', N'WF-INVEST-01', N'DSE-INVEST', N'PH-DSE-INVEST-EXPL', 1, N'Decide what would count as proof', N'Assemble the recorded facts your role needs before contributing to an investment decision.', N'Featured', N'Both', N'A customer investment would fund this technical work: [describe the work and what the customer doubts]. Define what it would need to demonstrate for the customer''s doubt to be resolved: the observable success criteria, what would constitute a clear negative result, the exit criteria that end the work either way, and the evidence a reviewer would need afterwards. Do not assume the investment is approved and do not estimate cost or duration.', N'1. Open Sales Agent and paste the prompt with your account or opportunity.
2. Separate the recorded technical position from what you were briefed. The gap is where the success criteria will have to do their work.
3. Form your own view before reading anyone else''s assessment.
4. Route what you find to whoever owns the request rather than acting on it yourself.', N'One proposed piece of technical work that customer investment might fund.', N'What the funded work would have to demonstrate, expressed as things somebody could observe happening.', N'The DSE decides how much the funded work must prove before the customer would act on the result. Proving too little leaves the doubt intact and the funding spent; proving too much turns a bounded piece of work into a project, and where that line sits depends on what this specific customer said they doubted.', N'Decide what would count as proof', N'Funded technical work is assessed at closure against whatever criteria existed at the start. If none did, the assessment becomes a matter of opinion and the next request is harder.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-INV-02', N'WF-INVEST-01', N'DSE-INVEST', N'PH-DSE-INVEST-EXPL', 2, N'Write the criteria down before the work is funded', N'Record the technical success and exit criteria in a form a reviewer can assess against afterwards.', N'Extended', N'Both', N'I have defined what an investment-funded piece of technical work must demonstrate. Here are my criteria: [paste them]. Write them up for the investment request: what will be demonstrated, how each will be observed, what would constitute a clear negative result, and the point at which the work stops either way. Mark anything I have written that could not actually be observed. Do not add criteria I have not stated and do not estimate effort or duration.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check that what you could not determine is as visible as what you found. Silence on a gap reads as a clear result.
3. Say what your role would still have to do. Requests are approved without that and then stall on it.
4. Send it to the named owner, not to a distribution list.', N'Your assessment and the evidence behind it. Who owns the investment request.', N'Success and exit criteria written for the request, with anything unobservable marked before it is submitted.', N'The DSE owns which criteria survive into the request. Criteria are negotiated down when the request is assembled, and the ones removed are the ones that would have shown a negative result - which is exactly what makes the remaining set unfalsifiable.', N'Write the criteria down before the work is funded', N'Criteria that live only in your head are renegotiated at closure by people who were not there. Written into the request, they set the terms of the assessment before anyone has a stake in the answer.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-INV-01', N'WF-INVEST-01', N'DCSA-INVEST', N'PH-DCSA-INVEST-EXPL', 1, N'Check the environment, not the opportunity', N'Assemble the recorded facts your role needs before contributing to an investment decision.', N'Featured', N'Both', N'An investment-funded engagement is proposed for [account name]: [describe the work]. Show me what is recorded about the account that bears on whether it could absorb this: the workloads deployed and what usage is recorded against them, any open or recently resolved support issues, whether a partner is associated, and the recorded technical activity in the last six months. Report what is recorded and do not assess readiness.', N'1. Open Sales Agent and paste the prompt with your account or opportunity.
2. Separate what the record shows from what you have been told. On a non-unified account the record is thinner, so the difference matters more.
3. Form your own view before reading anyone else''s assessment.
4. Route what you find to whoever owns the request rather than acting on it yourself.', N'One proposed investment-funded engagement and the account it would run on.', N'The account''s recorded technical position, with your read on whether this customer could absorb the funded work.', N'The DCSA decides which customer-side dependency would genuinely block delivery. Every engagement depends on something the customer must provide, and the judgment is which of those this particular customer will actually struggle with - the record shows what they have, not what they can take on.', N'Check the environment, not the opportunity', N'Investment converts into consumption only if the customer can absorb the work. In a portfolio of non-unified customers that is the assumption the request does not test.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-INV-02', N'WF-INVEST-01', N'DCSA-INVEST', N'PH-DCSA-INVEST-EXPL', 2, N'Name the dependency that would stop it', N'Set out the customer-side dependencies that would block funded delivery, and who would have to resolve each.', N'Extended', N'Both', N'I have assessed whether a customer could absorb investment-funded technical work. Here is what I found: [paste your findings]. Set out the customer-side dependencies that would have to be in place before the work could start or complete: what each is, who on the customer or partner side would have to provide it, and what happens to the engagement if it is not there. Separate the ones I have confirmed from the ones I am assuming. Do not assess whether the investment should proceed.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check that what you could not determine is as visible as what you found. Silence on a gap reads as a clear result.
3. Say what your role would still have to do. Requests are approved without that and then stall on it.
4. Send it to the named owner, not to a distribution list.', N'Your assessment and the evidence behind it. Who owns the investment request.', N'The customer-side dependencies that would block delivery, separated into those confirmed and those assumed.', N'The DCSA distinguishes a dependency the customer has been told about from one they have agreed to. Those look identical in any write-up and behave completely differently at delivery, and only the person who had the conversation knows which one it was.', N'Name the dependency that would stop it', N'Funded work can stall on a customer-side dependency that no technical review would surface, and the stall is recorded as a Microsoft delivery failure regardless of whose dependency it was. Testing for them is separate work from testing the technical plan.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-INV-01', N'WF-INVEST-01', N'SMEC-CE-INVEST', N'PH-SMEC-CE-INVEST-EXPL', 1, N'Test whether the structure survives without the investment', N'Check whether a commercial structure you are building depends on funding that has not been approved.', N'Featured', N'Both', N'For [account name], I am structuring a deal where customer investment is expected to form part of it. Show what is recorded: the existing agreement and its type, the products and quantities involved, any amendment or exception already recorded, the deal stage and value, and whether a partner is associated. Report what is recorded. Do not assess the investment, do not determine eligibility, and do not comment on approval.', N'1. Open Sales Agent and paste the prompt with your account.
2. Describe the structure twice: once assuming the investment arrives and once assuming it does not.
3. If the second version does not work, the structure depends on a decision you do not own. Say so now rather than at approval.
4. Route any eligibility or investment question to the role that owns it rather than answering it.', N'One deal you are structuring where customer investment is expected to be part of it.', N'The structure described with and without the investment, and any dependency on an unapproved decision made explicit.', N'The CE decides whether a structure that depends on unapproved investment should be presented at all. A structure contingent on someone else''s decision looks complete to a customer and to an approver, and the dependency only surfaces when the investment is declined and the commitment has already been made.', N'Test whether the structure survives without the investment', N'Investment decisions sit outside the CE''s authority in this segment, but the commercial consequence of one not arriving lands entirely on the structure. That exposure is worth seeing before the customer does.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-COMP-04', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 4, N'Rehearse the objection you know you will get', N'Prepare to meet the recurring competitive objection in the room, rather than only knowing what it is.', N'Featured', N'Both', N'I am going into a technical conversation where a competitor is in play. Here is the objection that comes up repeatedly: [paste the recurring objection you identified]. Here is what we can evidence and what I have decided to concede: [paste the criteria mapping]. Help me rehearse meeting it: how to acknowledge the part that is true without conceding the decision, what they are likely to say next, and how to respond if they press on something I have already decided to concede. Do not write competitive claims for me and do not tell me the competitor is wrong.', N'1. Open Agent J.ai and paste the prompt with the objection and your criteria mapping.
2. Practice the acknowledgement first. Decide how much of the objection you are willing to grant out loud.
3. Work the follow-up, not the opening. The opening is the part you have already thought about.
4. Say out loud the thing you decided to concede. If it sounds like a loss rather than a choice, it is not ready.
5. Take one sentence into the meeting, not a script.', N'The recurring objection from your competitive review, and the criteria you decided to contest and concede.', N'A rehearsed response to the recurring objection, with the acknowledgement and the concession both prepared as deliberate choices.', N'The DSS decides whether the rehearsed response is accurate and which part of it to withhold. Rehearsal smooths an answer, and a smoothed answer can acquire confidence the underlying evidence does not support, so what gets said is a separate decision from what was practiced.', N'Prepare to meet the objection you already know is coming', N'Knowing the objection and being ready to meet it are different states. Rehearsal is where you find out which one you are in.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'PSS-CAP-04', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 4, N'Decide whether this partner is ready, and who closes the gap', N'Put capability and capacity together into a readiness decision with a named owner and a date.', N'Featured', N'Both', N'Here is what the record shows about a partner''s delivery capability: [paste your findings]. Here is what they told me about capacity: [paste what they said, including anything vague]. Bring these together into a readiness view for [describe the work]. Separate what they have demonstrated from what they have asserted. Set out the candidate gaps with the evidence for each, the possible impact of each on this work, and what is not known. Do not rank the gaps for me, do not decide whether to proceed, and do not assume any gap can be closed.', N'1. Open Cowork and paste both halves - what the record showed and what the partner said.
2. Look first at anything demonstrated on one side and only asserted on the other. Demonstrated and asserted are different kinds of evidence and the difference is the point of this step.
3. Name one gap, not several. A readiness view with four gaps is a list, and lists do not get owned.
4. Decide who closes it and by when. If the honest answer is that you would close it yourself, that is a finding about this partnership rather than a plan.
5. Write down what happens to the work if the gap is not closed. That is the part that makes the date real.', N'Your findings on the partner''s delivery record, and what they said about capacity.', N'A readiness view with demonstrated capability separated from asserted capacity, the candidate gaps evidenced, and the seller''s chosen gap with a closing action, an owner and a date.', N'The PSS chooses which gap matters and names who closes it by when. The evidence supports several readings and selecting among them is the decision; an unowned gap has no date, and a readiness view without a date has not decided anything.', N'Turn the two halves of partner readiness into one decision', N'Capability and capacity are each half an answer. The decision that routes work needs both, joined, with somebody''s name on what is missing.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-HEALTH-04', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 4, N'Check whether the technical explanation actually holds', N'Test the most likely technical cause against documented behavior before raising it with anyone.', N'Featured', N'Both', N'I have a hypothesis about why a customer''s workload is behaving the way it is. Here is what I observed and what I think is causing it: [describe the movement and your suspected technical cause]. Here is the configuration as far as I know it: [describe the workload and any relevant settings]. Using approved Microsoft and authoritative internal documentation, tell me whether this cause is consistent with documented behavior for this configuration. Give me at most three documented alternatives that would produce the same symptom on this configuration, and for each, what I would need to observe to tell them apart. Cite each claim. Where the documentation does not settle it, say so rather than choosing.', N'1. Open Researcher and paste the prompt with your observation and your suspected cause.
2. Read the alternative explanations before the confirming ones. You already believe your own.
3. Check the citations reach current documentation. A behavior that changed in a recent release is the case this step is for.
4. Note what you would need to observe to separate the explanations. That is your question for the customer''s team.
5. Decide whether your hypothesis survived. If it did not, say so now rather than carrying it into the conversation.', N'The account you ranked highest, what you observed, and your suspected technical cause.', N'The hypothesis either retained or rejected, with up to three documented alternatives and the observation that would separate them, each claim sourced.', N'The DCSA decides whether the hypothesis survives contact with the documentation, and which observation would settle it. Documentation describes the general case and this customer is a specific one, so consistency raises confidence without confirming, and carrying an unrejected hypothesis forward as a finding is how a technical conversation goes wrong before it starts.', N'Test the technical hypothesis before you take it to a customer', N'A ranked list tells you which account to look at, not what is wrong with it. Testing the explanation is what turns a suspicion into something worth a customer''s time.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'SMEC-CE-RENEW-05', N'WF-X-RENEW-01', N'SMEC-CE-RENEW', N'PH-SMEC-CE-RENEW-EXPL', 5, N'Check the renewals that arrived without you', N'Work through renewal opportunities created automatically and decide which of them describe a renewal you would stand behind.', N'Featured', N'Both', N'Show me the renewal opportunities in my book that were created automatically rather than by me, using their creation date between [start date] and [end date]. For each, show the account, the recorded value and currency, the close date, the enrollment or agreement record it was built from, the product or SKU lines attached, and the forecast category currently set. Report what is recorded. Do not assess whether any value, date or line is correct.', N'1. Open Sales Agent and paste the prompt with your start and end dates.
2. For each opportunity, validate four things yourself against the agreement and the customer: the account it landed on, the value and currency, the close date, and the product or SKU lines attached.
3. Correct what is wrong and add what is missing - contacts, and any required field - before the opportunity progresses to the next stage.
4. Where the renewal should not exist at all, say so and route it rather than editing it into something plausible.
5. Set the forecast category yourself. The record existing is not the same as you committing to it.
6. Pick the one where what arrived differs most from what you would have entered, and work out why. That gap is the thing worth discussing.', N'Your renewal book for the period, including opportunities you did not create. The underlying agreement or enrollment record for anything you intend to correct.', N'Auto-created renewals reviewed with account, value, close date and product lines each confirmed or corrected, forecast category set by the CE, anything that should not exist routed rather than edited, and one flagged difference between what arrived and what was expected.', N'For each auto-created renewal the CE decides one of three things: accept it as it stands, correct it against the agreement, or reject it as a renewal that should not be in the book. The CE also decides whether and when to set a forecast category, which is the point at which the record becomes a commitment rather than a suggestion.', N'Own the renewals that arrived in pipeline without you', N'A renewal that appears in pipeline without anyone deciding it belongs there is a forecast entry nobody has stood behind. The work is no longer creating the record, it is deciding whether to own it.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'ALL-CLOSEDWON-01', N'WF-X-PIPE-01', N'ALL-CLOSEDWON', N'PH-ALL-CLOSEDWON-EXPL', 1, N'Find the closes you cannot account for', N'List recent closed-won opportunities in your book and separate the ones you closed from the ones that closed some other way.', N'Featured', N'Both', N'Show me the opportunities in my book that were marked closed won with a close date in the last [state a short period, for example 30 days]. For each, show the account, the value, the close date, the products or SKU lines attached, and the recorded close reason or status if one is set. Report what is recorded. Do not assess whether any close was correct.', N'1. Open Sales Agent and paste the prompt with a short recent period. Keep it small enough to read in one sitting.
2. Go down the list and mark the ones you do not remember closing. You are working from your own memory of the deal here, not from a field.
3. For each one you marked, ask whether you can account for the value, the products and the date. Mark anything you cannot.
4. Take the marked ones forward. If there are none, say so - that is a result worth the room hearing.', N'Your own opportunities and the date range you want to review.', N'Recent closed-won opportunities with the ones the seller cannot account for identified, or an explicit statement that there were none.', N'The seller decides which closes they can account for. A closed record can be well-formed and still describe something that did not happen, and the check is whether the value, products and date match what was actually sold.', N'See which of your deals closed without you closing them', N'A closed record carries your number whether or not you set it. A wrong one raises no error and blocks nothing, so it survives until somebody has to explain it.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'ALL-CLOSEDWON-02', N'WF-X-PIPE-01', N'ALL-CLOSEDWON', N'PH-ALL-CLOSEDWON-EXPL', 2, N'Work out what to do about the one you cannot explain', N'Take a closed record you cannot account for and decide whether to accept it, correct it, or raise it.', N'Featured', N'Both', N'Here is a closed-won opportunity I cannot fully account for: [paste the record - account, value, close date, close reason, products]. Here is what I know was actually happening on this account: [paste what you know - what was sold, what was signed, what was delivered, what was still open]. Lay out where the record and my account knowledge agree, where they disagree, and what would settle each disagreement. Do not tell me whether the close was correct.', N'1. Open Cowork and paste both the record and what you know about the account.
2. Work the disagreements, not the agreements. The agreements are why you did not notice sooner.
3. Decide which of four this is: the close is right and you had forgotten; it is wrong on detail you are able to correct yourself; it is wrong in a way that needs somebody else; or you cannot yet tell and need to check something first.
4. If it is yours to correct, correct it now while you still have the context.
5. If it needs somebody else or more evidence, write down what you checked and what you found, so the next person does not start from nothing.', N'One closed record you could not account for, and what you know was happening on that account.', N'One questionable close resolved into accepted, corrected by the seller, routed to whoever can act on it, or held pending a specific check.', N'The seller decides whether the record matches what was sold, and whether the correction is theirs to make or somebody else''s. Account knowledge is one input rather than the deciding one, and a correction made without the contract in front of you replaces one wrong record with another.', N'Decide what to do about a close you cannot account for', N'A wrong close is easy to leave alone because nothing breaks. It shows up later as revenue that cannot be explained or a customer conversation that starts from a false position.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'CSA-VSAT-01-P01', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 1, N'Watch the satisfaction signals across a live delivery', N'Gather the delivery signals that show how the customer is experiencing the work.', N'Featured', N'Prompt', N'For [Customer] and [delivery or engagement], set up a recurring check on the signals that show how the customer is experiencing this delivery: open issues and how long they have been open, escalations, missed or moved dates, response times, and questions left unanswered. Report what changed since the last check rather than restating everything. Separate what the record shows from what is inferred, and state what the record cannot see. My delivery context is [global delivery, field delivery or SME&C coverage]; reflect that in which signals you treat as material.', NULL, N'Delivery status, open issues, escalation history, milestone dates; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'A recurring satisfaction signal watch showing what changed since the last check, separating evidence from inference.', N'The CSA decides which signals reflect the customer''s experience rather than internal process noise. A record with no open issues can still describe a customer who has stopped telling us about them.', N'Monitoring and signal', N'The signals are usually already in the record. The work is looking before the survey does.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSA-VSAT-01-P02', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 2, N'Rank the satisfaction risks by what the customer would say', N'Turn the signals into a ranked view of what this customer would raise if asked today.', N'Featured', N'Prompt', N'Using the delivery signals for [Customer], rank what this customer would most likely raise if asked about their experience today. For each item give the specific moment behind it, who owns it, and whether it is still fixable within this delivery. Separate what is evidenced from what is inferred.', NULL, N'Satisfaction signal summary, delivery timeline, role ownership; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Ranked satisfaction risks with owner and a fixable or not-fixable call.', N'The CSA confirms each ranked item traces to a specific moment. A risk with no moment behind it is a feeling, and it will not survive the conversation with the account team.', N'Analysis and prioritization', N'Ranking by what the customer would say, rather than by what is easiest to fix, is what makes this worth doing.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-VSAT-01-P03', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 3, N'Build the satisfaction recovery action', N'Turn the top satisfaction risk into an action with an owner and a date.', N'Featured', N'Both', N'Take the top satisfaction risk for [Customer] and draft the recovery action: what will change, who owns it, what the customer will see and by when, and what we will say to them about it. Keep it to something deliverable inside this delivery.', N'1. Take the highest-ranked satisfaction risk.
2. State what the customer would see change, not what we would do internally.
3. Name the owner and the date.
4. Decide what is said to the customer and by whom.
5. Route anything that is not yours.', N'Ranked satisfaction risks, delivery timeline, account team roles; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'One satisfaction recovery action with owner, date and customer-visible change.', N'The CSA confirms the action is one the customer would notice. An internal process fix the customer never sees does not move satisfaction.', N'Synthesis and drafting', N'A satisfaction risk without a customer-visible action is a note. This is the step that changes the score.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'CSA-VSAT-01-P04', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 4, N'Check the risk against what the record supports', N'Test the satisfaction read against the evidence before taking it to the account team.', N'Extended', N'Prompt', N'Review this satisfaction read for [Customer]. For each claim, state whether the delivery record supports it, partly supports it, or does not support it. Identify anything asserted without evidence and anything the record cannot show either way.', NULL, N'Satisfaction read, delivery record, escalation history; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Evidence check with unsupported claims identified.', N'The CSA decides what to take forward. Raising an unsupported satisfaction claim with the account team costs credibility on the ones that were real.', N'Validation and evidence', N'Satisfaction claims get challenged. Checking them first is what lets you hold the position.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'CSA-TECHLEAD-01-P01', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 1, N'Map what the customer''s direction will demand of you', N'Work out which technical topics this customer''s roadmap will require you to be credible on.', N'Featured', N'Prompt', N'For [Customer], based on their stated technical direction, current estate and announced priorities, identify the technical topics they will need advice on over the next two to four quarters. Rank by how soon they will need it and how central it is to their direction. State what is known versus assumed.', NULL, N'Customer technical direction, current estate, announced priorities; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Ranked list of technical topics the customer will need advice on.', N'The CSA confirms this reflects the customer''s direction rather than Microsoft''s product roadmap. The two are not the same, and only one of them determines what the customer asks you.', N'Research and synthesis', N'The list of things worth knowing is set by the customer. Starting anywhere else is how good effort gets spent on the wrong topic.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'CSA-TECHLEAD-01-P02', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 2, N'Compare that against what you can defend today', N'Set the customer''s coming demands against what you could hold a conversation on now.', N'Featured', N'Prompt', N'Take this ranked list of technical topics for [Customer]. For each, help me separate what I could hold an advisory conversation on today, what I could speak to but not defend under challenge, and what I would have to route to a specialist. Ask me what I need to answer honestly rather than assuming.', NULL, N'Ranked technical topics, your own recent customer conversations; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Honest gap map across can defend, can discuss, and must route.', N'The CSA answers this honestly rather than aspirationally. A gap map that flatters you produces a plan that closes nothing.', N'Assumption testing', N'Most credibility gaps are known and unstated. Writing them down is most of the work.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-TECHLEAD-01-P03', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 3, N'Find where you were the bottleneck', N'Look back at where a question had to go to someone else, and what that cost.', N'Extended', N'Prompt', N'Looking across my recent customer engagements, identify where a technical question had to be routed to someone else, where a decision waited on an answer I could not give, and where I deferred a topic more than once. Group them by topic and show which ones recur.', NULL, N'Recent engagement history, meeting and escalation records; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Recurring topics where you were the routing point rather than the answer.', N'The CSA decides which routing was appropriate and which was a gap. Bringing in a specialist is often the right call, and treating every handoff as a personal shortfall points the plan at the wrong thing.', N'Analysis and assessment', N'The gaps that cost the most are the ones that recur. They are visible in your own history if you look.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-TECHLEAD-01-P04', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 4, N'Build the credibility plan for one gap', N'Turn the highest-value gap into a specific plan with a first step this week.', N'Featured', N'Both', N'Take the highest-value technical gap and build a plan to close it: what being credible on this looks like in a customer conversation, the smallest first step, what I will use to get there, how I will test whether it worked, and the date I will have it by. Keep it to one gap.', N'1. Pick the gap the customer will hit soonest.
2. State what credible looks like in their words, not ours.
3. Name the smallest first step.
4. Decide how you will test it, ideally on a real conversation.
5. Put a date on it.', N'Gap map, customer timeline, available time; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'A one-gap credibility plan with a first step and a date.', N'The CSA keeps this to one gap. A plan covering every gap is a plan that closes none of them before the customer needs the answer.', N'Synthesis and drafting', N'One closed gap before the customer needs it beats a broad plan that arrives after they asked.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DAE-SIGNAL-SCOUT-01', N'WF-X-SIGNAL-01', N'DAE-SIGNAL', N'PH-DAE-SIGNAL-EXPL', 5, N'Be told a signal is expiring instead of finding out', N'Set a standing watch on the signal queue so the ones approaching expiry surface without anyone going to look.', N'Featured', N'Both', N'Watch my signal queue and tell me, on a schedule I set, which signals are approaching expiry, which have moved since the last check, and which have gone quiet after an initial response. Rank by how close they are to expiring and how warm the account looked. Carry forward what you told me last time so I can see what I acted on and what I let go.', N'1. Set the cadence to match how fast your queue turns over, not how often you would like to look.
2. Say what counts as approaching expiry for your motion.
3. Ask it to report movement since the last check rather than the whole queue.
4. Check the first run before you trust the second.
5. After two weeks, look at what you consistently let go and decide whether that is a judgment or a capacity problem.', N'Access to your signal queue, the expiry window that applies to your motion, and the cadence you want to be told on.', N'A standing watch on the signal queue reporting what is close to expiry and what has moved since the last check, rather than a one-time list.', N'The DAE decides which expiring signals are worth the contact. A queue ranked by expiry date tells you what runs out first, not what is worth pursuing, and working the queue in date order is how the good accounts get the least attention.', N'Monitoring and signal', N'A signal you find on the day it expires is a signal you have already lost. Being told earlier is the whole difference.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'DSS-SIGNAL-SCOUT-01', N'WF-X-SIGNAL-01', N'DSS-SIGNAL', N'PH-DSS-SIGNAL-EXPL', 5, N'Watch for the engagement that turns into real intent', N'Set a standing watch across your solution area so repeat engagement surfaces as it builds rather than after the window has closed.', N'Featured', N'Both', N'Watch engagement across the accounts in my solution area and tell me, on a schedule I set, where activity is repeating or building rather than one-off, where a signal has gone quiet after I responded, and where the same pattern is showing up across more than one account. Carry forward what you reported last time so I can see what built and what faded.', N'1. Set the cadence and the accounts in scope.
2. Say what repeat engagement looks like in your solution area.
3. Ask for what changed since the last check, not the full picture.
4. Review the first run before relying on it.
5. Use the cross-account patterns to decide where your solution area is actually landing.', N'The accounts in your solution area, access to the engagement signals for them, and the cadence you want to be told on.', N'A standing watch across the solution area showing where engagement is building, where it went quiet after a response, and the patterns appearing across more than one account.', N'The DSS decides what repeat engagement means. Activity that repeats can be a buying signal or one person doing their research, and the difference is not in the count.', N'Monitoring and signal', N'A pattern across several touches says something a single event does not, and watching for it by hand is the part that does not get done.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-X-CONV-01-P-ATS-NARR-JAI', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 4, N'Pressure-test the options and tradeoffs with an executive', N'Practice putting the real decision, its options and its tradeoffs to an executive.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the executive who has to make this decision. I will present the options and their tradeoffs rather than a recommendation. Push back where an option sounds like a pitch, where a tradeoff has been softened, or where what this executive is personally backing has not been named. Pause for my response before coaching me on whether the decision was put clearly and the tradeoffs stated honestly. Do not invent customer facts or commitments.', NULL, N'The approved narrative; the decision being asked for; the options and their tradeoffs; who the executive is and what they are accountable for.', N'A rehearsed decision conversation, the objections raised, and coaching on where an option was pitched rather than offered.', N'The ATS decides which tradeoffs are material enough to put in front of this executive. Review the downsides the rehearsal raises and add the material ones it missed, since not everything it raises bears on the decision being made.', N'Conversation rehearsal', N'An executive decision put badly sounds like a pitch. Rehearsing it is how you hear the difference before they do.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'CSAM-ESCALATE-JAI', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 5, N'Rehearse the escalation conversation before you have it', N'Practise telling a customer something has gone wrong, before the call.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the customer stakeholder I have to tell about this escalation. Use the approved status position, the validated escalation brief and the commitment boundaries I am pasting below, and ask me for anything missing before you begin. Play them as someone who is frustrated and wants a date I cannot yet give. Push back where I over-commit, where I soften the impact, or where I explain the cause instead of saying what happens next. Pause for my response before coaching me on whether I was clear about what is known, what is not, and when they will hear from me again. Do not invent facts about the incident.', NULL, N'The validated escalation brief; the stakeholder and what they care about; the approved communication position; what you cannot yet commit to.', N'A rehearsed escalation conversation, the objections raised, and coaching on where you over-committed or softened the impact.', N'The CSAM decides what can be said about cause and timing before the facts are settled. Rehearsal makes an answer fluent, and a fluent answer about an unresolved incident is easy to hear as a commitment.', N'Conversation rehearsal', N'How an escalation is handled shapes the relationship long after the incident closes. Rehearsing it is cheaper than improvising it while they are angry.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai')
    ) v([ExternalId], [TopicExternalId], [PlacementExternalId], [PhaseExternalId], [DisplayOrder], [Name], [Description], [PracticeTier], [ExecutionMethod], [Prompt], [ActivitySteps], [RequiredContext], [ExpectedOutput], [HumanCheckpoint], [BestFitJob], [WhyThisMatters], [LaunchUrl], [LaunchLabel])
), src AS (
    SELECT raw.*, t.Id AS [HuddleTopicId], p.Id AS [HuddlePlacementId], ph.Id AS [HuddlePhaseId]
    FROM raw
    INNER JOIN dbo.HuddleTopics AS t ON t.[ExternalId] = raw.[TopicExternalId]
    INNER JOIN dbo.HuddlePlacements AS p ON p.[ExternalId] = raw.[PlacementExternalId]
    INNER JOIN dbo.HuddlePhases AS ph ON ph.[ExternalId] = raw.[PhaseExternalId]
)
MERGE dbo.HuddleActivities AS tgt
USING src ON tgt.[ExternalId] = src.[ExternalId]
WHEN MATCHED THEN UPDATE SET
        tgt.[HuddleTopicId] = src.[HuddleTopicId],
        tgt.[HuddlePlacementId] = src.[HuddlePlacementId],
        tgt.[HuddlePhaseId] = src.[HuddlePhaseId],
        tgt.[DisplayOrder] = src.[DisplayOrder],
        tgt.[Name] = src.[Name],
        tgt.[Description] = src.[Description],
        tgt.[PracticeTier] = src.[PracticeTier],
        tgt.[ExecutionMethod] = src.[ExecutionMethod],
        tgt.[Prompt] = src.[Prompt],
        tgt.[ActivitySteps] = src.[ActivitySteps],
        tgt.[RequiredContext] = src.[RequiredContext],
        tgt.[ExpectedOutput] = src.[ExpectedOutput],
        tgt.[HumanCheckpoint] = src.[HumanCheckpoint],
        tgt.[BestFitJob] = src.[BestFitJob],
        tgt.[WhyThisMatters] = src.[WhyThisMatters],
        tgt.[LaunchUrl] = src.[LaunchUrl],
        tgt.[LaunchLabel] = src.[LaunchLabel],
        tgt.[UpdatedAtUtc] = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT ([ExternalId], [HuddleTopicId], [HuddlePlacementId], [HuddlePhaseId], [DisplayOrder], [Name], [Description], [PracticeTier], [ExecutionMethod], [Prompt], [ActivitySteps], [RequiredContext], [ExpectedOutput], [HumanCheckpoint], [BestFitJob], [WhyThisMatters], [LaunchUrl], [LaunchLabel], [CreatedAtUtc])
    VALUES (src.[ExternalId], src.[HuddleTopicId], src.[HuddlePlacementId], src.[HuddlePhaseId], src.[DisplayOrder], src.[Name], src.[Description], src.[PracticeTier], src.[ExecutionMethod], src.[Prompt], src.[ActivitySteps], src.[RequiredContext], src.[ExpectedOutput], src.[HumanCheckpoint], src.[BestFitJob], src.[WhyThisMatters], src.[LaunchUrl], src.[LaunchLabel], SYSUTCDATETIME());
;WITH raw AS (
    SELECT * FROM (VALUES
        (N'DSE-DISC-01', N'WF-X-DISC-01', N'DSE-DISC', N'PH-DSE-DISC-EXPL', 1, N'Find out who has already spoken to this customer', N'Establish what is already known about the estate and who holds the rest, before you take a single question to the customer.', N'Featured', N'Both', N'For [account name], show me what is already recorded about their technical estate: the products and workloads in place and when they were deployed, any open support or delivery issue, the opportunities open and what they are for, every recorded activity and which role it came from, and whether a partner or co-sell record exists on the account. Report only what the record contains. Do not describe what any partner has done - that is not in MSX.', N'1. Open Sales Agent and paste the prompt with your customer.
2. Read the activity list by role. Whoever has been active is the person who knows what is not written down.
3. If a partner record exists, check the Partner Timeline view or Partner Center - the partner may have run discovery of their own.
4. Write down what the record answers, and what it only appears to answer.', N'One customer where you are about to start technical discovery.', N'What the record already establishes about the estate, and the named colleagues or partners likely holding the rest.', N'The DSE decides what the record genuinely establishes versus what it merely mentions. A workload appearing in the record says it was bought rather than how it was configured, and the configuration is what you will be held to when you design against it.', N'Prior discovery', N'At this customer count you are arriving after a partner and a seller have both already been there. Starting from what they found is faster than starting again and does not spend the customer''s patience.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-DISC-02', N'WF-X-DISC-01', N'DSE-DISC', N'PH-DSE-DISC-EXPL', 2, N'Test your criteria against what they already run', N'Check draft decision criteria against the customer''s recorded estate, and work out which ones a partner would have to satisfy.', N'Featured', N'Both', N'Here are the technical decision criteria I am proposing for [account name]: [paste your draft criteria]. Show me what that customer has deployed today and, for each criterion, whether anything in the record bears on it - an existing workload, an open support issue, a prior opportunity - or whether the record says nothing. Do not assess technical effort or judge whether a criterion is reasonable. I want to know which of these the record can already speak to.', N'1. Draft your criteria first. This is your judgment, not the agent''s.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Criteria the record says nothing about are the ones you will have to establish with the customer or the partner.
4. Mark which of those a delivery partner would have to satisfy rather than you.
5. Agree the surviving set with the DAE before it reaches the customer.', N'Your draft technical decision criteria, and the customer they are for.', N'Your criteria split by whether the record already speaks to them, with the partner-satisfied ones marked.', N'The DSE writes the criteria and decides which a partner could realistically meet. A criterion only the engineer can satisfy quietly commits you to every future deal of that shape, and at this customer count that is a commitment you cannot keep.', N'Decision criteria', N'Criteria written for yourself do not survive being handed to a delivery partner. Checking them against what the customer already runs is the cheap part; deciding who can meet them is the part that matters.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-DISC-03', N'WF-X-DISC-01', N'DSE-DISC', N'PH-DSE-DISC-EXPL', 3, N'Find where the technical record has gone quiet', N'Rank the technical record by how long each part of it has gone without an update, then decide what you still have to verify yourself.', N'Extended', N'Both', N'For [account name], show me how current the technical record actually is. For each deployed product and workload give the date it was last updated, list any open support or service record with the date it last moved, and name the areas where nothing has been logged in the last [number] months. Sort by longest silence first, and lead with the gaps rather than a full inventory of the estate.', N'1. Open Sales Agent, paste the prompt, and replace both bracketed sections - the account and the number of months you want checked.
2. Read the dates, not just the facts. Silence is not evidence either way: it means no entry was found in MSX for that period, not that nothing happened or that nobody recorded it somewhere you cannot see.
3. Now do the part the agent cannot: decide which of these facts you will confirm with a person before you design against them, and which are safe to take as read.', N'The customer, and how far back you want the currency check to run.', N'The technical record ranked by how long each part of it has gone untouched, with anything showing no entry inside the chosen period named separately.', N'The DSE owns the design and therefore decides which recorded facts are safe to build on. A fact nobody has touched in a long time is not necessarily wrong, and the difference between an inaccuracy caught at design time and one found in production is entirely a matter of which fact it was.', N'Verification', N'You cannot verify everything at this customer count. The record will not tell you what is true, but it will tell you which facts are fresh and which have gone untouched long enough to be worth checking before you design against them.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PROOF-01', N'WF-X-ARCH-01', N'DSE-PROOF', N'PH-DSE-PROOF-EXPL', 1, N'Look for the proof before you build one', N'Check whether you or a colleague have already proven this, at a customer with a comparable estate.', N'Featured', N'Both', N'I need to prove [describe what the customer doubts] for a customer running [describe their estate]. Across the opportunities in my patch, show me any where a similar workload or configuration was involved, what stage they reached, and any recorded notes, objections or outcomes. For each, show what the customer environment looked like. Do not assume a similar environment means the same proof will transfer.', N'1. Open Sales Agent, paste the prompt, and replace both bracketed sections.
2. Look for the closest environment rather than the closest product name.
3. If something transfers, find out who ran it before rebuilding it.
4. If nothing transfers, you now know why this one is genuinely new.', N'The technical doubt to be settled, and the customer''s environment as you understand it.', N'Comparable prior work identified with an honest read on whether it transfers, or a clear statement that this proof is genuinely new.', N'The DSE judges whether a prior proof actually transfers. Two customers on the same product can differ in the one respect the proof depended on, and a borrowed proof that quietly does not apply is worse than building a new one, because nobody re-examines it.', N'Reuse', N'A bespoke proof for every customer does not survive the customer count in this segment. Reuse is the constraint that makes the job possible, and it only works if somebody looks first.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PROOF-02', N'WF-X-ARCH-01', N'DSE-PROOF', N'PH-DSE-PROOF-EXPL', 2, N'Cut your proof down before you build it', N'State the proof you are considering, then test it against what comparable customers actually needed.', N'Featured', N'Both', N'A customer at [account name] is unsure about [describe the doubt]. I am considering this proof: [describe the proof you have in mind]. Across the opportunities in my patch, show me any where a similar doubt or objection was recorded, what was proposed, what stage the opportunity reached, and any note about what convinced the customer. Do not design a proof or judge whether mine is the right size.', N'1. Write down the proof you have in mind first, including what it will not cover. That scoping is yours.
2. Open Sales Agent, paste the prompt, and replace all three bracketed sections.
3. Look at what actually convinced comparable customers. It is frequently smaller than what was offered.
4. Cut yours to the smallest version that still settles the doubt, and write down explicitly what it excludes.
5. Get the customer to agree that this settles it, before you build anything.', N'The customer, what they are unsure about, and the proof you are considering including its exclusions.', N'Your proposed proof tested against what comparable customers actually needed, cut to the smallest sufficient version with exclusions stated.', N'The DSE decides what the customer is really doubting, which is frequently not what they asked to see. A request for a pilot is often a request for reassurance about operational effort, and building the pilot answers a question nobody had while leaving the real one open.', N'Proof scope', N'Proof work expands to fill whatever time it is given, and at this customer count that time comes straight out of another customer. What convinced somebody comparable is the cheapest available check on your own scoping.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PROOF-03', N'WF-X-ARCH-01', N'DSE-PROOF', N'PH-DSE-PROOF-EXPL', 3, N'Leave it in a state the next engineer can use', N'Spend the extra hour that makes this proof reusable, rather than rebuilding it from memory next quarter.', N'Extended', N'Both', N'I have built a proof demonstrating [describe what it shows] for a customer running [describe the environment]. Help me write it up so another engineer could reuse it: what it demonstrates, what environment it assumes, what it deliberately does not cover, what would have to change for a different customer, and what someone should check before reusing it. Write it for an engineer who was not involved. Do not include the customer name, contact details, or anything identifying them.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Read the assumptions section as somebody who was not there. Anything implicit will be missed.
3. Remove anything identifying the customer.
4. Put it where your colleagues will actually find it, and tell the ones covering similar estates.', N'The proof you built, what it demonstrates, and the environment it assumed.', N'A reuse note covering what the proof shows, what it assumes, what it excludes, and what to check before reusing it, with the customer anonymized.', N'The DSE states what the proof deliberately does not cover. A reuse note that lists only capabilities gets applied to a situation it was never valid for, and the engineer who inherits the failure will not know which assumption broke.', N'Reusability', N'Reuse only works if somebody wrote down the limits. The capabilities are obvious from the artifact; the boundaries exist only in the head of whoever built it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-CONV-01', N'WF-X-CONV-01', N'DSE-CONV', N'PH-DSE-CONV-EXPL', 1, N'Work out what was actually asked', N'Reconstruct the customer''s real question from the version that reached you second-hand.', N'Featured', N'Both', N'A technical question has reached me through a partner or seller. Here is how it was relayed: [paste the question as you received it]. It concerns [account name]. Using what is recorded about that customer''s estate, help me work out what they might actually be asking. Give the most likely readings, what each would imply about their concern, and the single clarifying question that would tell them apart. Do not answer the question yet.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Read the alternative readings against what the customer actually runs.
3. If two readings need completely different answers, ask the clarifying question before answering.
4. Answering the wrong reading confidently costs more than the delay of asking.', N'The relayed question as you received it, and the customer it concerns.', N'The plausible readings of the question with the one clarifying question that would resolve them.', N'The DSE decides whether to answer or to ask. A relayed question has already lost the tone and the follow-up that would have disambiguated it, and answering the wrong reading with confidence is how a technically correct answer becomes a customer problem.', N'Relayed question', N'You are not in the room in this segment, so every question arrives already translated once. Treating the relayed wording as the actual question is how engineers give confidently wrong answers.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-CONV-02', N'WF-X-CONV-01', N'DSE-CONV', N'PH-DSE-CONV-EXPL', 2, N'Write an answer that survives being forwarded', N'Produce a technical answer for the person who will relay it, not for a technical peer.', N'Featured', N'Both', N'Here is a technical question about [account name]: [state the question you have established]. Here is my answer: [paste your answer in your own words]. Rewrite it for a partner or seller who will relay it to the customer and who is not a specialist in this area. Lead with the direct answer, then the conditions it depends on. Keep every qualification I have written - do not simplify one away. Mark clearly which parts must be passed on word for word and which can be summarized. Do not add technical claims I have not made.', N'1. Write your answer first, in your own words. The technical content is yours.
2. Open Cowork, paste the prompt, and replace all three bracketed sections.
3. Check nothing has been added that you did not say, and no qualification has been softened.
4. Read it as the relayer. If a sentence needs you present to make sense, rewrite it.
5. Check the word-for-word section is genuinely short - if everything is marked critical, nothing is.
6. Check it against the CELA rules before it goes to a partner: no personal data, no seat or spend detail, nothing resembling an export.', N'The question you have established, your own technical answer, and the account. The CELA rules on partner data exchange.', N'Your answer rewritten for relay, with qualifications intact, the must-not-paraphrase parts marked, and the data-sharing boundary checked.', N'The DSE writes the technical answer and checks that nothing was added or softened in the rewrite. A model asked to make an answer clearer will drop the qualification that made it accurate, and the person relaying it has no way to know a sentence went missing.', N'Relay-safe answer', N'An answer written for a technical peer gets compressed by whoever passes it on, and the part they drop is the qualification. Having it rewritten for the relayer is useful; letting it be written from scratch is how a confident wrong answer reaches a customer.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-CONV-03', N'WF-X-CONV-01', N'DSE-CONV', N'PH-DSE-CONV-EXPL', 3, N'Work out what is not yours to answer', N'Identify the parts of a technical question that belong to product, legal, security or commercial owners, and route them.', N'Extended', N'Both', N'Here is a technical question I have been asked about [account name]: [state the question]. Break it into its separate parts and, for each, say whether answering it needs current product behavior, an unreleased or roadmap capability, licensing or commercial terms, or a security, legal or compliance position. Do not answer any part and do not suggest who should own it.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. You route these, not the agent. Licensing and commercial go to your CE; security and compliance to the authoritative owner.
3. Anything touching roadmap goes nowhere near a customer until it has shipped.
4. Answer your part fully and name who is picking up the rest, so the question does not stall.', N'The technical question and the account it concerns. Your CE for anything commercial, and the authoritative owner for security or compliance.', N'The question split by the kind of answer each part needs, with your portion answered and the rest routed by you to a named owner.', N'The DSE answers the technical part and routes the rest rather than being helpful across the boundary. An engineer''s answer about licensing or a roadmap date is read as authoritative because it came from the technical person, and it is repeated long after it stops being true.', N'Answer boundary', N'A relayed question arrives as one question and unpacks into several. Splitting it is what stops an engineer accidentally giving a commercial commitment.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DSE-HEALTH-01', N'WF-X-HEALTH-01', N'DSE-HEALTH', N'PH-DSE-HEALTH-EXPL', 1, N'Find who else is running the thing you know breaks', N'Take a problem you have already met and find the other customers exposed to it.', N'Featured', N'Both', N'I have found a technical problem at one customer: [describe the configuration or workload and what goes wrong]. Across the accounts in my patch, show me which others have the same workload or product combination deployed, with what is recorded about their deployment and any open support issue. Do not conclude that a matching product list means the same problem is present.', N'1. Open Sales Agent and paste the prompt with your problem described.
2. Treat the output as a list of customers to check, not a list of customers affected.
3. Narrow it using what you know about the configurations rather than the product names.
4. Order the survivors by how visible the failure would be to the customer.', N'A technical problem you have already diagnosed at one customer. The accounts in your patch.', N'The customers plausibly exposed to the same problem, narrowed by configuration rather than product match, and ordered by customer-visible impact.', N'The DSE decides which matches are genuinely exposed. A product list is not a configuration, and two deployments that share a product name can differ in exactly the setting that determines whether the problem occurs.', N'Pattern exposure', N'You do not operate any of these environments and there are too many to inspect. The only scalable way to find a problem before the customer does is to already know its shape.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-HEALTH-02', N'WF-X-HEALTH-01', N'DSE-HEALTH', N'PH-DSE-HEALTH-EXPL', 2, N'Check whether the problem is already being worked', N'Find out whether an exposed customer already has a support issue open on the problem, before you warn anyone about it.', N'Featured', N'Both', N'For these customers [list the exposed accounts], show every support or service issue recorded in the last six months: what it concerns, when it was raised, its current status, and whether it has been resolved. Show the deployed workloads alongside so I can see which issues touch the configuration I am worried about. Report only what is recorded and do not judge whether any issue relates to my problem.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list.
2. Read the open issues first. An issue already raised on the same workload means somebody found this before you.
3. A resolved issue on the same configuration is worth reading too - it may be the fix you were about to describe.
4. Only for accounts with nothing recorded should you check the Partner Timeline view, since a partner may be working it outside our systems.
5. Warn only the customers where nobody appears to be on it.', N'Your list of exposed customers from the previous activity.', N'The exposed customers split by whether an issue is already open, already resolved, or nothing is recorded at all.', N'The DSE decides whether an existing issue is actually the same problem. Support records describe a symptom in the customer''s words rather than the cause in yours, and a ticket that looks unrelated is often the same fault reported by someone who did not know what they were seeing.', N'Partner awareness', N'Most of these environments are operated by somebody else, so a problem you have just spotted has often already been raised by the people living with it. Warning them about it costs you standing you will need later.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-HEALTH-03', N'WF-X-HEALTH-01', N'DSE-HEALTH', N'PH-DSE-HEALTH-EXPL', 3, N'Send the fix to whoever can actually apply it', N'Write the problem up so the person who operates the solution can act on it without needing you.', N'Extended', N'Both', N'I need to tell the people operating a solution about this problem: [describe the problem, the trigger, and the fix]. Draft a short technical note for whoever operates the environment: what the symptom looks like, what causes it, how to confirm whether they are affected, and what to do about it. Write it for a competent engineer who was not involved in the original design. Keep it to what is technically necessary and exclude customer names, personal data, seat counts and spend figures.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check the confirm-whether-affected step is something they can actually run themselves.
3. Remove anything a partner should not receive under the CELA rules.
4. Send it, and record where you sent it so this does not come back to you as new in three months.', N'The problem, its trigger and its fix. The partners or customer teams operating the affected environments. The CELA rules on partner data exchange.', N'A technical note the operating team can act on unaided, with the check they can run themselves and the customer detail removed.', N'The DSE decides whether the note is genuinely actionable by somebody who was not there, and checks it against the data rules before it goes to a partner. A problem report that requires the author to explain it will sit unactioned, and the customer will find the problem first.', N'Routing the fix', N'You are not going to fix these yourself across this many customers. The work is making the fix travel, and a note that needs you attached to it does not travel.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-PART-01', N'WF-X-PARTNER-01', N'DCSA-PARTNER', N'PH-DCSA-PARTNER-EXPL', 1, N'Find out what is actually behind each account', N'Establish which accounts have a delivery partner genuinely engaged and which have a support agreement, because on these accounts one of those may be all there is.', N'Featured', N'Both', N'For these accounts [list up to fifteen accounts from your portfolio], show two things. First, whether any support or services agreement is recorded on the account, and of what kind. Second, whether a partner is associated, with any co-sell or referral record and its recorded status and dates. Report only what the record contains and do not describe what any partner is doing or infer what support entitlement implies.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list with up to fifteen of your accounts.
2. Read the support agreement column first. An account with neither an agreement nor an engaged partner has nothing behind it at all.
3. An association is not an engagement - check the dates before assuming anyone is active.
4. For anything that looks live, open the Partner Timeline view or Partner Center; partner-side progress is only visible there.
5. Rank by what would happen at each account if something broke tomorrow.', N'Up to fifteen accounts from your portfolio.', N'Your accounts sorted by what is actually behind them: an agreement, an engaged partner, both, or nothing.', N'The DCSA decides what counts as an engaged partner and what an absent agreement really means for a given account. A referral accepted eight months ago and a partner deploying this week look identical in our record, and an account with neither is one where your own time is the entire coverage.', N'Partner engagement', N'At this coverage ratio you are not the delivery mechanism, the agreement or the partner is. Knowing which accounts have neither tells you where a problem becomes yours by default.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-PART-02', N'WF-X-PARTNER-01', N'DCSA-PARTNER', N'PH-DCSA-PARTNER-EXPL', 2, N'Write a handover the partner can act on without you', N'Turn your own technical assessment into something a partner engineer can execute, inside the rules that govern what may be shared.', N'Featured', N'Both', N'I need to hand technical work to a delivery partner at [account name]. Here is my assessment and what I want done: [paste your own technical assessment and the work required]. Restructure this for a competent engineer at the partner who was not in any of my conversations: what the situation is, what needs doing, what order, and what they should check to confirm it worked. Do not add technical steps or recommendations I have not written. Exclude contact names and details, seat counts, spend figures, and anything that reads as an export from our systems.', N'1. Write your technical assessment and the required work first. That content is yours.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Check nothing technical has been added that you did not write.
4. Read it as the partner engineer. Anything that assumes a conversation they were not in has to be spelled out.
5. Check it against the CELA rules before sending: no personal data, no seat or spend detail, nothing resembling an export.', N'One account, and your own technical assessment of what needs doing. The CELA rules on partner data exchange.', N'A partner-executable technical handover derived from your own assessment, checked for added content and for the data-sharing boundary.', N'The DCSA owns the technical content and confirms nothing was invented in the restructuring, then checks it against the data rules before it goes out. A partner engineer will execute what is written without knowing which line came from you and which was generated to make the sequence read well.', N'Technical handover', N'Without a Unified agreement there is no delivery manager to interpret your intent. The handover is the whole intervention, and if it needs you attached to it, nothing happens.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-PART-03', N'WF-X-PARTNER-01', N'DCSA-PARTNER', N'PH-DCSA-PARTNER-EXPL', 3, N'Decide how you will know it worked', N'Name the observable signal that would tell you the partner''s work landed, before you stop thinking about the account.', N'Extended', N'Both', N'I have handed technical work to a partner at [account name]. The intended technical outcome is [describe what should change if it worked]. Show me what is currently recorded for that account that relates to it: deployed workloads, open or resolved support issues, recorded activity, and any usage or consumption figures held in the record. Show the current state only. Do not project what should happen or judge whether the work will succeed.', N'1. Open Sales Agent, paste the prompt, and replace both bracketed sections.
2. Take this as your baseline and write it down with today''s date.
3. Decide which single observable would change if the work landed, and by when you would expect it.
4. Put that check in your calendar. Nothing else in the week will surface it.
5. If the observable is not visible in any record you can reach, you need the partner to report it - agree that now, not later.', N'One account with work handed to a partner, and your own definition of what would change if it succeeded.', N'A dated baseline of what is currently recorded, with one observable signal and a date to check it.', N'The DCSA defines what would count as success and whether it is observable at all. Some technical outcomes leave no trace in any system we can see, and finding that out now rather than in three months is the difference between a check you can run and a hope.', N'Verification', N'Work handed to a partner without a check is work you have stopped tracking. At this account count nothing will bring it back to your attention until the customer escalates.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-CONV-01', N'WF-X-CONV-01', N'DCSA-CONV', N'PH-DCSA-CONV-EXPL', 1, N'Pick the one thing worth their attention', N'Assemble what is known about the account and choose the single technical priority, on the assumption you get one conversation.', N'Featured', N'Both', N'For [account name], show me what is recorded: the products and workloads deployed and when, any open or recently resolved support issue, any usage or consumption figures held in the record, recent activity and which role it came from, and whether a partner is associated. Present it as a factual summary. Do not rank the findings by importance or recommend what to focus on.', N'1. Open Sales Agent and paste the prompt with your account.
2. Read it for what is missing as much as for what is there.
3. Now do the part the agent cannot: decide the single technical thing that most needs to be right at this customer.
4. Build the conversation around that one thing and let the rest go.', N'One customer with a technical conversation coming up.', N'A factual account summary, with your own decision on the single technical priority for the conversation.', N'The DCSA chooses the priority. The record shows what was bought and what has broken, but which risk actually matters for this customer depends on what they are trying to do, and a summary that ranks findings would be ranking them on the wrong criteria.', N'Single priority', N'With one conversation available, covering everything means the customer leaves with nothing. Choosing is the work, and it is not something the record can do for you.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-CONV-02', N'WF-X-CONV-01', N'DCSA-CONV', N'PH-DCSA-CONV-EXPL', 2, N'Leave something behind that works without you', N'Turn your technical guidance into a short written artifact the customer or their partner can act on after you have moved on.', N'Featured', N'Both', N'I am advising [account name] on [state the priority you have chosen]. Here is my guidance in my own words: [paste your guidance]. Turn it into a short written note for the customer''s own technical people and whoever supports them, covering what to do, in what order, what to check afterwards, and what would indicate it is going wrong. Do not add recommendations I have not written. Keep it to one page and write it for someone who was not in the conversation.', N'1. Write your guidance first, in your own words. The technical judgment is yours.
2. Open Cowork, paste the prompt, and replace all three bracketed sections.
3. Check nothing has been added, and that no caveat you wrote has been smoothed away.
4. Test it against the question: could they follow this in three months with you unavailable?
5. Send it to the customer and, if a partner supports them, to the partner as well.', N'One customer, your chosen technical priority, and your own guidance written out.', N'A one-page durable note the customer or their partner can act on without you, derived from your own guidance.', N'The DCSA owns the guidance and confirms nothing was added in the rewrite. Advice that gets acted on months later with nobody available to interpret it has to be right as written, and a generated clarification that changes the meaning will not be caught by the person following it.', N'Durable guidance', N'At this coverage the value you leave is more durable than the value you deliver in the room. A conversation with nothing written down is gone the week after.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-CONV-03', N'WF-X-CONV-01', N'DCSA-CONV', N'PH-DCSA-CONV-EXPL', 3, N'Name who has this account after you', N'Establish which Microsoft roles have been active recently and who realistically holds the technical relationship next.', N'Extended', N'Both', N'For [account name], list every recorded activity in the last six months with the date and the role it came from, and show any open support issue with its recorded owner. Show the roles by how recently each was active. Do not include partner or co-sell records, and do not infer who is responsible for the account technically.', N'1. Open Sales Agent and paste the prompt with your account.
2. If the only recent activity is yours, that is the finding.
3. Decide who realistically holds this next - the DAE, a partner you already identified, or nobody - and be honest about the last option.
4. Tell them, and tell the customer who to contact. An unnamed successor is the same as none.', N'One customer you are unlikely to revisit soon.', N'The Microsoft roles active on the account ordered by recency, with a named technical successor or an explicit acknowledgement that there is not one.', N'The DCSA decides who genuinely picks this up, including the honest answer that nobody does. Naming a successor who has not agreed is worse than admitting the gap, because the customer will call someone who is not expecting them.', N'Succession', N'Accounts at this coverage ratio quietly lose their technical contact and nobody notices until something breaks. Saying out loud that there is no successor is what turns it into a decision somebody can make.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-VALUE-01', N'WF-X-VALUE-01', N'DCSA-VALUE', N'PH-DCSA-VALUE-EXPL', 1, N'Work out which accounts left any trace of delivery', N'Establish which of your accounts have a delivery record behind them and which have nothing but telemetry, because that determines what you can ever evidence.', N'Featured', N'Both', N'For these accounts [list up to fifteen accounts where you believe the technical outcome was good], show for each whether a support or services agreement is recorded, any support issue raised and how it was resolved, any milestone or success activity logged, and any usage or consumption figures held in the record. Separate the accounts that produced some record of delivery work from those where the only thing recorded is the purchase and whatever usage figures exist. Do not infer an outcome from deployment or from usage.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list.
2. The accounts with no delivery record are the normal case here, not the failures. That is what non-Unified looks like.
3. For those, usage figures are the only evidence that will ever exist, so decide now whether they say anything useful.
4. For the accounts that did produce a record, check whether the work recorded is actually connected to the outcome you have in mind.
5. Pick the account with the strongest case and carry it into the attribution step.', N'Up to fifteen accounts where you believe the technical outcome was good.', N'Your accounts split by whether any delivery record exists, with an explicit read on what can be evidenced for those where none does.', N'The DCSA decides whether usage figures alone amount to evidence of an outcome. On an account with no delivery record they are all there is, and consumption showing a service running is a much weaker claim than a customer saying it solved something.', N'Evidence base', N'A Unified engagement leaves milestones and hours behind it. Most of these accounts leave nothing, so knowing which ones produced any record at all tells you where a value story is even possible before somebody asks you for one.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-VALUE-02', N'WF-X-VALUE-01', N'DCSA-VALUE', N'PH-DCSA-VALUE-EXPL', 2, N'Separate what you did from what the partner did', N'Establish who actually performed the delivery work, so that outcomes are described by whoever earned them.', N'Featured', N'Both', N'For these accounts [list your evidenced accounts], show what the record says about work performed: each recorded activity with its date and the role it came from, each support issue with who logged it and who resolved it, and the dates workloads were deployed. Report the recorded actors only. Do not infer who was responsible for any outcome and do not summarize contribution.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list.
2. Our record captures what Microsoft logged. On a partner-delivered account that is a fraction of what happened, and the gaps are the partner''s work.
3. Where a partner delivered, the outcome is theirs to describe and yours to acknowledge.
4. If you want to use a partner-delivered outcome, ask them rather than reconstructing it from our record.', N'Your evidenced accounts from the previous activity.', N'Recorded delivery work attributed by actor, with the partner-delivered outcomes identified as theirs to describe.', N'The DCSA decides what is honestly ours to claim. Our record shows what Microsoft logged, which on a partner-delivered account is a small fraction of what happened, and presenting that fraction as the whole story is visible to the partner immediately.', N'Attribution', N'On non-Unified accounts the partner may have done most of the delivery. Getting attribution right is not politeness, it is the thing that keeps the partner willing to do it again.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-VALUE-03', N'WF-X-VALUE-01', N'DCSA-VALUE', N'PH-DCSA-VALUE-EXPL', 3, N'Get the evidence to whoever owns the renewal', N'Pass the technical evidence to the account and commercial roles before the renewal conversation happens without it.', N'Extended', N'Both', N'For [account name], I have technical evidence of the outcome delivered. Here is what I can evidence: [paste what you established]. Draft a short internal note for the account executive and the commercial executive covering what was delivered, what the evidence is, what the partner contributed, and what remains unproven. Keep it brief and factual. Do not add claims I have not made and do not characterize the commercial implications.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check nothing has been added, particularly anything that reads as a commercial recommendation.
3. Say plainly what remains unproven. A note that only lists wins is discounted by whoever reads it.
4. Send it to the DAE and the CE, and note the renewal date so you know whether it arrived in time.', N'One account with evidenced technical outcomes, your own summary of them, and the renewal date if known.', N'A brief factual internal note for the account and commercial roles, stating what is evidenced, what the partner contributed, and what is not proven.', N'The DCSA states what is not proven alongside what is. A technical note that reads as advocacy gets discounted entirely by the people preparing a renewal, and the unproven items are exactly what they need to know before they meet the customer.', N'Renewal handoff', N'Renewal conversations belong to the account and commercial roles. Technical evidence that stays with the architect does not reach them, and at this coverage nobody will come and ask for it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'PSS-DEM-01', N'WF-X-OPP-01', N'PSS-DEMAND', N'PH-PSS-DEMAND-EXPL', 1, N'Separate what you know from what you were told', N'Establish what our own record can independently confirm about an opportunity a partner brought you.', N'Featured', N'Both', N'A partner has brought me an opportunity at [account or company name]. Here is what they have told me: [paste what the partner told you]. Show me what our record independently contains about that customer: whether they exist as an account and under whose ownership, any products or workloads already in place, any prior or open opportunity, any recorded activity and from which role, and any existing partner association. State plainly which of the partner''s claims our record can speak to and which it cannot. Do not assess whether the opportunity is likely to close.', N'1. Open Researcher, paste the prompt, and replace both bracketed sections.
2. Read the cannot-speak-to list first. That is the part you are taking on the partner''s word.
3. If the account is owned by a DAE, tell them before you invest anything.
4. Decide how much Microsoft resource you will commit against the unverifiable portion, and be explicit that you are choosing to.', N'One opportunity brought to you by a partner, and what the partner told you about it.', N'The partner''s claims split into what our record can confirm and what rests entirely on their word, with an explicit decision on what to invest against the latter.', N'The PSS decides how much to invest against a claim only the partner can make. Their qualification bar is not ours and their incentive is to get Microsoft engaged, and a partner who is habitually right about this is a different proposition from one who is not, which is a judgment about the relationship rather than about the deal.', N'Inbound qualification', N'Every other role in this segment sends work out to partners. You also receive it, and what arrives has been qualified by somebody with a different standard and a different interest in the answer.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'PSS-DEM-02', N'WF-X-OPP-01', N'PSS-DEMAND', N'PH-PSS-DEMAND-EXPL', 2, N'Check the conditions before anyone counts on it', N'Establish whether a partner-originated deal meets the recorded conditions for registration, before it is treated as one.', N'Featured', N'Both', N'For [opportunity name or ID], show me what is recorded that bears on co-sell registration: the account and whether it is Microsoft-managed, the recorded deal value and currency, the solution area and products attached, the opportunity creation date, and the current stage and status. Also show any existing co-sell or referral record on the opportunity with its dates. Report only what is recorded and do not assess eligibility.', N'1. Open Sales Home and paste the prompt with the opportunity.
2. Check the recorded facts against the conditions yourself: a Microsoft-managed account, Azure IP co-sell eligibility, a value of at least twenty-five thousand US dollars, and at least seventy-two hours between creation and being marked won.
3. Anything you cannot confirm from the record, confirm with the authoritative owner rather than assuming.
4. Tell the partner what is missing now. Finding out at close is too late for both of you.', N'One partner-originated opportunity. The current co-sell registration conditions from the authoritative source.', N'The recorded facts assembled against the registration conditions, with the gaps identified and raised with the partner early.', N'The PSS confirms eligibility against the authoritative source rather than against a summary. Registration conditions change and a deal that fails one at close costs the partner real money, which is the kind of thing that ends a partnership rather than a deal.', N'Registration', N'The conditions are checkable long before close, and nothing prompts anyone to check them until it is nearly there. The whole cost of getting this wrong lands on the partner, and they will remember.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-DEM-03', N'WF-X-OPP-01', N'PSS-DEMAND', N'PH-PSS-DEMAND-EXPL', 3, N'Find the partner who keeps letting things lapse', N'Look across your partners for the ones whose referrals and co-sell records consistently stall, because that is a relationship problem rather than a record problem.', N'Extended', N'Both', N'For these partners [list three to five partners], show me the co-sell and referral records associated with each: the account, the recorded status, the date the record was created, and the date of the last recorded change. Group the output by partner. Report the recorded dates only - do not calculate elapsed time, judge which are close to expiring, or compare the partners.', N'1. Open Sales Home, paste the prompt, and replace the bracketed list with three to five of your partners.
2. Do the arithmetic yourself against the windows: fourteen days for a partner to accept a referral before it expires, sixty days after acceptance to convert before it is marked lost.
3. Read down each partner rather than across all the records. One lapsed referral is an accident; a partner with several is a conversation.
4. Check anything near a boundary in the Partner Timeline view or Partner Center, since our recorded status can lag what the partner has already done.
5. Chase the individual items with days left, and raise the pattern with the partner who has one.', N'Three to five partners from your portfolio. The Partner Timeline view or Partner Center for anything near a boundary.', N'Records grouped by partner with the window arithmetic done by you, separating one-off lapses from a partner-level pattern.', N'The PSS decides whether a pattern of lapsed records is a capacity problem, a fit problem, or a partner who was never going to work them. Those need completely different conversations, and the records look identical in all three cases.', N'Window management', N'Individual expiring referrals are chased by whoever sent them. Nobody else is positioned to notice whether the lapses concentrate on one partner, and that is the finding worth having.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-ORCH-01', N'WF-X-ORCH-01', N'PSS-ORCH', N'PH-PSS-ORCH-EXPL', 1, N'Decide which partners need you this month', N'Triage a portfolio of partners into the ones with something to decide and the ones that only need contact.', N'Featured', N'Both', N'For these partners [list three to five partners], show for each: the co-sell and referral records currently associated with them and the recorded status of each, and any opportunity where they are the associated partner along with its stage and the date it last moved. Group the output by partner. Do not rank the partners, compare them, or recommend where to spend time.', N'1. Open Sales Agent, paste the prompt, and replace the bracketed list with three to five partners.
2. Look for partners with something stalled or something approaching a decision - those need a meeting with an agenda.
3. Partners with everything moving need a check-in, not a meeting.
4. Separately, check your own cadence commitment: a minimum of monthly contact per partner seller. Anyone you have not spoken to in that window needs contact regardless of what the record shows.
5. Split the month into meetings that need preparation and contacts that satisfy the cadence.', N'Three to five partners from your portfolio, and your own record of when you last spoke to each.', N'Those partners split into meetings that need an agenda and contacts that meet the cadence commitment.', N'The PSS decides which partner genuinely needs time this month. Activity in the record tracks how much business is flowing rather than how much attention the relationship needs, and meeting a cadence minimum is a floor rather than a plan.', N'Portfolio triage', N'A minimum contact cadence is an obligation, not a strategy. Without a deliberate split the calendar fills with the partners who ask for time, and the meetings that needed preparation get none.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-ORCH-02', N'WF-X-ORCH-01', N'PSS-ORCH', N'PH-PSS-ORCH-EXPL', 2, N'Give the meeting something to decide', N'Turn a recurring partner meeting into one with a decision attached, using what has actually moved.', N'Featured', N'Both', N'I have a partner meeting with [partner name]. Show me what has changed on their associated records since a month ago where the record supports that: opportunities that moved stage, co-sell or referral records created or changed status, and any new recorded activity. Also show what has not moved. Present the changes factually and do not propose an agenda or suggest what to discuss.', N'1. Open Sales Agent, paste the prompt, and replace [partner name].
2. The things that have not moved are the meeting. The things that have moved are the update.
3. Pick one decision you want out of the conversation and build the agenda around it.
4. Send the partner the decision you want to reach beforehand, so they can arrive able to make it.', N'One partner with a meeting coming up.', N'A factual read on what has and has not moved for that partner, with one decision chosen and sent ahead as the agenda.', N'The PSS chooses the decision the meeting is for. What has not moved may be a partner problem, a Microsoft problem or a customer problem, and walking in with the wrong attribution turns a working session into a defensive one.', N'Meeting agenda', N'Recurring partner meetings drift into status reporting, which both sides can do by email. A meeting with a decision attached is the only kind worth the cadence.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-ORCH-03', N'WF-X-ORCH-01', N'PSS-ORCH', N'PH-PSS-ORCH-EXPL', 3, N'Find out who else is talking to your partner', N'Establish which Microsoft roles are engaged with the same partner, so the partner is not receiving three different asks.', N'Extended', N'Both', N'For these accounts where [partner name] is engaged [list three to five accounts], show which Microsoft roles have recorded activity on each in the last quarter and the date of the most recent from each role. Present it account by account with the roles named. Do not infer coordination or judge whether the engagement is aligned.', N'1. Open Sales Agent and paste the prompt with your partner and three to five of the accounts they work.
2. Look for accounts where several roles are active - the partner may be receiving conflicting asks.
3. Look for accounts where only the partner appears and no Microsoft role does.
4. Raise the conflicts at the territory health review rather than by chasing each role individually.', N'One partner, and three to five accounts where they are engaged.', N'The accounts where your partner is engaged, showing which Microsoft roles are active on each and where nobody is.', N'The PSS decides whether several roles engaging one partner is coordination or confusion. The record shows activity rather than intent, and a partner being asked for different things by three people will do the easiest one and tell nobody.', N'Internal alignment', N'Partners work with many people at Microsoft, and one receiving mixed messages does not necessarily say so; they prioritize. Seeing the overlap is the only way to find out it is happening.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-VAL-01', N'WF-X-VALUE-01', N'PSS-VALUE', N'PH-PSS-VALUE-EXPL', 1, N'Find out what happened after one partner''s deals closed', N'Take a single partner and establish what our record knows about the customers they closed, and where it goes silent.', N'Featured', N'Both', N'For [partner name], show me the opportunities recorded as closed won where they are the associated partner, going back two quarters. For each, show the account, the close date, and then what has been recorded on that account since that date: any activity and from which role, any support issue, and any usage or consumption figures held in the record. Show the most recent record date for each account alongside the close date. Do not infer customer satisfaction or outcome from any of it.', N'1. Open Sales Agent, paste the prompt, and replace [partner name] with one partner.
2. Look at the gap between each close date and the most recent record. That gap is what Microsoft cannot see.
3. Read it as a pattern for this partner rather than as a list of accounts. If every one of their customers goes silent immediately, that tells you something about how they work.
4. Long silence is not evidence of a problem or of success. It is the normal condition when a partner owns the relationship.
5. Pick the customer where not knowing would cost the most, usually one with a renewal ahead.', N'One partner whose closed deals you want to understand.', N'The visibility gap across one partner''s closed customers, read as a pattern for that partner, with the customer where it matters most identified.', N'The PSS decides where a gap in our visibility actually matters. Silence after a partner-led close is normal rather than alarming, and treating every quiet customer as a risk will exhaust both your time and the partner''s patience.', N'Visibility gap', N'Our record ends roughly where the customer''s experience begins on these deals. Looking partner by partner rather than account by account shows you whether the blind spot is about one customer or about how that partner works.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-VAL-02', N'WF-X-VALUE-01', N'PSS-VALUE', N'PH-PSS-VALUE-EXPL', 2, N'Ask the partner something worth answering', N'Draft the question that gets a partner to tell you how a customer is actually doing, without it reading as an audit.', N'Featured', N'Both', N'I want to ask [partner name] how a customer is getting on since they closed and delivered. Here is what I already know from our record: [paste what you found]. Draft a short message asking about the customer''s experience and any difficulty they have hit. Write it as a colleague with a shared interest in the customer, not as an inspection. Keep it to a few lines. Do not request seat counts, consumption figures, financial detail or anything commercially sensitive, and do not imply any obligation to report to us.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Read it as the partner. If it sounds like a request for a status report, it will be answered like one.
3. Check it against the CELA rules in both directions - what you are asking for as well as what you are sharing.
4. Send it, and be ready to offer something in return. A question with nothing behind it gets a short answer.', N'One partner and one customer they closed, plus what our record already shows. The CELA rules on partner data exchange.', N'A short colleague-to-colleague question about a specific customer, checked against the data rules and with something offered in return.', N'The PSS owns how this reads to the partner. A partner has no obligation to report customer outcomes to Microsoft, so the answer depends entirely on whether the question sounds like interest or like inspection, and only the person in the relationship can judge which.', N'Asking the partner', N'This is the only route Microsoft has back to a customer a partner owns. Getting the tone wrong does not just fail to get an answer, it makes the next question harder.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'PSS-VAL-03', N'WF-X-VALUE-01', N'PSS-VALUE', N'PH-PSS-VALUE-EXPL', 3, N'Get what you learn back to the people who need it', N'Pass what a partner tells you about a customer to the account and commercial roles, without overstating what you were told.', N'Extended', N'Both', N'A partner has told me about a customer they closed and delivered. Here is what they said: [paste what the partner told you]. Here is what our record shows: [paste the record position]. Draft a short internal note for the account executive and the commercial executive setting out what the partner reported, what our record independently shows, and where the two do not line up. Attribute the partner''s account clearly as theirs. Do not resolve any discrepancy or add conclusions I have not drawn.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check the partner''s account is presented as their report rather than as established fact.
3. Leave any discrepancy visible. The gap between what a partner says and what the record shows is the useful part.
4. Send it to the DAE and the CE, and tell the partner you have passed it on.', N'What the partner told you, and what our record shows for the same customer.', N'A short internal note separating the partner''s report from our record, with discrepancies left visible and attribution clear.', N'The PSS decides what is safe to represent as fact when it came from a single partner conversation. A partner''s read is genuine information and is also their interpretation, and a note that promotes it into a finding will be acted on by people who never spoke to them.', N'Closing the loop', N'What you learn from a partner is worthless if it stays with you. It is also dangerous if it travels as established fact, and the difference is entirely in how the note is written.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-POL-01', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 1, N'List the questions this structure will have to answer', N'Surface the policy, licensing and eligibility questions a deal will meet, before the structure is fixed.', N'Featured', N'Both', N'For [account name], show what is recorded that bears on commercial eligibility: the agreement type and its dates, the products and quantities involved, whether a partner is associated and any co-sell or referral record, and any amendment or exception already on the account. Also show whether the account transacts direct or through a partner where the record says so. Report what is recorded and do not interpret eligibility, licensing entitlement or policy.', N'1. Open Sales Agent and paste the prompt with your account.
2. Read the agreement type and the transaction route first - both change which rules apply.
3. Write down each question the structure raises. That list is yours to produce, not the agent''s.
4. Route every one to the authoritative owner rather than answering from a previous deal.', N'One live deal where the commercial structure is not yet fixed.', N'The recorded facts that bear on eligibility, with your own list of the questions the structure raises.', N'The CE decides which questions genuinely need an authoritative answer and routes them rather than answering from precedent. A structure that worked for a similar customer shows only that it was permitted once, on facts you have probably not seen, and reusing it quietly converts someone else''s exception into your own assumption.', N'Policy questions', N'Policy questions are cheapest at the point the structure is still a question. Asked at approval they cost weeks, and by then the customer may already have been told something that no longer holds.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-POL-02', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 2, N'Route the question so it comes back usable', N'Frame a policy question so the authoritative owner can answer it once, rather than starting a conversation.', N'Featured', N'Both', N'I need to ask an authoritative owner a policy question about [account name]. Here is the question and the context: [paste your question and the deal facts that bear on it]. Restructure this as a single question that can be answered without a follow-up: what is being asked, the specific facts that determine the answer, what I have already checked, and what decision the answer will drive. Do not answer the question or suggest what the answer might be.', N'1. Write the question yourself first, including the deal facts that determine the answer.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Check the restructured version still asks YOUR question rather than a cleaner adjacent one.
4. Send it, and record the answer against the account so the next person does not ask again.', N'Your policy question and the deal facts that bear on it. The authoritative owner for that question.', N'A single self-contained question that can be answered without a follow-up, with the answer recorded against the account.', N'The CE owns the question and confirms the rewrite did not change what is being asked. A model asked to make a question clearer will often make it more general, and a general answer to a specific eligibility question is worse than no answer because it feels like one.', N'Routing', N'Most policy delay is not the owner being slow, it is the question arriving without the facts needed to answer it. One well-formed question beats three exchanges.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-POL-03', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 3, N'Say out loud what you are relying on', N'Make an inherited policy position explicit enough that its owner can confirm or correct it.', N'Extended', N'Both', N'For [account name], show every amendment, exception or non-standard term recorded against this account: what each one is, the date it was recorded, and which agreement it sits against. Report only what is recorded on this account. Do not compare it to other accounts, and do not judge whether any of it still applies.', N'1. Write down the position you are about to rely on, in one sentence, before you look at anything. If you cannot state it, you do not yet know what you are assuming.
2. Open Sales Agent, paste the prompt, and replace [account name] with your deal.
3. Check whether the record actually says what you remember it saying. Often it says something narrower.
4. Send your one sentence and the relevant record to the authoritative owner and ask whether it still stands.', N'One live deal and the policy position you intend to rely on.', N'The position you are relying on stated in one sentence, with its recorded basis, sent to the authoritative owner for confirmation.', N'The CE states precisely what position they are relying on and has the owner confirm it before building on it. Reuse is invisible - a previous answer gets carried forward as an assumption rather than re-examined as a decision - and only the person relying on it can notice they are doing it. Whether it still stands is the owner''s call, not a matter of how recent it looks.', N'Precedent check', N'The most expensive policy error is not a wrong answer, it is a right answer that has expired. Nothing in the record marks a position as superseded, so the only reliable move is to name what you are assuming and have it confirmed.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-NEG-01', N'WF-X-DEAL-01', N'SMEC-CE-NEG', N'PH-SMEC-CE-NEG-EXPL', 1, N'Establish what can be conceded without asking', N'Fix the concession boundary from approved guidance before any pressure is applied to it.', N'Featured', N'Both', N'For [account name], show any discount, concession or non-standard term already in force on this account: what each one is, which agreement it sits on, and whether a partner transacts it. Report what is recorded. Do not advise what concession would be appropriate and do not propose a boundary.', N'1. Set your concession boundary from current approved guidance before you look at anything. That anchor does not come from the record.
2. Open Sales Agent, paste the prompt, and replace [account name] with your deal.
3. Treat what is already in force as a constraint on the boundary, not as evidence for it. It may itself have been an exception.
4. Write the boundary down, with the existing concessions noted against it, before anyone asks you to move.', N'One live deal heading toward a negotiation. Current approved commercial guidance for concession authority.', N'A concession boundary set from approved guidance, with the concessions already in force on the account recorded as constraints on it.', N'The CE sets the boundary from current approved guidance rather than from what comparable deals happen to carry. What was granted elsewhere may have been an exception, may have been wrong, or may have been approved under guidance that has since changed, and inheriting it silently converts one exception into a standard.', N'Concession authority', N'A boundary set before the pressure arrives is a decision. The same boundary set during the negotiation is a reaction, and it will be argued with.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-NEG-02', N'WF-X-DEAL-01', N'SMEC-CE-NEG', N'PH-SMEC-CE-NEG-EXPL', 2, N'Test whether your briefing gives away the floor', N'Check what a partner could infer from the boundary you are about to hand them.', N'Featured', N'Both', N'A partner will negotiate [describe the deal] with the customer. Here is the briefing I have written for them, covering what is fixed, what is theirs to use without asking, and what has to come back to me: [paste your briefing]. Read it as the partner would. Tell me what could be inferred from it about how much room exists beyond what I have stated, what is vague enough to be read as permission I did not intend, and anything in it resembling internal cost, margin, approval thresholds, seat counts, spend figures or personal data. Do not rewrite the briefing and do not tell me where the boundary should sit.', N'1. Write the briefing yourself, in three parts: what is fixed, what is theirs to use without asking, and what must come back to you. All three are your decisions and none of them are delegated.
2. Open Cowork, paste the prompt, and replace both bracketed sections.
3. Close anything that could be read as permission you did not intend to give. Vagueness reads as room.
4. Check it against the CELA rules yourself as well. The agent is a second reader, not the control.
5. Send it through your normal partner channel before the negotiation, not during it.', N'The partner briefing you have written, setting out what is fixed, what is theirs to use, and what must return to you for approval. The CELA rules on partner data exchange.', N'A partner briefing whose stated limits cannot be read as more room than you intended, with everything inferable closed before it is sent.', N'The CE decides how much of the boundary the partner needs to see. Too little and they concede something they should have escalated; too much and your floor becomes their opening position with the customer. That judgment depends on the specific partner, and only the person in the relationship can make it.', N'Partner briefing', N'A boundary is only as good as what the other side can infer around it. Partners are commercially sophisticated and will read the shape of what you did not say.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-NEG-03', N'WF-X-DEAL-01', N'SMEC-CE-NEG', N'PH-SMEC-CE-NEG-EXPL', 3, N'Decide now what would make you escalate', N'Name the specific condition that would take a concession decision above you, before it arrives.', N'Extended', N'Both', N'For the deal at [account name], my concession boundary is [paste your boundary]. Help me think through what circumstances would put a decision beyond that boundary: what the customer might reasonably ask for, what a partner might commit to on their own, and what timing pressure might create. For each, frame it as a condition to watch for rather than a prediction. Do not recommend whether to escalate or what the answer should be.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Pick the one or two conditions most likely to actually occur.
3. Write the trigger as something observable - a specific ask, a specific number - not as a feeling.
4. Tell your approver now that it may be coming, so the escalation is expected rather than a surprise.', N'Your concession boundary and the deal it applies to. Your approval route.', N'One or two observable escalation triggers named in advance, with the approver forewarned.', N'The CE decides what genuinely warrants escalation. Escalating everything trains your approver to stop reading, and escalating nothing means the boundary was never real, and only you can judge where this deal sits between those.', N'Escalation trigger', N'An escalation raised before the pressure is a decision with time attached. The same escalation raised during a negotiation is an emergency, and gets a worse answer.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'SMEC-CE-ORCH-01', N'WF-X-ORCH-01', N'SMEC-CE-ORCH', N'PH-SMEC-CE-ORCH-EXPL', 1, N'Find every approval this structure triggers', N'Assemble the full set of approvals a commercial structure will need, rather than meeting them one at a time.', N'Featured', N'Both', N'For [account name] I am taking this commercial structure to approval: [paste the structure]. Show what is already recorded that an approver would need to see: any exception or non-standard term already approved on this account and when it was recorded, the current deal stage and value, and whether a partner is associated with the account. Report what is recorded. Do not determine which approvals are required or who approves them.', N'1. Open Sales Agent and paste the prompt with your deal.
2. Work out the required approvals yourself from current approved guidance - that mapping is yours and it changes.
3. For each, decide whether it is one you obtain, one you request, or one the partner obtains from their own organization.
4. Confirm current lead times rather than assuming last quarter''s.', N'One deal with an agreed commercial structure needing approval. Current approved guidance on approval requirements.', N'The full approval set for this structure, each classified by whether you obtain it, request it, or the partner obtains it.', N'The CE determines which approvals are required, because that mapping changes with guidance and the record cannot know it. The classification matters more than the list: an approval you can obtain and one the partner must obtain from their own organization look identical on a plan and behave completely differently.', N'Approval mapping', N'Approvals met one at a time cost a week each. Mapping them together can show which ones run in parallel, and the sequence that looked fixed may be habit.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-ORCH-02', N'WF-X-ORCH-01', N'SMEC-CE-ORCH', N'PH-SMEC-CE-ORCH-EXPL', 2, N'Replace every implied owner with a named one', N'Turn an approval path expressed in roles into one expressed in people who know it is coming.', N'Featured', N'Both', N'Here is the approval path I have mapped for [account name]. For each step I have listed the owning role and the evidence that approval requires: [paste your approval list]. Draft the short note I would send to secure each one: what is being asked, the evidence I have listed against it, the date it is needed by, and what happens if it slips. Keep each to a few lines. Do not add evidence I have not listed, do not invent approver names, and do not state who the owner is.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Put a real name against every role before you send anything. A role is not an owner.
3. For partner-side steps, send the note to your partner contact rather than assuming they will discover it.
4. Send them all now rather than in sequence. Most of these are not actually dependent on each other.', N'Your mapped approval path, with the owning role for each step and the evidence that step requires taken from current approved guidance. The people who currently hold those roles.', N'A named owner and a sent request for every approval step, with the partner-side steps raised with the partner.', N'The CE confirms who currently holds each approval and that the evidence listed against it is what that approver actually asks for. Both change without announcement - a role moves, or a threshold is revised - and a note sent to last quarter''s owner citing last quarter''s evidence is a week lost before anyone notices it went to the wrong place.', N'Named owners', N'The approval path can be entirely correct and still unowned. Naming people converts a diagram into something that moves.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-ORCH-03', N'WF-X-ORCH-01', N'SMEC-CE-ORCH', N'PH-SMEC-CE-ORCH-EXPL', 3, N'Find the approval that never landed', N'Check the approvals you have already requested against what the record now shows, before a customer date makes it urgent.', N'Extended', N'Both', N'Here are the approvals I have outstanding and the date I requested each one: [paste your list with dates]. For each, show what is currently recorded on that opportunity: the current stage, the recorded next step and who owns it, and the close date. Report what is recorded and do not infer why anything is waiting.', N'1. List your outstanding approvals and the date you asked for each. If you cannot produce that list, that is itself the finding.
2. Open Sales Agent, paste the prompt, and replace the bracketed section.
3. Compare the recorded next step against what you actually asked for. Where they do not match, the request never landed.
4. Chase the ones you own with the named person rather than the queue. For partner-side approvals, ask your partner contact - our record will not show their progress at all.', N'The approvals you have already requested, and the date you requested each one.', N'Outstanding approvals separated into those that landed, those that never registered, and those sitting with a partner organization.', N'The CE decides which approvals have genuinely stalled and which are simply waiting their turn. An approval nobody ever submitted and one sitting correctly in a queue look identical from inside our systems, and a partner-side approval leaves no trace here at all - chasing that one through our own record costs the week you were trying to save.', N'Stalled approvals', N'Approvals fail quietly. The request that was never registered looks exactly like the one being worked, and the difference only becomes visible when the close date arrives.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'SMEC-CE-DEAL2-01', N'WF-X-DEAL-01', N'SMEC-CE-DEAL2', N'PH-SMEC-CE-DEAL2-EXPL', 1, N'State the decision you are asking someone to make', N'Turn a commercial structure into an explicit decision, so the approver is not left to work out what is being asked.', N'Featured', N'Both', N'I am taking a commercial structure to approval. Here is the structure and what I am asking for: [paste the structure and the ask]. Restate this as a decision: what specifically is being approved, what the alternatives were and why they were set aside, what happens if it is declined, and what the approver is accepting responsibility for. Use only what I have given you. Do not add commercial detail, do not recommend a decision, and do not soften the ask.', N'1. Write the structure and the ask down yourself first. If you cannot state the ask in one sentence, it is not ready to send.
2. Open Cowork, paste the prompt, and replace the bracketed section.
3. Check the alternatives are the ones you genuinely considered, not ones that make the recommendation look inevitable.
4. Confirm the responsibility line is accurate. That sentence is the one the approver will remember.', N'One commercial structure you have agreed and intend to take to approval. The approval you are seeking.', N'The structure restated as an explicit decision, with the alternatives, the consequence of declining, and what the approver is accepting.', N'The CE decides what the approver is actually being asked to accept. An approval request that understates what the approver is taking on gets granted quickly and withdrawn later, and the second conversation is far more expensive than the first.', N'Structure outcome', N'Approvers are sent structures and left to infer the decision. The ones that stall are the ones where the ask was never stated plainly, and nobody wants to admit they could not find it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-DEAL2-02', N'WF-X-DEAL-01', N'SMEC-CE-DEAL2', N'PH-SMEC-CE-DEAL2-EXPL', 2, N'Make the numbers checkable by someone else', N'Lay out the economics so an approver can verify them rather than take them on trust.', N'Featured', N'Both', N'Here are the economics of the commercial structure I am proposing: [paste your figures and where each came from]. Lay them out so someone else can check them: what is committed, over what period, what the customer pays and when, and what varies from standard and by how much. Show each figure alongside the source I have given for it. Do not calculate anything I have not supplied, do not estimate missing values, and flag any figure I have given without a source.', N'1. Assemble your figures first, and write the source next to each one as you go.
2. Open Cowork, paste the prompt, and replace the bracketed section.
3. Look at what it flags as unsourced. Those are the ones you will be asked about.
4. Replace any figure you cannot source with the range you can defend, and say it is a range.', N'The economics of your proposed structure, with the source of each figure.', N'The economics laid out with a source against every figure, and unsourced figures either sourced or stated as ranges.', N'The CE owns every number in the narrative and confirms each against where it came from. A figure that appears in an approval document becomes the figure everyone quotes afterwards, and the person who typed it is the only one who knows whether it was measured or estimated.', N'Pattern', N'A commercial narrative can fail review on one unsourced number rather than on the strength of the case. The figure nobody can trace is the one that stops the meeting.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-DEAL2-03', N'WF-X-DEAL-01', N'SMEC-CE-DEAL2', N'PH-SMEC-CE-DEAL2-EXPL', 3, N'Find what you have asserted without showing', N'Read your own narrative as someone who was not in any of the conversations behind it.', N'Extended', N'Both', N'Here is the commercial decision narrative I have written: [paste the narrative]. Read it as someone who was not part of any conversation behind it. List every claim asserted without evidence attached, every figure whose source is not stated, and every place where a judgment is presented as though it were a fact. Do not rewrite it, do not supply the missing evidence, and do not tell me whether the case is a good one.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Read the list before defending anything. The first reaction to most of these is that the context is obvious.
3. Close the gaps on the central commercial claim. Leave the peripheral ones open if closing them would bury the argument.
4. Where a judgment is being presented as a fact, say whose judgment it is.', N'Your drafted commercial decision narrative.', N'The narrative''s unevidenced claims identified, with the central ones closed and the remaining judgments attributed.', N'The CE decides which gaps must be closed before this goes and which can stand. A narrative that evidences every claim is unreadable and a narrative that leaves the central commercial claim unevidenced is returned, and telling those apart is the whole skill.', N'Feeding it back', N'You cannot see the assumptions you carried into your own document. Everything in it was obvious to you at the time, which is exactly why it reads as unsupported to the person approving it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-ARCH-01', N'WF-X-ARCH-01', N'DCSA-ARCH', N'PH-DCSA-ARCH-EXPL', 1, N'Compare the options on what happens when nobody tunes them', N'Research architecture options for a customer with no platform team, judging them on how they behave unattended.', N'Featured', N'Both', N'I am designing [describe the workload] for a customer with [describe their technical capacity and who will operate it]. Using approved Microsoft and authoritative public sources, compare the architecture options on operational burden: what each requires someone to monitor, tune or intervene on; what each does when left alone; what skills each assumes the operator already has; and what the documented failure modes are. Cite each claim and name where guidance conflicts or is missing. Do not recommend an option.', N'1. Write down who will operate this before you look at any options. That constraint decides the answer.
2. Open Researcher, paste the prompt, and replace both bracketed sections.
3. Check the citations. Guidance written for a customer with a platform team will not say so, and you have to notice.
4. Discard any option whose operational assumptions this customer cannot meet, however good it looks.', N'The workload and the customer''s technical constraints. What you know about who will operate it.', N'Architecture options compared on unattended behavior and operator skill assumed, with sources cited and gaps named.', N'The DCSA decides what this customer can realistically operate. Published guidance assumes a competent platform team because it is written for the general case, and a design chosen on capability alone will be technically correct and quietly abandoned within two quarters.', N'Compare the options on what happens when nobody tunes them', N'For a portfolio of non-unified customers there is no support relationship to absorb an operationally demanding design. The question is not which architecture is best but which one survives contact with the people who will actually run it.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DCSA-ARCH-02', N'WF-X-ARCH-01', N'DCSA-ARCH', N'PH-DCSA-ARCH-EXPL', 2, N'Write the design for the person who will build it', N'Turn a chosen architecture into something a partner or customer team can implement without you present.', N'Featured', N'Both', N'Here is the architecture I have chosen and what I know about who will implement it: [paste the design, the constraints, and what the implementer has built before]. Turn this into an implementation-ready description covering the sequence and the dependencies, marking which dependencies are outside the implementer''s control. Separately, list every configuration decision the implementer will have to make that my design does not already settle, and for each state what the design implies but does not say. Do not choose any of those configurations for me and do not add architectural decisions I have not made.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Read the unsettled configuration list. Those are the decisions the implementer will otherwise make for you, at the point you are least available.
3. Write your recommended choice against each one yourself. That is a design decision and it does not get delegated.
4. Send it to the implementer and ask which step they would want to talk through.', N'Your chosen architecture and its constraints. Who will implement it and what they have built before.', N'An implementation-ready design with the sequence and dependencies, plus the configuration decisions your design leaves open, each answered by you.', N'The DCSA answers every configuration decision the design leaves open. The implementer will resolve anything left silent using their own defaults, which are reasonable for their usual customer and may be wrong for this one - and the divergence only becomes visible when something behaves unexpectedly months later.', N'Write the design for the person who will build it', N'The design is not the artefact. What the implementer does with it is the artefact, and everything you left implicit becomes their judgment call.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-ARCH-03', N'WF-X-ARCH-01', N'DCSA-ARCH', N'PH-DCSA-ARCH-EXPL', 3, N'Find what your design assumes the customer has', N'Read your own design for the support, skills and tooling it quietly takes for granted.', N'Extended', N'Both', N'Here is a design I am about to hand over: [paste the design]. Here is what I actually know about the customer''s operating capability: [describe their team, skills, tooling and support arrangements]. Identify every point where the design assumes capability, tooling, support or availability I have not confirmed they have. For each, state what the design expects and what happens if it is absent. Do not redesign anything and do not tell me whether the design is good.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Read the list before defending it. Most of these assumptions felt obvious when you made them.
3. Confirm or close the ones that would cause a silent failure. An assumption that fails loudly is survivable.
4. Where you cannot close one, say so in the handover rather than leaving it to be discovered.', N'Your implementation-ready design. What you actually know about the customer''s operating capability and support arrangements.', N'The design''s unconfirmed assumptions listed with the consequence of each, and the silent-failure ones closed or disclosed.', N'The DCSA decides which unconfirmed assumptions are acceptable to hand over. Every design assumes something, and closing all of it is not possible in this segment - the judgment is which assumption fails quietly, because that is the one that turns into a consumption problem nobody traces back to the design.', N'Find what your design assumes the customer has', N'You cannot see what you assumed. Everything in the design was reasonable when you wrote it, which is exactly why the gaps are invisible to you and obvious to the customer six months later.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-HEALTH-01', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 1, N'Find the accounts where something technical has changed', N'Scan the portfolio for the recorded signals that precede a consumption problem.', N'Featured', N'Both', N'Across the accounts in my portfolio, identify those where consumption or usage has moved against plan, and separately those with a support or service record raised in the period I specify but no recorded technical activity from us. For the accounts that match, show the recorded movement, the support activity and the date of our last recorded technical engagement. Use this period: [state the period]. Do not return the accounts that do not match and do not diagnose a cause.', N'1. Open Sales Agent and paste the prompt.
2. Treat the two groups differently: movement against plan is a question, support activity with no engagement from us is a gap.
3. For each candidate, form your own technical hypothesis before opening the account. The record will not give you one.
4. Rank by how expensive the problem becomes if it is still there next quarter, not by size.', N'Your portfolio of accounts. Whatever consumption, usage and support views you can reach. The period you want assessed.', N'The portfolio split into accounts moving against plan and accounts with unattended support activity, ranked by cost of delay.', N'The DCSA decides which movement is technically significant. Consumption drops for reasons that have nothing to do with the technology - a project ending, a budget cycle, a seasonal workload - and spending your limited portfolio time on those is how the real problem stays undiscovered.', N'Find the accounts where something technical has changed', N'At this portfolio size you cannot inspect accounts individually, so the scan is the only way in. It will not tell you what is wrong; it tells you where to spend the attention you have.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-HEALTH-02', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 2, N'Raise a problem the customer has not noticed yet', N'Prepare the conversation where you tell a customer about a technical risk they did not ask you to look for.', N'Featured', N'Both', N'I need to raise a technical risk with a customer who has not asked about it. Here is the risk and my evidence: [describe the risk and what supports it]. Here is who I would raise it with and our history: [describe the contact and the relationship]. Help me rehearse this conversation: how to open it without implying they have been negligent, what they are likely to push back on, how to respond if they say it is not a priority, and how to close with a specific next step. Do not tell me whether to raise it.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the pushback you find hardest rather than the opening you find easiest.
3. Decide in advance what you will do if they decline to act. That answer is yours, not the agent''s.
4. Have the conversation, and record what they said so the next person does not raise it cold again.', N'The technical risk you have identified and the evidence for it. Who at the customer you would raise it with.', N'A rehearsed conversation with the likely objections worked through and a specific next step prepared.', N'The DCSA decides whether the evidence is strong enough to raise unasked. A technical risk surfaced on partial evidence and then disproved by the customer''s own team costs the standing you would need to raise the next one, and the record may not contain enough to settle it either way before the conversation.', N'Raise a problem the customer has not noticed yet', N'Finding the risk is the easy part. The conversation is where it either becomes an intervention or becomes a note nobody acted on, and in this segment you may get one attempt.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DCSA-HEALTH-03', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 3, N'Set a standing check so the next one finds you', N'Put a recurring watch on the portfolio so technical movement reaches you when it happens rather than at the next review.', N'Featured', N'Both', N'Set up a recurring weekly check across the accounts in my portfolio. Each week, tell me where consumption or usage has moved against plan, where a new support or service record has appeared on an account with no recent technical engagement from us, and where something I flagged previously has not changed. For each one, state what the data shows, what it does not tell us, and the single technical question I should ask next. Remember what you reported before, so you can tell me what is genuinely new and what is unchanged.', N'1. Open Scout and set the check running against your portfolio.
2. Give it the period and the movement threshold you actually care about, so it does not report everything.
3. Read the first run against what you already believed about these accounts.
4. Keep only the accounts where the movement is technically explainable and worth a conversation.
5. Prune it after two weeks. A check that reports everything gets ignored exactly like a dashboard nobody opens.', N'Your portfolio of accounts. The consumption, usage and support sources you can reach. The risks already on your list.', N'A weekly check running across the portfolio, separating new movement from unchanged risk, with a next technical question for each.', N'The DCSA confirms the technical reading of each signal and decides what is worth acting on. A standing check makes the finding cheaper, not the judgment - and the failure mode of automation here is a weekly report that everyone stops reading by week three.', N'Set a standing check so the next one finds you', N'Manual portfolio scans do not survive a busy quarter, which is exactly the quarter you need them. The value is that it keeps running when you have forgotten about it.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'DCSA-EXPAND-01', N'WF-X-RENEW-01', N'DCSA-EXPAND', N'PH-DCSA-EXPAND-EXPL', 1, N'Find the workload that is genuinely working', N'Identify where a customer is succeeding with something, as the only reliable starting point for expansion.', N'Featured', N'Both', N'For the accounts in my portfolio, show for each the workloads deployed, what usage is recorded against each, when each was deployed, and any support or service record raised against them. Identify the accounts where recorded usage has been stable or growing over the period I specify: [state the period you want assessed]. Report what is recorded and do not infer readiness or recommend anything.', N'1. Open Sales Agent and paste the prompt.
2. Look for stable and growing, not just large. A big workload that has flattened is not a readiness signal.
3. Decide for yourself how long usage has to hold before it evidences adoption rather than a pilot. That depends on the workload and the customer.
4. Pick the one account where the succeeding workload is closest to something the customer has said they care about.', N'Your portfolio of accounts and whatever deployment and usage evidence you can reach.', N'Accounts where a workload has demonstrably held or grown over two quarters, with the strongest candidate chosen.', N'The DCSA decides what counts as genuinely succeeding. Recorded usage can reflect one team, one automated process, or a workload nobody has switched off, and expanding from a false positive costs the credibility you would need for the real conversation.', N'Find the workload that is genuinely working', N'Expansion built on a workload that is merely deployed fails in a predictable way. Expansion built on one the customer is visibly getting value from is a conversation they will start themselves.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-EXPAND-02', N'WF-X-RENEW-01', N'DCSA-EXPAND', N'PH-DCSA-EXPAND-EXPL', 2, N'Test what usually comes next after this', N'Check an expansion hypothesis against documented adoption patterns rather than against what we would like to sell.', N'Featured', N'Both', N'A customer is running [describe the workload] successfully and I am considering whether [describe the expansion you have in mind] is the next logical step. Using approved Microsoft and authoritative public sources, show what the documented technical prerequisites are for that expansion, what the common adoption sequence is from the first workload, and what the documented reasons are for that sequence failing. Cite each claim. Do not tell me whether this customer is ready.', N'1. Open Researcher, paste the prompt, and replace both bracketed sections.
2. Read the failure reasons before the prerequisites. They are more useful and less often looked at.
3. Check the prerequisites against what you actually know this customer has, not what a customer of this size usually has.
4. If the documented sequence puts something else before your expansion, take that seriously rather than skipping it.', N'The workload the customer is succeeding with, and the expansion you are considering.', N'The expansion''s documented prerequisites and common failure reasons, checked against what this customer actually has.', N'The DCSA decides whether the documented sequence applies to this customer. Adoption patterns describe the average case and this segment is full of customers who are not average - the judgment is which prerequisite genuinely blocks and which is an assumption from a larger deployment.', N'Test what usually comes next after this', N'The expansion that follows a documented sequence is the one the customer can absorb. Skipping a step is how a technically valid expansion turns into a stalled deployment that damages the workload it grew from.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DCSA-EXPAND-03', N'WF-X-RENEW-01', N'DCSA-EXPAND', N'PH-DCSA-EXPAND-EXPL', 3, N'Hand it over in a form somebody can sell', N'Turn technical readiness evidence into something the person who owns the commercial conversation can actually use.', N'Extended', N'Both', N'I have technical evidence that a customer is ready for [describe the expansion]. Here is the evidence: [paste what you found - the succeeding workload, the usage pattern, the prerequisites met and any not yet met]. Draft a short handover for the person who owns the commercial conversation: what the customer is already succeeding with, what that makes possible, what is technically confirmed and what is not, and what would need to be true before it could start. Keep it factual. Do not write a pitch and do not include commercial or pricing framing.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check that what is unconfirmed is as prominent as what is confirmed. A handover that reads as certainty will be sold as certainty.
3. Send it to whoever owns the commercial conversation and say explicitly that the technical readiness is your view and the timing is theirs.
4. Record it against the account so the next person does not rediscover it.', N'Your evidenced expansion hypothesis. Who owns the commercial conversation on this account.', N'A factual technical handover separating confirmed readiness from open questions, with the commercial owner named.', N'The DCSA states what is technically evidenced and stops there. Technical readiness and commercial timing are different judgments owned by different people, and a handover that strays into whether the customer will buy undermines the person who has to have that conversation.', N'Hand it over in a form somebody can sell', N'Uncovering the next workload is the DCSA''s accountability; selling it is not. The handover is where that boundary is either respected or quietly crossed.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-ASSET-01', N'WF-X-ASSET-01', N'DSE-ASSET', N'PH-DSE-ASSET-EXPL', 1, N'Package it with what it assumes', N'Turn something you built into a reusable asset, with the constraints that decide whether it fits.', N'Featured', N'Both', N'Here is something I built and want to make reusable: [paste or describe the artefact - a script, design, demo, response or checklist]. It was built for this situation: [describe the customer context, constraints and what it assumed]. Produce a reusable package covering what it does, what it requires before use, the steps to use it, what someone would need to change for their own situation, how to check it worked, where it does not apply, and who owns it. Flag anything customer-identifying that should be removed. Do not add capability it does not have.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check the removal flags yourself. The agent will catch names and identifiers; it will not catch a configuration that only one customer would ever run.
3. Write the "where it does not apply" section properly. It is the part that stops the asset being misused and the part everyone skips.
4. Check the community hubs before publishing. If something close already exists, improve that instead of adding a second.', N'The artefact you want to make reusable. The customer situation it was built for. Your team''s rules on what may be shared internally.', N'A reusable package with prerequisites, adaptation points, validation steps and stated limits, sanitized for internal sharing.', N'The DSE decides what is safe to hand to someone who will not know what it assumed. Automated flagging may surface names and identifiers but cannot be relied on to catch a configuration that only made sense for one customer, so the review is the seller''s and it is not delegable.', N'Package it with what it assumes', N'An artefact without its constraints is not reusable, it is just findable. The next engineer either rebuilds it or applies it somewhere it was never validated.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-ASSET-02', N'WF-X-ASSET-01', N'DSE-ASSET', N'PH-DSE-ASSET-EXPL', 2, N'Write the note that makes it findable', N'Produce the description another engineer would search for and could judge fit from without opening it.', N'Featured', N'Both', N'Here is a reusable asset I am publishing: [paste the package]. Write the entry another engineer would find when searching: a one-line description of what it does, the problem it solves stated in the words somebody would actually search for, the prerequisites, one example of when to use it and one of when not to, and the owner. Keep it short enough to read in fifteen seconds. Do not restate the asset itself.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check the search words are the ones a colleague would type, not the ones you used when you built it.
3. Make sure the "when not to use it" example is specific. A vague limitation gets ignored.
4. Publish it where the team already looks, and tell one person who has the problem it solves.', N'Your sanitized asset package. Where it will be stored and who maintains it.', N'A short findable entry with the problem stated in searchable terms, a fit example, a non-fit example and a named owner.', N'The DSE decides whether the description matches how colleagues actually search. The test is not whether it reads well but whether it uses the words someone would type while looking for something they cannot name precisely, and only somebody who has failed to find things in this repository knows what those are.', N'Write the note that makes it findable', N'An asset nobody can find fails for a reason that has nothing to do with its quality. Something described in the language of the person who built it is invisible to the person who needs it.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-ASSET-03', N'WF-X-ASSET-01', N'DSE-ASSET', N'PH-DSE-ASSET-EXPL', 3, N'Catch the question that has started arriving', N'Set a standing check that surfaces technical questions which have begun recurring since you last looked, rather than re-listing what you already know.', N'Featured', N'Both', N'Check my messages and meetings from the last [state a period] for technical questions I have answered more than once. Group them by the underlying technical problem rather than by wording, and show how many different people or customers each came from. On each later run, report only groups that are new since your previous report, or where the number of distinct askers has grown. Do not draft answers and do not repeat groups you have already reported unless they have grown.', N'1. Open Scout, run the prompt, and set your own lookback period for the first run.
2. Treat the first run as a backlog. Everything it finds is historical and most of it you already half-knew.
3. From the second run onward, the value is only in what is new or growing. That is a signal that something has changed in the product, the market or your patch.
4. Pick candidates by breadth of asker rather than by count, and judge for yourself what breadth means for your patch.
5. When you publish an asset, check the next report to see whether the question stopped arriving.', N'Your mail, chats and meetings. The assets your team has already published.', N'Technical question groups that are new or growing since the previous run, with the breadth of askers for each.', N'The DSE decides whether a newly recurring question reflects a genuine change or a coincidence of timing. A question that starts appearing may mean a product update, a competitor claim or a shift in what customers are attempting - and only someone who knows what changed recently can tell which, or whether it is simply two customers who happened to ask in the same two weeks.', N'Notice what you are answering repeatedly', N'A one-off scan finds the backlog once. What is worth knowing afterwards is which questions have STARTED arriving, because that is a change in the field you would otherwise notice months later.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'DSE-PARTNER-01', N'WF-X-ORCH-01', N'DSE-PARTNER', N'PH-DSE-PARTNER-EXPL', 1, N'Find where the same partner keeps needing you', N'Look across partner-led opportunities for the technical dependency that keeps coming back to you.', N'Featured', N'Both', N'For the opportunities in my area where a partner is associated and that have been open during [state the period], group them by partner and return only the partners with more than one. For those partners only, show for each opportunity the current stage, how long it has been at that stage, the recorded next step and its owner, and any recorded technical activity from me. Report what is recorded and do not infer why anything has stalled.', N'1. Open Sales Agent and paste the prompt.
2. Look at the grouping by partner before the individual deals. One deal needing you is normal; one partner repeatedly needing you is the finding.
3. For each recurring partner, work out what specific technical step they hand back. The record will not say - you know it from the asks.
4. Separate what they cannot do from what they simply prefer you to do. Those need different responses.', N'The partner-led opportunities you support, which partner is associated with each, and the period you want to look at.', N'Partner-led opportunities grouped by partner, with the recurring technical dependency identified for each.', N'The DSE decides whether a partner is genuinely lacking capability or has learned that asking is faster than doing. Both look identical in the record and in the request, and enablement fixes only the first - offering it for the second is politely ignored.', N'Find where the same partner keeps needing you', N'One deal at a time, absorbing the technical step looks like helpfulness. Across a partner''s portfolio it is the reason their capability never grows and your time never comes back.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-PARTNER-02', N'WF-X-ORCH-01', N'DSE-PARTNER', N'PH-DSE-PARTNER-EXPL', 2, N'Have the capability conversation without causing offence', N'Prepare the conversation that names a partner''s technical gap and offers to close it rather than cover it.', N'Featured', N'Both', N'I need to raise a technical capability gap with a partner. Here is the gap and what makes me think it exists: [describe the gap and the evidence]. Here is my relationship with them and who I would speak to: [describe the contact and the history]. Help me rehearse this: how to open it as an offer rather than a criticism, what they may say to deflect it, how to respond if they say they have it covered when the evidence says otherwise, and how to close with a specific action they own. Do not tell me whether the gap is real.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the deflection you expect, not the version where they agree with you.
3. Decide beforehand what you will do if they decline. Continuing to absorb the work is a decision too, and it should be a deliberate one.
4. Close with an action the partner owns and a date. Enablement you own is not enablement.', N'The capability gap you have identified and the evidence for it. Your relationship with the partner and who you would raise it with.', N'A rehearsed capability conversation opened as an offer, with the likely deflections worked through and a partner-owned action prepared.', N'The DSE decides what evidence is sufficient to call something a capability gap rather than a preference. Repeated requests can mean the partner cannot do the work, or that they have learned we will, and naming the wrong one produces enablement that is politely attended and never applied.', N'Have the capability conversation without causing offence', N'This conversation is the whole workflow. Everything before it is preparation, and the alternative to having it is doing the partner''s technical work indefinitely.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DSE-PARTNER-03', N'WF-X-ORCH-01', N'DSE-PARTNER', N'PH-DSE-PARTNER-EXPL', 3, N'Leave them something that works when you are not there', N'Turn a resolved technical gap into material the partner can use themselves next time.', N'Extended', N'Both', N'A partner had this technical gap and here is how it was resolved this time: [describe the gap and what was done]. Here is what the partner''s team already knows and works with: [describe their technical background and tooling]. Draft something they could use to do this themselves next time: the steps, the decisions they will face and what to consider for each, how to check it worked, and when to come to us anyway. Write it for their engineers, not for ours. Do not include internal-only detail, customer-identifying information, or anything that reads as an export from our systems.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Check it against your data-sharing rules before it leaves Microsoft. This is going to another company.
3. Be specific about when they should still come to us. Material that implies they never need us again is inaccurate and will be trusted anyway.
4. Send it to the person who owns the action, not to the account contact, and ask them to try it on the next one.', N'The capability gap and how it was resolved. What the partner already knows and what they use.', N'Partner-usable technical material with the decision points explained and the escalation boundary stated, checked before it leaves Microsoft.', N'The DSE decides what is genuinely safe to hand to another company and where the boundary of self-service sits. Material that is too complete invites a partner to attempt something they should escalate, and the failure lands on a customer who never knew the difference.', N'Leave them something that works when you are not there', N'A gap closed in one conversation reopens on the next deal. Something the partner keeps is the only version of this that reduces your load permanently.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSS-COMP-01', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 1, N'Find out what the competitor actually does well', N'Build an evidenced view of a competitor''s real strengths in your solution area, from sources rather than from internal belief.', N'Featured', N'Both', N'A customer is comparing our [describe the solution area] against [name the competitor]. Using authoritative public sources and approved Microsoft material, set out what that competitor''s offering does well in this area, what its documented limitations are, and where independent sources disagree with either vendor''s marketing. Cite each claim and state where evidence is thin. Do not tell me how to position against them and do not characterize the competitor as weak.', N'1. Open Researcher, paste the prompt, and replace both bracketed sections.
2. Read the competitor strengths first. That is the part internal material will not give you honestly.
3. Check the citations. A claim about a competitor that turns out to be out of date loses a technical audience.
4. Mark anything you would be uncomfortable saying if the competitor were in the room. That is the material to drop.', N'The competitor and the solution area. The customer''s stated decision criteria if you have them.', N'An evidenced view of the competitor''s genuine strengths and documented limitations, with sources cited and thin areas flagged.', N'The DSS decides what is safe to assert. A competitive claim that a customer can disprove in one search costs the whole position, not just that point, and internal competitive material is written to persuade rather than to survive being checked.', N'Find out what the competitor actually does well', N'You will be positioned against a competitor the customer has already researched. Arriving with a view that is less accurate than theirs ends the technical credibility you need for everything else.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DSS-COMP-02', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 2, N'Check what this competitor has actually cost you', N'Look across your solution area for what happened in past opportunities where this competitor was involved.', N'Featured', N'Both', N'Across the opportunities in my solution area, show any where [name the competitor] is recorded as involved: the account, the stage reached, whether it closed and how, and any recorded objection, blocker or competitor note. Group them by outcome. Report what is recorded and do not infer why any of them went the way they did.', N'1. Open Sales Home and paste the prompt with your competitor.
2. Look at the losses before the wins. The recorded objection on a loss is the most useful sentence in the system.
3. Where the record says nothing, treat that as unknown rather than as no objection.
4. Pick the objection that appears most often across different accounts. That is the one worth preparing properly.', N'The competitor. Your solution-area opportunities.', N'Past opportunities involving this competitor grouped by outcome, with the recurring objection identified.', N'The DSS decides which recorded objection reflects a real competitive pattern. Notes are written by whoever was losing at the time and often record the last thing said rather than the actual reason, so the same words can mean several different problems.', N'Check what this competitor has actually cost you', N'The objection you will meet has almost certainly been met before somewhere in your solution area. It is written down badly, but it is written down.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-COMP-03', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 3, N'Write the position against their criteria, not ours', N'Turn competitive evidence into a position expressed in the customer''s decision criteria.', N'Extended', N'Both', N'Here is what I know about how we compare to a competitor in my solution area: [paste your evidence and the recurring objection]. Here are the customer''s decision criteria as they have expressed them: [paste or describe the criteria]. Map each criterion to what we can evidence, what the competitor can evidence, and where neither of us has evidence. Identify the criteria where the comparison genuinely favors us and those where it does not. Do not write positioning language and do not resolve the criteria where we are behind.', N'1. Open Cowork, paste the prompt, and replace both bracketed sections.
2. Look at the criteria where we are behind. Deciding what to do about those is the actual work.
3. Concede the ones you cannot win rather than arguing them. A concession buys credibility for the criteria that matter.
4. Build the conversation around the two or three criteria where the advantage is both real and valued.', N'Your competitive evidence and the recurring objection. The customer''s decision criteria in their own words.', N'Decision criteria mapped to what each side can evidence, with the winnable criteria separated from the ones to concede.', N'The DSS decides which criteria to concede. Contesting everything reads as a vendor who has not listened, and choosing what to give up is a judgment about this customer''s priorities that no comparison table contains.', N'Write the position against their criteria, not ours', N'Customers decide on their criteria, not on ours. A position organized around our strengths answers a question they were not asking.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSS-ORCH-01', N'WF-X-ORCH-01', N'DSS-ORCH', N'PH-DSS-ORCH-EXPL', 1, N'Work out what the opportunity is actually missing', N'Establish what support an opportunity needs by looking at what is recorded rather than at what feels stuck.', N'Featured', N'Both', N'For [opportunity name or ID] in my solution area, show what is recorded: the current stage and when it last changed, the recorded next step and its owner, any recorded blocker or objection, whether a partner is associated, and what technical or specialist activity is recorded against it. Report what is recorded and do not infer what support is needed.', N'1. Open Sales Agent and paste the prompt with your opportunity.
2. Compare the recorded next step against what you believe the next step is. Where they differ, someone else is working from the record.
3. Decide what is genuinely missing: a person, a decision, or evidence. They are asked for in different ways.
4. Write the need down as a task somebody could do, not as a description of the situation.', N'One opportunity in your solution area that is not moving as it should.', N'The opportunity''s recorded position with the missing support identified as a person, a decision or a piece of evidence.', N'The DSS decides what would actually unblock this rather than what would be useful to have. In a segment with no assigned v-team every ask spends credit with someone who has their own targets, and asking for the wrong thing costs the same as asking for the right one.', N'Work out what the opportunity is actually missing', N'Most support asks describe a situation and hope the reader works out the task. Naming the missing thing precisely is what separates an ask that gets actioned from one that gets acknowledged.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-ORCH-02', N'WF-X-ORCH-01', N'DSS-ORCH', N'PH-DSS-ORCH-EXPL', 2, N'Write the ask so it can be said yes to', N'Turn a support need into a request with a task, a date and a consequence.', N'Featured', N'Both', N'I need support on an opportunity and here is what is missing: [describe what you need and the opportunity context]. I am asking [describe who you are asking and what they are accountable for]. I need it by [state your date] because [state what happens to the opportunity if it does not arrive]. Draft the request using those: what specifically I am asking them to do, by my stated date, what I have already done so they are not repeating it, and my stated consequence. Keep it to a few lines. Do not set a date I have not given you, do not invent a consequence, and do not pad it with background.', N'1. Decide your date and your consequence first. Both are yours and neither can be worked out from the opportunity record.
2. Open Cowork, paste the prompt, and replace all four bracketed sections.
3. Check that the task is something a person could start without asking you a question first.
4. Send it to a named person. A request to a team is a request to nobody.', N'The support you need and the opportunity it is for. Who you are asking and what they are accountable for. The date you need it by, and what happens to the opportunity if it does not arrive by then.', N'A short request with a specific task, a date, what has already been done, and the consequence of it not arriving.', N'The DSS decides how much of the consequence to state. Overstating it is noticed and quietly discounted from then on; omitting it leaves the reader to guess the priority, and they will guess low because everything else they have been sent also looked urgent.', N'Write the ask so it can be said yes to', N'The people you need are not assigned to you and are choosing between several asks. Yours is competing on how easy it is to act on.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSS-ORCH-03', N'WF-X-ORCH-01', N'DSS-ORCH', N'PH-DSS-ORCH-EXPL', 3, N'Notice when an ask has gone quiet', N'Set a standing check that tells you which of your requests never got answered.', N'Featured', N'Both', N'Set up a recurring weekly check across my sent messages for requests I have made that have not received a reply. For each, show who it went to, when it was sent, what was being asked, and whether any date I set has now passed. Group them by how overdue they are. Remember what you reported before so you can tell me which are newly overdue and which I have already been told about. Do not draft follow-ups.', N'1. Open Scout and run the prompt.
2. Read the newly-overdue group first. The long-overdue ones need a different approach rather than another chase.
3. For anything twice reported and still unanswered, go to the person a different way rather than resending.
4. Prune what you are tracking every few weeks. A list that includes everything you ever sent stops being useful immediately.', N'The support asks you have outstanding and who each went to.', N'Outstanding requests grouped by how overdue they are, separating newly overdue from previously reported.', N'The DSS decides which silence needs chasing and which means the answer is no. Some unanswered asks are a queue and some are a declined request nobody wanted to say out loud, and chasing the second repeatedly costs the relationship you will need for the next one.', N'Notice when an ask has gone quiet', N'Support asks fail silently. Nobody tells you they are not doing it, and by the time you notice, the opportunity has moved past the point where it would have helped.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'PSS-CAP-01', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 1, N'Look at what the partner has actually delivered', N'Establish a partner''s delivery record from what is recorded, before deciding what to route to them.', N'Featured', N'Both', N'For [partner name], show what is recorded: the opportunities where they are associated and the stage each reached, any co-sell or referral record and its status, what closed and over what period, and the workloads or solution areas involved. Group by outcome and by solution area. Report what is recorded and do not assess their capability.', N'1. Open Sales Agent and paste the prompt with your partner.
2. Look at what they have delivered in the specific solution area you are considering, not their overall record.
3. Note where the record thins out. A partner with three closed deals and nothing recorded since is a different proposition from one with steady flow.
4. Treat this as the capability half only. Nothing here tells you whether they have anyone available.', N'The partner you are assessing. The work you are considering routing to them.', N'The partner''s recorded delivery grouped by outcome and solution area, with the gaps in the record noted.', N'The PSS decides what the delivery record actually evidences. A partner who closed several deals two years ago with a team that has since left looks identical in the record to one delivering now, and the record has no way of showing you the difference.', N'Look at what the partner has actually delivered', N'Capability is the half of partner readiness we have evidence for. Getting it from the record rather than from the relationship is what makes the routing decision defensible when it is questioned.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-CAP-02', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 2, N'Ask about capacity without implying doubt', N'Prepare the conversation that establishes whether a partner actually has people available, which no system will tell you.', N'Featured', N'Both', N'I need to find out whether a partner genuinely has capacity to take on [describe the work], and our systems cannot tell me. Here is what I know about their delivery record: [paste your findings]. Help me prepare that conversation: how to ask about available people without implying I doubt them, what answers would tell me they are overcommitted, how to respond if they say yes when the evidence suggests otherwise, and how to leave the door open if the answer is no. Do not tell me whether to route the work.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the case where they say yes and you do not believe them. That is the hard one and it is common.
3. Ask about named people and current commitments rather than about capacity in general. General questions get general reassurance.
4. Decide in advance what you will do with a no. A partner who can say no safely will tell you the truth next time.', N'The partner and what you are considering routing to them. Your delivery-record findings.', N'A prepared capacity conversation with the tell-tale answers identified and a safe route to no.', N'The PSS decides whether a named-people answer is specific enough to route work on. A partner naming individuals and dates has given you something checkable; a partner describing capability in general has not, and accepting the second because the first felt intrusive is how work gets routed to a firm rather than to a team.', N'Ask about capacity without implying doubt', N'Nothing in our systems shows partner capacity. It only comes from a conversation, and how you ask determines whether the answer is real.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'PSS-CAP-03', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 3, N'Watch for the partner who has stopped moving', N'Set a standing check across your partners for the delivery signals that appear before a partner-led engagement stalls.', N'Featured', N'Both', N'Set up a recurring check across the partners I work with. Each time, show me for each partner-associated opportunity and referral: its current status, the date that status was last recorded, and how long it has held. Show the same for any partner with no recorded activity in the period. Report the elapsed times and do not classify anything as stalled, at risk or normal. Remember what you reported before so you can tell me which elapsed times have grown since last time.', N'1. Open Scout and confirm which partner and opportunity sources it can reach.
2. Choose your own cadence. Partner rhythms differ and a frequency that suits one portfolio buries another.
3. Decide for yourself what counts as too long for each partner. A quiet period that is routine for one partner is a warning for another.
4. Remember our record shows nothing about partner-side activity. Silence here is a prompt to ask, not a finding.
5. Prune what you track once you can see which categories actually move.', N'The partners you carry. The opportunities and referrals associated with each.', N'Elapsed time against each partner-associated record, with the times that have grown since the previous run identified.', N'The PSS decides what a gap in partner activity means. There is no general answer - partners work to their own cadence, and two weeks of quiet that is routine for one is a warning for another - so the elapsed time is a prompt to ask rather than a conclusion to act on.', N'Watch for the partner who has stopped moving', N'Elapsed time is a fact the record can supply. Whether a given elapsed time matters is a judgment about a specific partner relationship, and conflating the two produces either constant false alarms or a report nobody reads.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'PSS-CONV-01', N'WF-X-CONV-01', N'PSS-CONV', N'PH-PSS-CONV-EXPL', 1, N'Assemble what the partner already knows about themselves', N'Build the performance picture the partner will recognize, before you ask them for anything.', N'Featured', N'Both', N'[Partner name]', N'1. Open Know Your Partner and type the partner name or their PartnerOne ID.
2. Read the performance and program sections first. This is the version of the relationship they can also see.
3. Check the web-sourced context - recent news, acquisitions, expansion. That often explains a change in behavior better than any metric.
4. Note where it shows a placeholder rather than a figure. Missing data is not zero, and treating it as zero in front of a partner is expensive.
5. If you do not have access, assemble the same picture from partner performance reporting and continue with the rest of the workflow.', N'The partner and the conversation you have coming up.', N'A partner performance and context picture covering program participation, delivery and recent business developments.', N'The PSS decides which of this the partner would recognize as their own view. Our reporting measures what matters to Microsoft, and opening a conversation with figures the partner does not use is how a business discussion turns into a data argument.', N'Assemble what the partner already knows about themselves', N'Partners experience the relationship through their own numbers. Arriving with only our version guarantees the first ten minutes are spent reconciling rather than deciding.', N'https://aka.ms/KnowYourPartner', N'Open Know Your Partner'),
        (N'PSS-CONV-02', N'WF-X-CONV-01', N'PSS-CONV', N'PH-PSS-CONV-EXPL', 2, N'Reframe the ask in what their business gains', N'Turn a Microsoft priority into an ask expressed in the partner''s own economics.', N'Featured', N'Both', N'I want a partner to [describe the one thing you want them to do]. Here is what I know about their business and performance: [paste your partner picture]. Here is what I know about how they make money, and what I do not know: [describe their model and state the gaps]. Set out the questions I would have to answer before I could claim this is good for their business: what it would cost them, what they would gain, and over what period. For each question, say whether what I have given you answers it. Do not estimate any figure I have not supplied, do not construct a return calculation, and do not use Microsoft targets or incentive language.', N'1. Open Cowork, paste the prompt, and replace all three bracketed sections, including what you do NOT know.
2. Look at which questions your material cannot answer. Those are what you ask the partner, not what you assert to them.
3. Do not fill a gap with an estimate. A partner will recognize a number you invented about their own business immediately.
4. Reduce it to one ask, framed by the questions you can actually answer.', N'Your partner picture. The one thing you want the partner to do. Whatever you actually know about how they make money, including what you do not know.', N'The economic questions the ask depends on, marked by whether your material answers them, with the unanswerable ones turned into questions for the partner.', N'The PSS decides which economic claims can be made and which must be asked. A partner''s cost base is not visible to us, and a return figure constructed from our side is both wrong and recognisably wrong to the person who runs the business - which costs the credibility the ask depends on.', N'Reframe the ask in what their business gains', N'Partners commit to things that improve their business. Claiming to know their economics when you do not is how you get treated as a vendor rather than a partner.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'PSS-CONV-03', N'WF-X-CONV-01', N'PSS-CONV', N'PH-PSS-CONV-EXPL', 3, N'Rehearse the part where they push back', N'Prepare for the objection this partner will actually raise, rather than the conversation where they agree.', N'Extended', N'Both', N'I am asking a partner to [describe your reframed ask]. Here is our history: [describe what this partner has committed to before and what actually happened]. Help me rehearse the difficult part: what they are most likely to push back with, how to respond if they raise a past commitment we did not meet, what to do if they agree in the room but the history suggests they will not act, and how to close with something specific enough to follow up on. Do not tell me whether the ask is reasonable.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse the response to a past Microsoft failure honestly. Deflecting it is remembered longer than the original failure.
3. Prepare for agreement-without-action specifically - it is the most common outcome and the hardest to name politely.
4. Close on something checkable with a date, and put it in writing the same day.', N'Your reframed ask and the partner picture. The history of what this partner has and has not done before.', N'A rehearsed conversation covering the likely pushback, the history, and a close specific enough to follow up.', N'The PSS decides which previous commitment is solid enough evidence to raise. A commitment that was implied, or made by someone who has since left, will be disputed and turns the conversation into a disagreement about history - so the judgment is whether this specific instance is documented well enough to survive being questioned.', N'Rehearse the part where they push back', N'The partner conversation that changes anything is the one where the difficult part was prepared. The rest is a status meeting with a friendlier name.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DAE-HEALTH-05', N'WF-X-HEALTH-01', N'DAE-HEALTH', N'PH-DAE-HEALTH-EXPL', 5, N'Let the territory tell you when it moves', N'Set a standing check across the territory so a change reaches you when it happens rather than at the next review.', N'Featured', N'Both', N'Set up a recurring weekly check across the accounts in my territory. Each week, show me where an opportunity has changed stage or close date, where a new signal or plan priority has arrived and how long it has before it expires, where a renewal date has moved inside twelve months, and where a partner referral has changed status. For each, state what changed and what the record does not tell us. Remember what you reported before so you can separate what is new from what I have already seen.', N'1. Open Scout and confirm which signal, opportunity and referral sources it can reach for your territory.
2. Run the prompt and set the cadence to land before your own pipeline review.
3. The first run reports everything. Read it once, then tune it to movement rather than inventory.
4. Act on expiring signals first - they are the only items on the list with a deadline you cannot negotiate.', N'Your territory of accounts. The signal, opportunity and renewal sources you can reach.', N'A weekly view of territory movement separating new changes from previously reported ones, with expiring items surfaced.', N'The DAE decides which movement needs action this week. A territory of this size generates change constantly and most of it is noise, so the judgment is which change alters what you were going to do anyway.', N'Let the territory tell you when it moves', N'At this territory size nothing surfaces on its own. The choice is between a standing check and finding out at the review, and the review is always too late for the signals that expire.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SMEC-CE-HEALTH-05', N'WF-X-HEALTH-01', N'SMEC-CE-HEALTH', N'PH-SMEC-CE-HEALTH-EXPL', 5, N'Keep watching the book between reviews', N'Set a standing check across the agreement book so commercial exposure surfaces before it becomes a renewal problem.', N'Featured', N'Both', N'Set up a recurring check across the agreements in my book that runs every two weeks. Each time, show me where an agreement end date has moved, where a new exception or amendment has been recorded, and where a renewal date has come inside the window I specify. Report only what has changed since the previous run. Do not assess commercial risk and do not recommend action.', N'1. Open Scout and set the check running against your book of agreements.
2. Run the prompt and set it to repeat every two weeks. Commercial exposure moves more slowly than pipeline and a weekly check would mostly report nothing.
3. Read the first run in full, then read only the changes after that.
4. Decide which movements need a conversation and which are administrative.', N'Your book of agreements. The consumption, amendment and renewal data you can reach.', N'A change-only view, refreshed every two weeks, of agreement dates moving, new exceptions recorded, and renewals entering the window.', N'The CE decides which movement is commercially material. An exception recorded on one account is administration; the same exception appearing repeatedly is a policy signal, and only someone reading across the book over time can tell which one they are watching.', N'Keep watching the book between reviews', N'Commercial exposure in this segment accumulates quietly across many small agreements. Nobody discovers it in a single review, because no single account looks like a problem.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SMEC-CE-POL-04', N'WF-X-POLICY-01', N'SMEC-CE-POLICY', N'PH-SMEC-CE-POLICY-EXPL', 4, N'Read what the guidance actually says', N'Establish what published commercial and licensing guidance states on a question, before asking anyone to interpret it.', N'Extended', N'Both', N'I need to understand what published guidance says about [describe the policy, licensing or eligibility question]. Using approved Microsoft sources and authoritative public documentation, set out what the published position is, what conditions or exceptions the documentation names, what it explicitly does not cover, and where different sources say different things. Cite each source and give its date. Do not tell me whether it applies to my deal and do not resolve any conflict you find.', N'1. Open Researcher, paste the prompt, and replace the bracketed section.
2. Check the dates before the content. Commercial guidance gets revised without being re-read.
3. Where sources conflict, that is your question for the authoritative owner - not something to resolve yourself.
4. Take the citations with you when you ask. A question that shows what you have already read gets a faster and better answer.', N'The policy or licensing question your deal raises.', N'The published position with its conditions, its explicit gaps, and any conflicts between sources, each cited and dated.', N'The CE decides which fact about this deal takes it outside the published general case. Guidance is written for the standard shape and commercial eligibility turns on the specifics that differ, so the judgment is which of your deal''s particulars actually changes the answer - that is what determines whether you need a ruling or already have one.', N'Read what the guidance actually says', N'Arriving at the policy owner having read nothing wastes their time and yours. Arriving having read it and knowing exactly where it stops being clear is the difference between one exchange and four.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DSS-INV-01', N'WF-INVEST-01', N'DSS-INVEST', N'PH-DSS-INVEST-EXPL', 1, N'Establish what the deal actually looks like', N'Assemble the recorded facts that determine which investment routes are even open to this opportunity.', N'Featured', N'Both', N'For [opportunity name or ID] in my solution area, show what is recorded: the account, the products and workloads involved, the deal value and stage, any existing agreement and its type, whether a partner is associated and any co-sell or referral record, and any consumption or usage recorded on the account. Report what is recorded. Do not determine eligibility for any investment program and do not recommend a route.', N'1. Open Sales Agent and paste the prompt with your opportunity.
2. Note the partner association first. It changes which routes are even in scope.
3. Write down the barrier the investment would remove, in one sentence. If you cannot, investment is not the answer yet.
4. Take the facts and the barrier to the next step rather than deciding eligibility here.', N'One solution-area opportunity where customer investment might remove a barrier.', N'The recorded facts that bear on route selection, with the barrier the investment would remove stated in one sentence.', N'The DSS decides whether there is a real barrier that money removes. Investment attached to a deal that is simply slow does not speed it up, and a request built on a barrier nobody can name is declined late, after the effort has been spent.', N'Establish what the deal actually looks like', N'Route selection depends on facts about the deal that are already recorded. Starting from the program rather than the deal is how sellers end up building a case for a vehicle the opportunity never fitted.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-INV-02', N'WF-INVEST-01', N'DSS-INVEST', N'PH-DSS-INVEST-EXPL', 2, N'Find out what the routes actually require', N'Establish from published guidance what each candidate investment route requires, before choosing between them.', N'Featured', N'Both', N'I am considering customer investment for an opportunity with these characteristics: [paste the deal facts and the barrier]. Using approved Microsoft sources and authoritative internal documentation, set out what the published requirements are for each investment route that could apply, what evidence each requires, what each explicitly excludes, and where the documentation is silent. Cite each source and give its date. Do not tell me which route to use and do not assess whether my opportunity qualifies.', N'1. Open Researcher, paste the prompt, and replace the bracketed section.
2. Read the exclusions before the requirements. That is where most requests fail and it is the part least often read.
3. Check the dates. Investment guidance changes between fiscal years and last year''s version is still findable.
4. Where the documentation is silent, that is a question for the authoritative owner, not a gap for you to fill.', N'Your deal facts and the barrier you named. The routes you are considering.', N'Each candidate route''s published requirements, evidence and exclusions, cited and dated, with the silent areas identified.', N'The DSS confirms every eligibility reading with the authoritative owner rather than acting on the documentation alone. Published requirements describe the general case and investment decisions turn on specifics the documentation cannot see, so this shortens that conversation instead of replacing it.', N'Find out what the routes actually require', N'Sellers learn one route and apply it everywhere - the one that worked first. Reading what the alternatives actually require is the only way that habit gets corrected.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'DSS-INV-03', N'WF-INVEST-01', N'DSS-INVEST', N'PH-DSS-INVEST-EXPL', 3, N'Write the case against the route you chose', N'Turn the barrier and the route requirements into a request that answers what that route actually asks.', N'Extended', N'Both', N'I am requesting customer investment through [name the route] for an opportunity. Here are the route''s published requirements: [paste them]. Here is the barrier and the deal context: [paste them]. Draft the request so that it answers each requirement in turn: what is being asked for, the barrier it removes, the evidence for that barrier, what changes if it is approved, and how that change would be observed. Mark any requirement I have not evidenced. Do not assert eligibility, do not estimate any figure I have not supplied, and do not claim approval is likely.', N'1. Open Cowork, paste the prompt, and replace all three bracketed sections.
2. Look at what it marks as unevidenced. Those are the questions a reviewer will ask first.
3. Make the observable change specific. "Accelerates adoption" is not something anyone can check afterwards.
4. Send it through the route''s own process rather than to whoever answered last time.', N'Your chosen route and its published requirements. The barrier and the deal facts.', N'A request answering each published requirement in turn, with unevidenced requirements marked and the observable change stated specifically.', N'The DSS states what will be observably different if the investment is approved. A request that promises acceleration without naming what would be measured is approved on trust and cannot be defended at review, which is what makes the next request from your team harder.', N'Write the case against the route you chose', N'Investment requests are compared against each other, not judged in isolation. The one that answers the stated requirements in order is easier to approve than a better opportunity described loosely.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'PSS-INV-01', N'WF-INVEST-01', N'PSS-INVEST', N'PH-PSS-INVEST-EXPL', 1, N'Check what this partner has already signed up to', N'Establish what program commitments a partner already carries before adding another one.', N'Featured', N'Both', N'For [partner name], show any co-sell or referral record currently open and the status and date of each, and any record showing a program or campaign this partner has been nominated into. For each, show whether it progressed after it was opened and the date of the last change. Report what is recorded. Do not assess their program eligibility and do not recommend an investment route.', N'1. Open Sales Agent and paste the prompt with your partner.
2. Look for records opened and never progressed. A partner carrying several of those has an acceptance habit rather than a delivery habit.
3. Check program participation in the partner reporting you have access to - our opportunity record shows nominations, not completions.
4. Decide whether this partner has room for another commitment before you offer one.', N'The partner and the opportunity you are considering investment for. Whatever partner program reporting you can reach.', N'The partner''s open commitments with the ones that never progressed identified, and a view on whether they have room for another.', N'The PSS decides whether this partner can absorb another commitment. Partners accept nominations readily and complete far fewer, so adding one to a partner already carrying unfinished commitments produces another unfinished commitment and makes the next conversation harder to have.', N'See what this partner has already been nominated for', N'A partner-led route only works if the partner does their part. What they have already agreed to and not delivered is the most direct evidence available, and it sits in a record nobody checks before nominating.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'PSS-INV-02', N'WF-INVEST-01', N'PSS-INVEST', N'PH-PSS-INVEST-EXPL', 2, N'Find out what the route asks of the partner', N'Establish from published guidance what a partner-led route requires the partner to do, not just what it offers.', N'Featured', N'Both', N'I am considering [name the partner-led investment route] for a partner opportunity. Using approved Microsoft sources and authoritative internal documentation, set out what the route requires from the PARTNER specifically: what they must nominate, what activity they must complete, what evidence they must produce, over what period, and what they receive in return. Also show what it requires from Microsoft. Cite each source and give its date. Do not assess whether this partner qualifies.', N'1. Open Researcher, paste the prompt, and replace the bracketed section.
2. Separate what the partner must do from what we must do, and list each partner obligation on its own line.
3. Note the period. A program requiring activity over two quarters is a different ask from one requiring a single nomination.
4. Take the partner-side obligations into the conversation with them rather than nominating first and explaining later.', N'The route you are considering and the partner it would run through.', N'The route''s partner-side obligations, Microsoft-side obligations, timeframe and partner return, cited and dated.', N'The PSS confirms the partner-side obligations with the authoritative owner before committing a partner to them. Program terms change between fiscal years and a partner told the wrong requirements will discover the real ones at the point they are being assessed, which costs the relationship rather than the program.', N'Find out what the route asks of the partner', N'Partner-led investment fails when the partner did not know what they had agreed to. The obligations are published, and nothing in the nomination flow requires anyone to read them.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'PSS-INV-03', N'WF-INVEST-01', N'PSS-INVEST', N'PH-PSS-INVEST-EXPL', 3, N'Get the partner to agree to their half', N'Prepare the conversation where the partner commits to what the route requires of them, rather than simply accepting a nomination.', N'Extended', N'Both', N'I want a partner to take part in an investment route that requires this of them: [paste the partner-side obligations]. Here is their record of completing what they have started before: [describe it]. Help me prepare the conversation: how to present the obligations without making it sound like paperwork, what they are likely to agree to in the room and not do, how to raise a previous unfinished commitment without it becoming an argument, and how to close on something specific enough to check. Do not tell me whether to nominate them.', N'1. Open Agent J.ai, paste the prompt, and replace both bracketed sections.
2. Rehearse raising the unfinished commitment. Avoiding it guarantees the same outcome.
3. Get agreement on a named person on their side, not on the firm. A firm cannot complete an activity.
4. Confirm in writing the same day, with what they agreed and by when.', N'The route''s partner-side obligations. The partner''s record of completing what they start.', N'A prepared conversation covering the partner''s obligations, the previous record, and a close naming a person and a date.', N'The PSS decides how directly to raise a partner''s record of not finishing. Naming it risks the relationship; not naming it means nominating into the same outcome again, and only the person in the relationship can judge which this partner will take better.', N'Get the partner to agree to their half', N'A nomination is not a commitment. The conversation where the partner agrees to their specific half is the whole difference between a program that runs and one that appears in a report as unstarted.', N'https://aka.ms/agentjcopilot', N'Open Agent J.ai'),
        (N'DAE-INV-01', N'WF-INVEST-01', N'DAE-INVEST', N'PH-DAE-INVEST-EXPL', 1, N'Tell a funding barrier from a decision barrier', N'Assemble the recorded facts your role needs before contributing to an investment decision.', N'Featured', N'Both', N'For [account name], show what is recorded that would bear on whether investment could help: the open opportunities and their stage, any recorded blocker or objection, the existing agreement and its type, what is deployed against it, whether a partner is associated, and any recorded activity in the last six months. Report what is recorded and do not assess whether investment is appropriate.', N'1. Open Sales Agent and paste the prompt with your account or opportunity.
2. Separate what the record shows from what you have been told. Where those two disagree is the barrier worth naming.
3. Form your own view before reading anyone else''s assessment.
4. Route what you find to whoever owns the request rather than acting on it yourself.', N'One account where something is blocked and money might move it.', N'The account''s recorded position with the barrier stated, and your own read on whether it is one funding removes.', N'The DAE decides whether the barrier is one money removes. A customer who has not decided is not blocked by cost, and investment offered into indecision reads as discounting and is remembered as a price signal on the next deal.', N'Tell a funding barrier from a decision barrier', N'Investment is a lever for a specific class of barrier. Offering it against the wrong one trains the customer to wait for it.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DAE-INV-02', N'WF-INVEST-01', N'DAE-INVEST', N'PH-DAE-INVEST-EXPL', 2, N'Route it to whoever owns the request', N'Hand a recognized investment opportunity to its owner with enough evidence to be acted on.', N'Extended', N'Both', N'I have found an account where customer investment might remove a barrier. Here is what I found and the evidence: [paste your findings]. Draft a short note for whoever owns the investment request: the account, the barrier and what evidences it, what I have already confirmed, what I have not, and why I think investment is the lever rather than something else. Keep it brief. Do not assess eligibility and do not recommend an amount.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check that what you could not determine is as visible as what you found. Silence on a gap reads as a clear result.
3. Say what your role would still have to do. Requests are approved without that and then stall on it.
4. Send it to the named owner, not to a distribution list.', N'Your assessment and the evidence behind it. Who owns the investment request.', N'A short handover naming the account, the barrier and its evidence, with what you confirmed separated from what you did not.', N'The DAE hands over the barrier evidence and does not propose a figure. An amount suggested by the person who found the opportunity anchors the request before anyone has assessed eligibility, and a number that turns out to be wrong is remembered as the account team over-promising.', N'Route it to whoever owns the request', N'You see these barriers across more accounts than anyone. The value is only realized if the person who owns the request can act without a second conversation.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DSE-INV-01', N'WF-INVEST-01', N'DSE-INVEST', N'PH-DSE-INVEST-EXPL', 1, N'Decide what would count as proof', N'Assemble the recorded facts your role needs before contributing to an investment decision.', N'Featured', N'Both', N'A customer investment would fund this technical work: [describe the work and what the customer doubts]. Define what it would need to demonstrate for the customer''s doubt to be resolved: the observable success criteria, what would constitute a clear negative result, the exit criteria that end the work either way, and the evidence a reviewer would need afterwards. Do not assume the investment is approved and do not estimate cost or duration.', N'1. Open Sales Agent and paste the prompt with your account or opportunity.
2. Separate the recorded technical position from what you were briefed. The gap is where the success criteria will have to do their work.
3. Form your own view before reading anyone else''s assessment.
4. Route what you find to whoever owns the request rather than acting on it yourself.', N'One proposed piece of technical work that customer investment might fund.', N'What the funded work would have to demonstrate, expressed as things somebody could observe happening.', N'The DSE decides how much the funded work must prove before the customer would act on the result. Proving too little leaves the doubt intact and the funding spent; proving too much turns a bounded piece of work into a project, and where that line sits depends on what this specific customer said they doubted.', N'Decide what would count as proof', N'Funded technical work is assessed at closure against whatever criteria existed at the start. If none did, the assessment becomes a matter of opinion and the next request is harder.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSE-INV-02', N'WF-INVEST-01', N'DSE-INVEST', N'PH-DSE-INVEST-EXPL', 2, N'Write the criteria down before the work is funded', N'Record the technical success and exit criteria in a form a reviewer can assess against afterwards.', N'Extended', N'Both', N'I have defined what an investment-funded piece of technical work must demonstrate. Here are my criteria: [paste them]. Write them up for the investment request: what will be demonstrated, how each will be observed, what would constitute a clear negative result, and the point at which the work stops either way. Mark anything I have written that could not actually be observed. Do not add criteria I have not stated and do not estimate effort or duration.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check that what you could not determine is as visible as what you found. Silence on a gap reads as a clear result.
3. Say what your role would still have to do. Requests are approved without that and then stall on it.
4. Send it to the named owner, not to a distribution list.', N'Your assessment and the evidence behind it. Who owns the investment request.', N'Success and exit criteria written for the request, with anything unobservable marked before it is submitted.', N'The DSE owns which criteria survive into the request. Criteria are negotiated down when the request is assembled, and the ones removed are the ones that would have shown a negative result - which is exactly what makes the remaining set unfalsifiable.', N'Write the criteria down before the work is funded', N'Criteria that live only in your head are renegotiated at closure by people who were not there. Written into the request, they set the terms of the assessment before anyone has a stake in the answer.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-INV-01', N'WF-INVEST-01', N'DCSA-INVEST', N'PH-DCSA-INVEST-EXPL', 1, N'Check the environment, not the opportunity', N'Assemble the recorded facts your role needs before contributing to an investment decision.', N'Featured', N'Both', N'An investment-funded engagement is proposed for [account name]: [describe the work]. Show me what is recorded about the account that bears on whether it could absorb this: the workloads deployed and what usage is recorded against them, any open or recently resolved support issues, whether a partner is associated, and the recorded technical activity in the last six months. Report what is recorded and do not assess readiness.', N'1. Open Sales Agent and paste the prompt with your account or opportunity.
2. Separate what the record shows from what you have been told. On a non-unified account the record is thinner, so the difference matters more.
3. Form your own view before reading anyone else''s assessment.
4. Route what you find to whoever owns the request rather than acting on it yourself.', N'One proposed investment-funded engagement and the account it would run on.', N'The account''s recorded technical position, with your read on whether this customer could absorb the funded work.', N'The DCSA decides which customer-side dependency would genuinely block delivery. Every engagement depends on something the customer must provide, and the judgment is which of those this particular customer will actually struggle with - the record shows what they have, not what they can take on.', N'Check the environment, not the opportunity', N'Investment converts into consumption only if the customer can absorb the work. In a portfolio of non-unified customers that is the assumption the request does not test.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DCSA-INV-02', N'WF-INVEST-01', N'DCSA-INVEST', N'PH-DCSA-INVEST-EXPL', 2, N'Name the dependency that would stop it', N'Set out the customer-side dependencies that would block funded delivery, and who would have to resolve each.', N'Extended', N'Both', N'I have assessed whether a customer could absorb investment-funded technical work. Here is what I found: [paste your findings]. Set out the customer-side dependencies that would have to be in place before the work could start or complete: what each is, who on the customer or partner side would have to provide it, and what happens to the engagement if it is not there. Separate the ones I have confirmed from the ones I am assuming. Do not assess whether the investment should proceed.', N'1. Open Cowork, paste the prompt, and replace the bracketed section.
2. Check that what you could not determine is as visible as what you found. Silence on a gap reads as a clear result.
3. Say what your role would still have to do. Requests are approved without that and then stall on it.
4. Send it to the named owner, not to a distribution list.', N'Your assessment and the evidence behind it. Who owns the investment request.', N'The customer-side dependencies that would block delivery, separated into those confirmed and those assumed.', N'The DCSA distinguishes a dependency the customer has been told about from one they have agreed to. Those look identical in any write-up and behave completely differently at delivery, and only the person who had the conversation knows which one it was.', N'Name the dependency that would stop it', N'Funded work can stall on a customer-side dependency that no technical review would surface, and the stall is recorded as a Microsoft delivery failure regardless of whose dependency it was. Testing for them is separate work from testing the technical plan.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'SMEC-CE-INV-01', N'WF-INVEST-01', N'SMEC-CE-INVEST', N'PH-SMEC-CE-INVEST-EXPL', 1, N'Test whether the structure survives without the investment', N'Check whether a commercial structure you are building depends on funding that has not been approved.', N'Featured', N'Both', N'For [account name], I am structuring a deal where customer investment is expected to form part of it. Show what is recorded: the existing agreement and its type, the products and quantities involved, any amendment or exception already recorded, the deal stage and value, and whether a partner is associated. Report what is recorded. Do not assess the investment, do not determine eligibility, and do not comment on approval.', N'1. Open Sales Agent and paste the prompt with your account.
2. Describe the structure twice: once assuming the investment arrives and once assuming it does not.
3. If the second version does not work, the structure depends on a decision you do not own. Say so now rather than at approval.
4. Route any eligibility or investment question to the role that owns it rather than answering it.', N'One deal you are structuring where customer investment is expected to be part of it.', N'The structure described with and without the investment, and any dependency on an unapproved decision made explicit.', N'The CE decides whether a structure that depends on unapproved investment should be presented at all. A structure contingent on someone else''s decision looks complete to a customer and to an approver, and the dependency only surfaces when the investment is declined and the commitment has already been made.', N'Test whether the structure survives without the investment', N'Investment decisions sit outside the CE''s authority in this segment, but the commercial consequence of one not arriving lands entirely on the structure. That exposure is worth seeing before the customer does.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'DSS-COMP-04', N'WF-X-DEAL-01', N'DSS-COMP', N'PH-DSS-COMP-EXPL', 4, N'Rehearse the objection you know you will get', N'Prepare to meet the recurring competitive objection in the room, rather than only knowing what it is.', N'Featured', N'Both', N'I am going into a technical conversation where a competitor is in play. Here is the objection that comes up repeatedly: [paste the recurring objection you identified]. Here is what we can evidence and what I have decided to concede: [paste the criteria mapping]. Help me rehearse meeting it: how to acknowledge the part that is true without conceding the decision, what they are likely to say next, and how to respond if they press on something I have already decided to concede. Do not write competitive claims for me and do not tell me the competitor is wrong.', N'1. Open Agent J.ai and paste the prompt with the objection and your criteria mapping.
2. Practice the acknowledgement first. Decide how much of the objection you are willing to grant out loud.
3. Work the follow-up, not the opening. The opening is the part you have already thought about.
4. Say out loud the thing you decided to concede. If it sounds like a loss rather than a choice, it is not ready.
5. Take one sentence into the meeting, not a script.', N'The recurring objection from your competitive review, and the criteria you decided to contest and concede.', N'A rehearsed response to the recurring objection, with the acknowledgement and the concession both prepared as deliberate choices.', N'The DSS decides whether the rehearsed response is accurate and which part of it to withhold. Rehearsal smooths an answer, and a smoothed answer can acquire confidence the underlying evidence does not support, so what gets said is a separate decision from what was practiced.', N'Prepare to meet the objection you already know is coming', N'Knowing the objection and being ready to meet it are different states. Rehearsal is where you find out which one you are in.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'PSS-CAP-04', N'WF-X-HEALTH-01', N'PSS-CAPACITY', N'PH-PSS-CAPACITY-EXPL', 4, N'Decide whether this partner is ready, and who closes the gap', N'Put capability and capacity together into a readiness decision with a named owner and a date.', N'Featured', N'Both', N'Here is what the record shows about a partner''s delivery capability: [paste your findings]. Here is what they told me about capacity: [paste what they said, including anything vague]. Bring these together into a readiness view for [describe the work]. Separate what they have demonstrated from what they have asserted. Set out the candidate gaps with the evidence for each, the possible impact of each on this work, and what is not known. Do not rank the gaps for me, do not decide whether to proceed, and do not assume any gap can be closed.', N'1. Open Cowork and paste both halves - what the record showed and what the partner said.
2. Look first at anything demonstrated on one side and only asserted on the other. Demonstrated and asserted are different kinds of evidence and the difference is the point of this step.
3. Name one gap, not several. A readiness view with four gaps is a list, and lists do not get owned.
4. Decide who closes it and by when. If the honest answer is that you would close it yourself, that is a finding about this partnership rather than a plan.
5. Write down what happens to the work if the gap is not closed. That is the part that makes the date real.', N'Your findings on the partner''s delivery record, and what they said about capacity.', N'A readiness view with demonstrated capability separated from asserted capacity, the candidate gaps evidenced, and the seller''s chosen gap with a closing action, an owner and a date.', N'The PSS chooses which gap matters and names who closes it by when. The evidence supports several readings and selecting among them is the decision; an unowned gap has no date, and a readiness view without a date has not decided anything.', N'Turn the two halves of partner readiness into one decision', N'Capability and capacity are each half an answer. The decision that routes work needs both, joined, with somebody''s name on what is missing.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DCSA-HEALTH-04', N'WF-X-HEALTH-01', N'DCSA-HEALTH', N'PH-DCSA-HEALTH-EXPL', 4, N'Check whether the technical explanation actually holds', N'Test the most likely technical cause against documented behavior before raising it with anyone.', N'Featured', N'Both', N'I have a hypothesis about why a customer''s workload is behaving the way it is. Here is what I observed and what I think is causing it: [describe the movement and your suspected technical cause]. Here is the configuration as far as I know it: [describe the workload and any relevant settings]. Using approved Microsoft and authoritative internal documentation, tell me whether this cause is consistent with documented behavior for this configuration. Give me at most three documented alternatives that would produce the same symptom on this configuration, and for each, what I would need to observe to tell them apart. Cite each claim. Where the documentation does not settle it, say so rather than choosing.', N'1. Open Researcher and paste the prompt with your observation and your suspected cause.
2. Read the alternative explanations before the confirming ones. You already believe your own.
3. Check the citations reach current documentation. A behavior that changed in a recent release is the case this step is for.
4. Note what you would need to observe to separate the explanations. That is your question for the customer''s team.
5. Decide whether your hypothesis survived. If it did not, say so now rather than carrying it into the conversation.', N'The account you ranked highest, what you observed, and your suspected technical cause.', N'The hypothesis either retained or rejected, with up to three documented alternatives and the observation that would separate them, each claim sourced.', N'The DCSA decides whether the hypothesis survives contact with the documentation, and which observation would settle it. Documentation describes the general case and this customer is a specific one, so consistency raises confidence without confirming, and carrying an unrejected hypothesis forward as a finding is how a technical conversation goes wrong before it starts.', N'Test the technical hypothesis before you take it to a customer', N'A ranked list tells you which account to look at, not what is wrong with it. Testing the explanation is what turns a suspicion into something worth a customer''s time.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'SMEC-CE-RENEW-05', N'WF-X-RENEW-01', N'SMEC-CE-RENEW', N'PH-SMEC-CE-RENEW-EXPL', 5, N'Check the renewals that arrived without you', N'Work through renewal opportunities created automatically and decide which of them describe a renewal you would stand behind.', N'Featured', N'Both', N'Show me the renewal opportunities in my book that were created automatically rather than by me, using their creation date between [start date] and [end date]. For each, show the account, the recorded value and currency, the close date, the enrollment or agreement record it was built from, the product or SKU lines attached, and the forecast category currently set. Report what is recorded. Do not assess whether any value, date or line is correct.', N'1. Open Sales Agent and paste the prompt with your start and end dates.
2. For each opportunity, validate four things yourself against the agreement and the customer: the account it landed on, the value and currency, the close date, and the product or SKU lines attached.
3. Correct what is wrong and add what is missing - contacts, and any required field - before the opportunity progresses to the next stage.
4. Where the renewal should not exist at all, say so and route it rather than editing it into something plausible.
5. Set the forecast category yourself. The record existing is not the same as you committing to it.
6. Pick the one where what arrived differs most from what you would have entered, and work out why. That gap is the thing worth discussing.', N'Your renewal book for the period, including opportunities you did not create. The underlying agreement or enrollment record for anything you intend to correct.', N'Auto-created renewals reviewed with account, value, close date and product lines each confirmed or corrected, forecast category set by the CE, anything that should not exist routed rather than edited, and one flagged difference between what arrived and what was expected.', N'For each auto-created renewal the CE decides one of three things: accept it as it stands, correct it against the agreement, or reject it as a renewal that should not be in the book. The CE also decides whether and when to set a forecast category, which is the point at which the record becomes a commitment rather than a suggestion.', N'Own the renewals that arrived in pipeline without you', N'A renewal that appears in pipeline without anyone deciding it belongs there is a forecast entry nobody has stood behind. The work is no longer creating the record, it is deciding whether to own it.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'ALL-CLOSEDWON-01', N'WF-X-PIPE-01', N'ALL-CLOSEDWON', N'PH-ALL-CLOSEDWON-EXPL', 1, N'Find the closes you cannot account for', N'List recent closed-won opportunities in your book and separate the ones you closed from the ones that closed some other way.', N'Featured', N'Both', N'Show me the opportunities in my book that were marked closed won with a close date in the last [state a short period, for example 30 days]. For each, show the account, the value, the close date, the products or SKU lines attached, and the recorded close reason or status if one is set. Report what is recorded. Do not assess whether any close was correct.', N'1. Open Sales Agent and paste the prompt with a short recent period. Keep it small enough to read in one sitting.
2. Go down the list and mark the ones you do not remember closing. You are working from your own memory of the deal here, not from a field.
3. For each one you marked, ask whether you can account for the value, the products and the date. Mark anything you cannot.
4. Take the marked ones forward. If there are none, say so - that is a result worth the room hearing.', N'Your own opportunities and the date range you want to review.', N'Recent closed-won opportunities with the ones the seller cannot account for identified, or an explicit statement that there were none.', N'The seller decides which closes they can account for. A closed record can be well-formed and still describe something that did not happen, and the check is whether the value, products and date match what was actually sold.', N'See which of your deals closed without you closing them', N'A closed record carries your number whether or not you set it. A wrong one raises no error and blocks nothing, so it survives until somebody has to explain it.', N'https://m365.cloud.microsoft/chat/?titleId=P_280ba0c3-7951-e7a8-68d3-8d65f9ca8149', N'Open Sales Agent'),
        (N'ALL-CLOSEDWON-02', N'WF-X-PIPE-01', N'ALL-CLOSEDWON', N'PH-ALL-CLOSEDWON-EXPL', 2, N'Work out what to do about the one you cannot explain', N'Take a closed record you cannot account for and decide whether to accept it, correct it, or raise it.', N'Featured', N'Both', N'Here is a closed-won opportunity I cannot fully account for: [paste the record - account, value, close date, close reason, products]. Here is what I know was actually happening on this account: [paste what you know - what was sold, what was signed, what was delivered, what was still open]. Lay out where the record and my account knowledge agree, where they disagree, and what would settle each disagreement. Do not tell me whether the close was correct.', N'1. Open Cowork and paste both the record and what you know about the account.
2. Work the disagreements, not the agreements. The agreements are why you did not notice sooner.
3. Decide which of four this is: the close is right and you had forgotten; it is wrong on detail you are able to correct yourself; it is wrong in a way that needs somebody else; or you cannot yet tell and need to check something first.
4. If it is yours to correct, correct it now while you still have the context.
5. If it needs somebody else or more evidence, write down what you checked and what you found, so the next person does not start from nothing.', N'One closed record you could not account for, and what you know was happening on that account.', N'One questionable close resolved into accepted, corrected by the seller, routed to whoever can act on it, or held pending a specific check.', N'The seller decides whether the record matches what was sold, and whether the correction is theirs to make or somebody else''s. Account knowledge is one input rather than the deciding one, and a correction made without the contract in front of you replaces one wrong record with another.', N'Decide what to do about a close you cannot account for', N'A wrong close is easy to leave alone because nothing breaks. It shows up later as revenue that cannot be explained or a customer conversation that starts from a false position.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'CSA-VSAT-01-P01', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 1, N'Watch the satisfaction signals across a live delivery', N'Gather the delivery signals that show how the customer is experiencing the work.', N'Featured', N'Prompt', N'For [Customer] and [delivery or engagement], set up a recurring check on the signals that show how the customer is experiencing this delivery: open issues and how long they have been open, escalations, missed or moved dates, response times, and questions left unanswered. Report what changed since the last check rather than restating everything. Separate what the record shows from what is inferred, and state what the record cannot see. My delivery context is [global delivery, field delivery or SME&C coverage]; reflect that in which signals you treat as material.', NULL, N'Delivery status, open issues, escalation history, milestone dates; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'A recurring satisfaction signal watch showing what changed since the last check, separating evidence from inference.', N'The CSA decides which signals reflect the customer''s experience rather than internal process noise. A record with no open issues can still describe a customer who has stopped telling us about them.', N'Monitoring and signal', N'The signals are usually already in the record. The work is looking before the survey does.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSA-VSAT-01-P02', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 2, N'Rank the satisfaction risks by what the customer would say', N'Turn the signals into a ranked view of what this customer would raise if asked today.', N'Featured', N'Prompt', N'Using the delivery signals for [Customer], rank what this customer would most likely raise if asked about their experience today. For each item give the specific moment behind it, who owns it, and whether it is still fixable within this delivery. Separate what is evidenced from what is inferred.', NULL, N'Satisfaction signal summary, delivery timeline, role ownership; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Ranked satisfaction risks with owner and a fixable or not-fixable call.', N'The CSA confirms each ranked item traces to a specific moment. A risk with no moment behind it is a feeling, and it will not survive the conversation with the account team.', N'Analysis and prioritization', N'Ranking by what the customer would say, rather than by what is easiest to fix, is what makes this worth doing.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-VSAT-01-P03', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 3, N'Build the satisfaction recovery action', N'Turn the top satisfaction risk into an action with an owner and a date.', N'Featured', N'Both', N'Take the top satisfaction risk for [Customer] and draft the recovery action: what will change, who owns it, what the customer will see and by when, and what we will say to them about it. Keep it to something deliverable inside this delivery.', N'1. Take the highest-ranked satisfaction risk.
2. State what the customer would see change, not what we would do internally.
3. Name the owner and the date.
4. Decide what is said to the customer and by whom.
5. Route anything that is not yours.', N'Ranked satisfaction risks, delivery timeline, account team roles; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'One satisfaction recovery action with owner, date and customer-visible change.', N'The CSA confirms the action is one the customer would notice. An internal process fix the customer never sees does not move satisfaction.', N'Synthesis and drafting', N'A satisfaction risk without a customer-visible action is a note. This is the step that changes the score.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'CSA-VSAT-01-P04', N'WF-X-VSAT-01', N'CSA-VSAT', N'PH-CSA-VSAT-EXPL', 4, N'Check the risk against what the record supports', N'Test the satisfaction read against the evidence before taking it to the account team.', N'Extended', N'Prompt', N'Review this satisfaction read for [Customer]. For each claim, state whether the delivery record supports it, partly supports it, or does not support it. Identify anything asserted without evidence and anything the record cannot show either way.', NULL, N'Satisfaction read, delivery record, escalation history; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Evidence check with unsupported claims identified.', N'The CSA decides what to take forward. Raising an unsupported satisfaction claim with the account team costs credibility on the ones that were real.', N'Validation and evidence', N'Satisfaction claims get challenged. Checking them first is what lets you hold the position.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'CSA-TECHLEAD-01-P01', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 1, N'Map what the customer''s direction will demand of you', N'Work out which technical topics this customer''s roadmap will require you to be credible on.', N'Featured', N'Prompt', N'For [Customer], based on their stated technical direction, current estate and announced priorities, identify the technical topics they will need advice on over the next two to four quarters. Rank by how soon they will need it and how central it is to their direction. State what is known versus assumed.', NULL, N'Customer technical direction, current estate, announced priorities; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Ranked list of technical topics the customer will need advice on.', N'The CSA confirms this reflects the customer''s direction rather than Microsoft''s product roadmap. The two are not the same, and only one of them determines what the customer asks you.', N'Research and synthesis', N'The list of things worth knowing is set by the customer. Starting anywhere else is how good effort gets spent on the wrong topic.', N'https://m365.cloud.microsoft/chat/?titleId=P_552e6eda-fc18-7fb9-0ef6-1bf2de3393e4', N'Open Researcher'),
        (N'CSA-TECHLEAD-01-P02', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 2, N'Compare that against what you can defend today', N'Set the customer''s coming demands against what you could hold a conversation on now.', N'Featured', N'Prompt', N'Take this ranked list of technical topics for [Customer]. For each, help me separate what I could hold an advisory conversation on today, what I could speak to but not defend under challenge, and what I would have to route to a specialist. Ask me what I need to answer honestly rather than assuming.', NULL, N'Ranked technical topics, your own recent customer conversations; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Honest gap map across can defend, can discuss, and must route.', N'The CSA answers this honestly rather than aspirationally. A gap map that flatters you produces a plan that closes nothing.', N'Assumption testing', N'Most credibility gaps are known and unstated. Writing them down is most of the work.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-TECHLEAD-01-P03', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 3, N'Find where you were the bottleneck', N'Look back at where a question had to go to someone else, and what that cost.', N'Extended', N'Prompt', N'Looking across my recent customer engagements, identify where a technical question had to be routed to someone else, where a decision waited on an answer I could not give, and where I deferred a topic more than once. Group them by topic and show which ones recur.', NULL, N'Recent engagement history, meeting and escalation records; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'Recurring topics where you were the routing point rather than the answer.', N'The CSA decides which routing was appropriate and which was a gap. Bringing in a specialist is often the right call, and treating every handoff as a personal shortfall points the plan at the wrong thing.', N'Analysis and assessment', N'The gaps that cost the most are the ones that recur. They are visible in your own history if you look.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-TECHLEAD-01-P04', N'WF-X-TECHLEAD-01', N'CSA-TECHLEAD', N'PH-CSA-TECHLEAD-EXPL', 4, N'Build the credibility plan for one gap', N'Turn the highest-value gap into a specific plan with a first step this week.', N'Featured', N'Both', N'Take the highest-value technical gap and build a plan to close it: what being credible on this looks like in a customer conversation, the smallest first step, what I will use to get there, how I will test whether it worked, and the date I will have it by. Keep it to one gap.', N'1. Pick the gap the customer will hit soonest.
2. State what credible looks like in their words, not ours.
3. Name the smallest first step.
4. Decide how you will test it, ideally on a real conversation.
5. Put a date on it.', N'Gap map, customer timeline, available time; your delivery context, whether global delivery, field delivery or SME&C coverage, since it changes which next action is right.', N'A one-gap credibility plan with a first step and a date.', N'The CSA keeps this to one gap. A plan covering every gap is a plan that closes none of them before the customer needs the answer.', N'Synthesis and drafting', N'One closed gap before the customer needs it beats a broad plan that arrives after they asked.', N'https://m365.cloud.microsoft/cowork', N'Open Cowork'),
        (N'DAE-SIGNAL-SCOUT-01', N'WF-X-SIGNAL-01', N'DAE-SIGNAL', N'PH-DAE-SIGNAL-EXPL', 5, N'Be told a signal is expiring instead of finding out', N'Set a standing watch on the signal queue so the ones approaching expiry surface without anyone going to look.', N'Featured', N'Both', N'Watch my signal queue and tell me, on a schedule I set, which signals are approaching expiry, which have moved since the last check, and which have gone quiet after an initial response. Rank by how close they are to expiring and how warm the account looked. Carry forward what you told me last time so I can see what I acted on and what I let go.', N'1. Set the cadence to match how fast your queue turns over, not how often you would like to look.
2. Say what counts as approaching expiry for your motion.
3. Ask it to report movement since the last check rather than the whole queue.
4. Check the first run before you trust the second.
5. After two weeks, look at what you consistently let go and decide whether that is a judgment or a capacity problem.', N'Access to your signal queue, the expiry window that applies to your motion, and the cadence you want to be told on.', N'A standing watch on the signal queue reporting what is close to expiry and what has moved since the last check, rather than a one-time list.', N'The DAE decides which expiring signals are worth the contact. A queue ranked by expiry date tells you what runs out first, not what is worth pursuing, and working the queue in date order is how the good accounts get the least attention.', N'Monitoring and signal', N'A signal you find on the day it expires is a signal you have already lost. Being told earlier is the whole difference.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'DSS-SIGNAL-SCOUT-01', N'WF-X-SIGNAL-01', N'DSS-SIGNAL', N'PH-DSS-SIGNAL-EXPL', 5, N'Watch for the engagement that turns into real intent', N'Set a standing watch across your solution area so repeat engagement surfaces as it builds rather than after the window has closed.', N'Featured', N'Both', N'Watch engagement across the accounts in my solution area and tell me, on a schedule I set, where activity is repeating or building rather than one-off, where a signal has gone quiet after I responded, and where the same pattern is showing up across more than one account. Carry forward what you reported last time so I can see what built and what faded.', N'1. Set the cadence and the accounts in scope.
2. Say what repeat engagement looks like in your solution area.
3. Ask for what changed since the last check, not the full picture.
4. Review the first run before relying on it.
5. Use the cross-account patterns to decide where your solution area is actually landing.', N'The accounts in your solution area, access to the engagement signals for them, and the cadence you want to be told on.', N'A standing watch across the solution area showing where engagement is building, where it went quiet after a response, and the patterns appearing across more than one account.', N'The DSS decides what repeat engagement means. Activity that repeats can be a buying signal or one person doing their research, and the difference is not in the count.', N'Monitoring and signal', N'A pattern across several touches says something a single event does not, and watching for it by hand is the part that does not get done.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-X-CONV-01-P-ATS-NARR-JAI', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 4, N'Pressure-test the options and tradeoffs with an executive', N'Practice putting the real decision, its options and its tradeoffs to an executive.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the executive who has to make this decision. I will present the options and their tradeoffs rather than a recommendation. Push back where an option sounds like a pitch, where a tradeoff has been softened, or where what this executive is personally backing has not been named. Pause for my response before coaching me on whether the decision was put clearly and the tradeoffs stated honestly. Do not invent customer facts or commitments.', NULL, N'The approved narrative; the decision being asked for; the options and their tradeoffs; who the executive is and what they are accountable for.', N'A rehearsed decision conversation, the objections raised, and coaching on where an option was pitched rather than offered.', N'The ATS decides which tradeoffs are material enough to put in front of this executive. Review the downsides the rehearsal raises and add the material ones it missed, since not everything it raises bears on the decision being made.', N'Conversation rehearsal', N'An executive decision put badly sounds like a pitch. Rehearsing it is how you hear the difference before they do.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'CSAM-ESCALATE-JAI', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 5, N'Rehearse the escalation conversation before you have it', N'Practise telling a customer something has gone wrong, before the call.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the customer stakeholder I have to tell about this escalation. Use the approved status position, the validated escalation brief and the commitment boundaries I am pasting below, and ask me for anything missing before you begin. Play them as someone who is frustrated and wants a date I cannot yet give. Push back where I over-commit, where I soften the impact, or where I explain the cause instead of saying what happens next. Pause for my response before coaching me on whether I was clear about what is known, what is not, and when they will hear from me again. Do not invent facts about the incident.', NULL, N'The validated escalation brief; the stakeholder and what they care about; the approved communication position; what you cannot yet commit to.', N'A rehearsed escalation conversation, the objections raised, and coaching on where you over-committed or softened the impact.', N'The CSAM decides what can be said about cause and timing before the facts are settled. Rehearsal makes an answer fluent, and a fluent answer about an unresolved incident is easy to hear as a commitment.', N'Conversation rehearsal', N'How an escalation is handled shapes the relationship long after the incident closes. Rehearsing it is cheaper than improvising it while they are angry.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai')
    ) v([ExternalId], [TopicExternalId], [PlacementExternalId], [PhaseExternalId], [DisplayOrder], [Name], [Description], [PracticeTier], [ExecutionMethod], [Prompt], [ActivitySteps], [RequiredContext], [ExpectedOutput], [HumanCheckpoint], [BestFitJob], [WhyThisMatters], [LaunchUrl], [LaunchLabel])
)
SELECT @unresolved = 103 - COUNT(*) FROM raw
    INNER JOIN dbo.HuddleTopics AS t ON t.[ExternalId] = raw.[TopicExternalId]
    INNER JOIN dbo.HuddlePlacements AS p ON p.[ExternalId] = raw.[PlacementExternalId]
    INNER JOIN dbo.HuddlePhases AS ph ON ph.[ExternalId] = raw.[PhaseExternalId];
IF @unresolved <> 0
    THROW 51000, 'HuddleActivities (new): 103 source rows were expected to resolve their foreign keys but some did not. Run the earlier scripts in order and re-check the workbook.', 1;

COMMIT TRANSACTION;
GO
